decisionRoutes.get('/:tenant/decisions/snapshot', async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const visitorId = (c.req.query('visitorId') ?? '').trim().slice(0, 128);
  if (!visitorId) return c.json({ ok: false, error: 'visitorId required' }, 400);
  // A visitor id is a Durable Object name and a session key. One that starts with
  // the namespace marker would address another brand's namespace directly.
  if (visitorId.startsWith(NAMESPACE_MARKER)) return c.json({ ok: false, error: 'visitorId may not start with the namespace marker' }, 400);
  const page = ((c.req.query('page') ?? 'home').trim() || 'home').slice(0, 64);
  const brand = (c.req.query('brand') ?? '').trim() || undefined;
  const channel = (c.req.query('channel') ?? '').trim() || null;
  const sessionId = (c.req.query('sessionId') ?? '').trim().slice(0, 64) || null;
  const cf = ((c.req.raw as unknown as { cf?: unknown }).cf ?? null) as { country?: string; regionCode?: string } | null;

  // Two names, on purpose, until CW1 provisions tenants: the path names the SCOPE
  // the documents are read under; the tenancy middleware names the brand whose
  // shopper state and session this request belongs to.
  const out = await serveContentDecisions(c.env, {
    tenant, brand, page, visitorId, sessionId, channel, cf, cookieHeader: c.req.header('Cookie') ?? null,
    stateTenant: c.get('tenant'),
  });
  // Where the time went, for whoever is measuring: one Server-Timing entry per stage.
  c.header('Server-Timing', Object.entries(out.sources.timings).map(([k, v]) => `${k};dur=${v}`).join(', '));
  // Phase 0 and Phase 1, after the response, never on it: the ledger, the visitor's ring, each slot's exposures.
  // CW31: nothing at all when the shopper withheld tracking consent.
  const ledger = out.write ? enqueueDecisions(c.env, out.records) : Promise.resolve();
  try { c.executionCtx.waitUntil(ledger); c.executionCtx.waitUntil(out.afterResponse); } catch { void ledger; void out.afterResponse; }
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, ...out });
});

/**
 * GET /v1/:tenant/ledger/batches?date=YYYY-MM-DD[&stream=decision|outcome][&cursor=]
 * The export (doc 22 §12.4) is the R2 partition itself; this lists one day's
 * batch objects so a warehouse job knows what to fetch. Authenticated.
 * Registered before /ledger/:id so the literal segment wins.
 */
decisionRoutes.get('/:tenant/ledger/batches', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  const date = (c.req.query('date') ?? '').trim();
  if (!TENANT.test(tenant) || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return c.json({ ok: false, error: 'tenant slug and date=YYYY-MM-DD' }, 400);
  const stream = c.req.query('stream') === 'outcome' ? 'outcome' : c.req.query('stream') === 'decision' ? 'decision' : null;
  const cursor = (c.req.query('cursor') ?? '').trim() || undefined;
  const [listed, tombs] = await Promise.all([
    c.env.STORAGE.list({ prefix: `${tenant}/${date}/`, ...(cursor ? { cursor } : {}), limit: 1000 }),
    loadTombstones(c.env.STORAGE as unknown as R2Erasable, tenant),
  ]);
  const objects = listed.objects
    .filter((o) => !stream || o.key.includes(`/${stream}/`))
    .map((o) => ({ key: o.key, size: o.size, uploaded: o.uploaded instanceof Date ? o.uploaded.toISOString() : String(o.uploaded) }));
  c.header('Cache-Control', 'no-store');
  // CW28: a warehouse job applies the pending erasures to what it loads; the nightly rewrite makes the objects themselves clean.
  return c.json({ ok: true, tenant, date, stream: stream ?? 'both', objects, truncated: listed.truncated, ...(listed.truncated ? { cursor: listed.cursor } : {}), erasures: { pending: tombs.size, list: `/v1/${tenant}/ledger/erasures` } });
});

/**
 * CW28, the ledger half of erasure (doc 22 §15). GET lists the pending
 * tombstones so an export consumer can apply them at once; POST writes one for
 * a visitor and empties her ring (the identity route calls the same function
 * after erasing the profile); POST .../rewrite runs the scheduled rewrite now,
 * as the nightly cron does. All authenticated; the list carries visitor ids.
 * Registered before /ledger/:id so the literal segment wins.
 */
decisionRoutes.get('/:tenant/ledger/erasures', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const tombs = await loadTombstones(c.env.STORAGE as unknown as R2Erasable, tenant);
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, tenant, retentionDays: retentionDays(c.env), pending: [...tombs.values()].sort((a, b) => b.erased_at - a.erased_at) });
});
decisionRoutes.post('/:tenant/ledger/erasures', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const b = (await c.req.json().catch(() => null)) as { visitorId?: string } | null;
  const visitorId = (b?.visitorId ?? '').trim();
  if (!visitorId || visitorId.length > 200 || visitorId.startsWith(NAMESPACE_MARKER)) return c.json({ ok: false, error: 'visitorId required' }, 400);
  const actor = (c as unknown as { get: (k: 'auth') => AuthContext | undefined }).get('auth')?.user?.sub ?? 'operator';
  const res = await eraseVisitorLedger(c.env, tenant, visitorId, actor);
  c.header('Cache-Control', 'no-store');
  return c.json({ ...res, tenant });
});
decisionRoutes.post('/:tenant/ledger/erasures/rewrite', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const b = (await c.req.json().catch(() => ({}))) as { maxObjects?: number } | null;
  const maxObjects = typeof b?.maxObjects === 'number' && b.maxObjects > 0 ? Math.floor(b.maxObjects) : undefined;
  const result = await rewriteErasures(c.env.STORAGE as unknown as R2Erasable, tenant, { retentionDays: retentionDays(c.env), ...(maxObjects ? { maxObjects } : {}) });
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, ...result });
});

/**
 * GET /v1/:tenant/ledger/:id[?stream=outcome]
 * One record by id, straight from R2 with no index (doc 22 §3.4): the id names
 * the brand and the hour, the batch objects are named by the id range they hold.
 * Authenticated, because a record carries a visitor id. Behind by the queue lag
 * during a peak; exact afterwards.
 */
decisionRoutes.get('/:tenant/ledger/:id', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  const id = (c.req.param('id') ?? '').trim();
  if (!TENANT.test(tenant) || !id.startsWith(`${tenant}:`)) return c.json({ ok: false, error: 'id must belong to the tenant in the path' }, 400);
  const stream = c.req.query('stream') === 'outcome' ? 'outcome' : 'decision';
  const found = await findById<DecisionRecord | OutcomeRecord>(c.env.STORAGE as unknown as R2Like, id, stream);
  c.header('Cache-Control', 'no-store');
  if (!found) return c.json({ ok: false, error: 'not found, or not yet written by the consumer' }, 404);
  if (hidden(await loadTombstones(c.env.STORAGE as unknown as R2Erasable, tenant), found.record)) return c.json({ ok: false, error: 'erased at the visitor\'s request' }, 410);
  return c.json({ ok: true, stream, key: found.key, record: found.record });
});

/**
 * GET /v1/:tenant/replay/:id (doc 22 §12.3). Fetch the decision record, decide
 * again from the documents at the recorded revisions, the archived lift
 * snapshot and the inputs the record carries, and compare. Authenticated,
 * because the record carries a visitor id. Behind by the queue lag at a peak.
 */
decisionRoutes.get('/:tenant/replay/:id', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  const id = (c.req.param('id') ?? '').trim();
  if (!TENANT.test(tenant) || !id.startsWith(`${tenant}:`)) return c.json({ ok: false, error: 'id must belong to the tenant in the path' }, 400);
  const found = await findById<DecisionRecord>(c.env.STORAGE as unknown as R2Like, id, 'decision');
  c.header('Cache-Control', 'no-store');
  if (!found) return c.json({ ok: false, error: 'not found, or not yet written by the consumer' }, 404);
  if (hidden(await loadTombstones(c.env.STORAGE as unknown as R2Erasable, tenant), found.record)) return c.json({ ok: false, error: 'erased at the visitor\'s request' }, 410);
  const result = await replayDecision(c.env, found.record);
  return c.json({ ok: result.ok, equal: result.equal, ...(result.reason ? { reason: result.reason } : {}), used: result.used, diff: result.diff, key: found.key, served: result.served, replayed: result.replayed });
});

/**
 * POST /v1/:tenant/models/reference (doc 22 §9). The reference implementation
 * of the model contract, as a service a data science team can call to see the
 * shape, and point the `service` kind at by URL to see the term on a receipt.
 * Stateless; no visitor id crosses it.
 */
decisionRoutes.post('/:tenant/models/reference', async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const body = (await c.req.json().catch(() => null)) as Partial<ExternalRequest> | null;
  if (!body || typeof body !== 'object' || !Array.isArray(body.candidates)) return c.json({ ok: false, error: 'a contract request: affinity and candidates' }, 400);
  const req: ExternalRequest = {
    tenant, brand: typeof body.brand === 'string' ? body.brand : tenant, page: typeof body.page === 'string' ? body.page : '', slots: Array.isArray(body.slots) ? body.slots.map(String) : [],
    cell: (body.cell as ExternalRequest['cell']) ?? { channel: 'unknown', visit_bucket: 'unknown', region: null, affinity: null },
    affinity: body.affinity && typeof body.affinity === 'object' ? body.affinity : {},
    candidates: body.candidates.filter((x): x is ExternalRequest['candidates'][number] => Boolean(x) && typeof x === 'object' && typeof (x as { id?: unknown }).id === 'string').map((x) => ({ id: x.id, tags: x.tags && typeof x.tags === 'object' ? x.tags : {} })),
  };
  return c.json(referenceScore(req));
});

/** GET /v1/:tenant/lift/history?slot=[&brand=]: every archived snapshot version for the slot (doc 22 §12.2). */
decisionRoutes.get('/:tenant/lift/history', async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  const slot = (c.req.query('slot') ?? '').trim();
  if (!TENANT.test(tenant) || !slot) return c.json({ ok: false, error: 'tenant slug and slot' }, 400);
  const brand = (c.req.query('brand') ?? '').trim() || tenant;
  const prefix = `lift/${tenant}/${brand}/${slot}/`;
  const versions: Array<{ version: number; size: number; uploaded: string }> = [];
  let cursor: string | undefined;
  do {
    const page = await c.env.STORAGE.list({ prefix, ...(cursor ? { cursor } : {}), limit: 1000 });
    for (const o of page.objects) {
      const v = Number(o.key.slice(prefix.length).replace(/\.json$/, ''));
      if (v > 0) versions.push({ version: v, size: o.size, uploaded: o.uploaded instanceof Date ? o.uploaded.toISOString() : String(o.uploaded) });
    }
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  versions.sort((a, b) => b.version - a.version);
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, tenant, brand, slot, versions });
});

/**
 * POST /v1/:tenant/learn/items/reset (doc 22 §12.2): discard one item's evidence in one slot and start
 * again from the prior. The next snapshot publishes at once; the learn document gets a revision whose
 * content is unchanged and whose note records who reset what, so the audit trail shows it.
 */
decisionRoutes.post('/:tenant/learn/items/reset', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const b = (await c.req.json().catch(() => null)) as { slot?: string; item?: string; brand?: string } | null;
  if (!b?.slot || !b.item) return c.json({ ok: false, error: 'slot and item required' }, 400);
  const brand = (b.brand ?? '').trim() || tenant;
  if (!c.env.LEARN_STATS) return c.json({ ok: false, error: 'LEARN_STATS binding absent on this stamp' }, 503);
  const actor = (c as unknown as { get: (k: 'auth') => AuthContext | undefined }).get('auth')?.user?.sub ?? 'operator';
  const stub = c.env.LEARN_STATS.get(c.env.LEARN_STATS.idFromName(statsName(tenant, brand, b.slot)));
  const res = (await (await stub.fetch('https://learn/reset-item', { method: 'POST', body: JSON.stringify({ item: b.item }) })).json()) as { ok: boolean; had?: boolean };
  invalidateLiftCache();
  const current = await read<LearnConfig>(c.env, LEARN_KIND, tenant, DEFAULT_LEARN);
  const rev = await write(c.env, LEARN_KIND, tenant, current, { actor, note: `reset ${b.item} in ${b.slot}${brand !== tenant ? ` (${brand})` : ''}: evidence discarded by ${actor}, estimate restarts from the prior` });
  return c.json({ ok: res.ok, had: res.had ?? false, revision: rev.ok ? rev.revision.revision : null });
});

/**
 * POST /v1/:tenant/learn/publish { slot, brand? }: publish the slot's lift snapshot now, as the object's
 * alarm does within the minute. For an operator who has just changed a dial, and for the acceptance run.
 */
decisionRoutes.post('/:tenant/learn/publish', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const b = (await c.req.json().catch(() => null)) as { slot?: string; brand?: string } | null;
  if (!b?.slot) return c.json({ ok: false, error: 'slot required' }, 400);
  const brand = (b.brand ?? '').trim() || tenant;
  if (!c.env.LEARN_STATS) return c.json({ ok: false, error: 'LEARN_STATS binding absent on this stamp' }, 503);
  const stub = c.env.LEARN_STATS.get(c.env.LEARN_STATS.idFromName(statsName(tenant, brand, b.slot)));
  const res = (await (await stub.fetch('https://learn/publish', { method: 'POST' })).json()) as { ok: boolean; published?: boolean; snapshot?: unknown };
  invalidateLiftCache();
  c.header('Cache-Control', 'no-store');
  // The object answers with what it published, ahead of KV's cache; `published` is false when it has no evidence yet.
  return c.json({ ok: res.ok, tenant, brand, slot: b.slot, published: res.published ?? false, snapshot: res.snapshot ?? null });
});

/**
 * POST /v1/:tenant/learn/report (doc 22 §4.2, §7, §10): the day's ledger under the learning policy and
 * any reporting policies, side by side; what explored; the holdout arms. Body: { date, brand?, policies? }.
 * GET reads the last report built for the day. Aggregates only; no visitor id in the result.
 */
decisionRoutes.post('/:tenant/learn/report', jwt({ required: true }), async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  if (!TENANT.test(tenant)) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const b = (await c.req.json().catch(() => ({}))) as { date?: string; brand?: string; policies?: unknown };
  const date = (b.date ?? new Date().toISOString().slice(0, 10)).trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return c.json({ ok: false, error: 'date=YYYY-MM-DD' }, 400);
  const brand = (b.brand ?? '').trim() || tenant;
  const learn = await read<LearnConfig>(c.env, LEARN_KIND, tenant, DEFAULT_LEARN);
  let policies: ReportPolicy[] | null = null;
  if (Array.isArray(b.policies)) {
    policies = [];
    for (const p of b.policies as Array<Record<string, unknown>>) {
      const okScope = p.scope === 'session' || p.scope === 'visitor', okMatch = p.match === 'direct' || p.match === 'any', okCredit = p.credit === 'last' || p.credit === 'first';
      if (!p || typeof p.name !== 'string' || !okScope || !okMatch || !okCredit) return c.json({ ok: false, error: 'each policy: name, scope session|visitor, match direct|any, credit last|first, windowsMs?' }, 400);
      const windowsMs: Record<string, number> = {};
      if (p.windowsMs && typeof p.windowsMs === 'object') for (const [k, v] of Object.entries(p.windowsMs as Record<string, unknown>)) if (typeof v === 'number' && v > 0) windowsMs[k] = v;
      policies.push({ name: p.name.slice(0, 40), scope: p.scope as 'session' | 'visitor', match: p.match as 'direct' | 'any', credit: p.credit as 'last' | 'first', windowsMs: Object.keys(windowsMs).length ? windowsMs : learn.policy?.windowsMs ?? {} });
    }
  }
  // Doc 31 §3: the day is the sum of its hour aggregates; only custom policies, or a day from before the
  // fold existed, are computed from the records, and such a day must be one a request can read.
  c.header('Cache-Control', 'no-store');
  try {
    const report = await runDayReport(c.env.STORAGE as unknown as Parameters<typeof runDayReport>[0], { tenant, brand, date }, learn, policies, Date.now(), { maxObjects: REPORT_MAX_OBJECTS });
    return c.json({ ok: true, report });
  } catch (e) {
    if (e instanceof ReportTooLarge) return c.json({ ok: false, error: e.message, objects: e.objects, max: e.max }, 413);
    throw e;
  }
});
/**
 * CW34 (delivery lane, named in plan 21): the day reports over a window, pooled per
 * slot and arm and compared at the asked confidence against the pre-set targets.
 * Reads reports already built; a day without one is listed as missing.
 */
decisionRoutes.get('/:tenant/learn/report/window', async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  const from = (c.req.query('from') ?? '').trim();
  const to = (c.req.query('to') ?? '').trim();
  if (!TENANT.test(tenant) || !/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to)) return c.json({ ok: false, error: 'tenant slug, from=YYYY-MM-DD and to=YYYY-MM-DD' }, 400);
  const brand = (c.req.query('brand') ?? '').trim() || tenant;
  const conf = Number(c.req.query('confidence') ?? '0.95');
  const confidence = [0.9, 0.95, 0.99].includes(conf) ? conf : 0.95;
  const report = await windowReport(c.env.STORAGE as unknown as Parameters<typeof windowReport>[0], { tenant, brand, from, to }, { confidence });
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, report });
});
decisionRoutes.get('/:tenant/learn/report', async (c) => {
  const tenant = (c.req.param('tenant') ?? '').trim();
  const date = (c.req.query('date') ?? '').trim();
  if (!TENANT.test(tenant) || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return c.json({ ok: false, error: 'tenant slug and date=YYYY-MM-DD' }, 400);
  const brand = (c.req.query('brand') ?? '').trim() || tenant;
  let report: DayReport | null = null;
  try { const obj = await c.env.STORAGE.get(reportKey(tenant, brand, date)); report = obj ? ((await obj.json()) as DayReport) : null; } catch { report = null; }
  c.header('Cache-Control', 'no-store');
  return report ? c.json({ ok: true, report }) : c.json({ ok: false, error: 'no report built for that day yet' }, 404);
});

// src/routes/sort.ts
// ---------------------------------------------------------------------------
// POST /sort: custom product sort over a candidate set. Ledger 20 row 9,
// scope appendix §1.11.
//
// The commerce platform calls its search exactly as it does today, sends us the
// candidate ids with the attributes the registry reads, and gets the same ids
// back in a per-shopper order. Its front end renders. That is the whole
// contract, and it is the same one the content decisions already use: decisions
// by id, over the wire, the customer's system paints.
//
// The ranking itself lives in @/reflex/sortCandidates and is pure. This file
// resolves three things and hands them to it: which brand, which shopper
// vector, and which registry. The shopper vector is read exactly the way
// GET /realtime/reflex reads it, on both hosts, so a sort and a snapshot can
// never disagree about who the shopper is.
// ---------------------------------------------------------------------------

import { Hono } from 'hono';
import { z } from 'zod';
import type { Env } from '@/types/env';
import { getConnectors } from '@/connectors';
import { RealtimeSegmentEngine } from '@/services/RealtimeSegmentEngine';
import { resolveReflexConfig, resolveSurface } from '@/demos/registry';
import { snapshot } from '@/reflex/core';
import { sortCandidates, type AffinityDims, type Candidate } from '@/reflex/sortCandidates';
import { shopperObject } from '@/tenancy/objects';
import { DEFAULT_TENANT, type TenantVariables } from '@/tenancy/tenant';

export const sortRoutes = new Hono<{ Bindings: Env; Variables: TenantVariables }>();

/** Bounded, because a candidate set is a page of results and not a catalog. */
const MAX_CANDIDATES = 500;

const bodySchema = z.object({
  userId: z.string().trim().min(1).max(200),
  sessionId: z.string().optional(),
  surface: z.string().optional(),
  candidates: z.array(z.object({ id: z.string() }).passthrough()).max(MAX_CANDIDATES),
  weights: z.object({
    affinity: z.number().optional(),
    dims: z.record(z.string(), z.number()).optional(),
  }).optional(),
});

/**
 * The shopper's affinity vector, read the way GET /realtime/reflex reads it.
 * Null when the shopper has no state yet, which the sorter treats as "nothing
 * to personalize on": the platform's order stands.
 */
async function affinityFor(
  c: { env: Env; get: (k: 'tenant') => string; req: { header: (n: string) => string | undefined } },
  userId: string,
  surfaceHint: string | undefined,
): Promise<{ dims: AffinityDims; configVersion: string }> {
  const env = c.env;
  // Explicit fallback. If this router is ever mounted without the tenancy
  // middleware, every helper below would default to the default brand on its
  // own -- but silently, and the response would echo undefined. Saying it once
  // here makes the fallback visible where it can be seen.
  const tenant = c.get('tenant') ?? DEFAULT_TENANT;

  if ((env.REFLEX_HOST ?? 'session') === 'do') {
    const stub = shopperObject(env.SHOPPER_REFLEX, userId, tenant);
    const res = await stub.fetch('https://shopper-reflex/snapshot');
    const body = (await res.json()) as {
      affinity?: { dims?: AffinityDims } | null;
      config?: { version?: string };
    };
    const cfg = await resolveReflexConfig(env, resolveSurface({ surface: surfaceHint }));
    return { dims: body.affinity?.dims ?? {}, configVersion: cfg.version };
  }

  const engine = new RealtimeSegmentEngine(env, getConnectors(env), { tenant });
  const { sessionData } = await engine.getOrCreateSessionFromCookies(c.req.header('Cookie') ?? null, userId);
  const cfg = await resolveReflexConfig(env, resolveSurface({ surface: surfaceHint ?? sessionData.surface }));
  const dims = sessionData.reflex ? snapshot(sessionData.reflex, Date.now(), cfg).dims : {};
  return { dims, configVersion: cfg.version };
}

sortRoutes.post('/', async (c) => {
  const parsed = bodySchema.safeParse(await c.req.json().catch(() => null));
  if (!parsed.success) {
    return c.json({ ok: false, error: 'Invalid sort request', details: parsed.error.issues }, 400);
  }
  const { userId, surface, candidates, weights } = parsed.data;

  try {
    const { dims, configVersion } = await affinityFor(c, userId, surface);
    const cfg = await resolveReflexConfig(c.env, resolveSurface({ surface }));
    const result = sortCandidates(candidates as Candidate[], dims, cfg, weights);
    return c.json({
      ok: true,
      tenant: c.get('tenant') ?? DEFAULT_TENANT,
      configVersion,
      ...result,
    });
  } catch (error) {
    // A visitor id that addresses another brand's namespace lands here from
    // shopperObject(); it is refused, never served.
    const message = error instanceof Error ? error.message : 'sort failed';
    const status = /may not start with/.test(message) ? 400 : 500;
    return c.json({ ok: false, error: message }, status);
  }
});

// src/content/service.ts
// The decision service: everything decide.ts needs, resolved from where it lives,
// with the failure posture doc 22 §1 requires — a store or state read that fails
// produces a cold decision, never a failed request. Reads only. Nothing here
// writes a record; the ledger writer is Phase 0's and consumes `records` as is.

import type { Env } from '@/types/env';
import { readRevision } from '@/config/versionedStore';
import { readReflexConfigRevision } from '@/reflex/configStore';
import { DEFAULT_REFLEX_CONFIG, snapshot as reflexSnapshot, type AffinitySnapshot, type ReflexConfig } from '@/reflex/core';
import { RealtimeSegmentEngine } from '@/services/RealtimeSegmentEngine';
import { getConnectors } from '@/connectors';
import { DEFAULT_TENANT, type TenantId } from '@/tenancy/tenant';
import { shopperObject } from '@/tenancy/objects';
import { CONTENT_KIND, DEFAULT_LEARN, DEFAULT_SLOTS, EMPTY_CATALOG, LEARN_KIND, SLOTS_KIND } from './kinds';
import { armFor } from './holdout';
import { cellFor, type CfLike } from './cell';
import { armUnder, CONSENTING, consentOf, personalizes, type Consent } from './consent';
import { decideContent } from './decide';
import { blendAffinity, lambdaFor, readTrend, regionKeyOf } from '@/reflex/regionTrend';
import { fanDecisions, liftKey, readRing, servedCounts, type SlotLearnConfig } from '@/learn/fan';
import { DEFAULT_STATS, type LiftSnapshot } from '@/learn/stats';
import type { ExternalTerm } from './types';
import type { ContentDecisionSet } from './types';

export interface ServeRequest {
  tenant: string;
  brand?: string;
  page: string;
  visitorId: string;
  cookieHeader: string | null;
  /** The client's browsing session, when the SDK sends one: what the decision's session_id carries, so an outcome from the same client compares equal. */
  sessionId?: string | null;
  cf?: CfLike | null;
  channel?: string | null;
  nowMs?: number;
  /** The brand whose shopper state this request reads, as the tenancy middleware resolved it. */
  stateTenant?: TenantId;
}

/** Where each input came from, so a reader can tell a tuned scope from a compiled default. */
/** The lift snapshots the decision path reads: KV through a per-isolate cache, never the object. */
const LIFT_TTL_MS = 60_000;
const liftCache = new Map<string, { at: number; value: LiftSnapshot | null }>();
export function invalidateLiftCache(): void { liftCache.clear(); }
async function readLift(env: Pick<Env, 'CACHE'>, tenant: string, brand: string, slot: string, now: number): Promise<LiftSnapshot | null> {
  const key = liftKey(tenant, brand, slot);
  const hit = liftCache.get(key);
  if (hit && now - hit.at < LIFT_TTL_MS) return hit.value;
  let value: LiftSnapshot | null = null;
  try { value = (await env.CACHE.get(key, 'json')) as LiftSnapshot | null; } catch { value = null; }
  liftCache.set(key, { at: now, value });
  return value;
}

/** What each slot learns against: its reward and the estimator's constants, from the learn document. */
export function slotLearnConfigOf(learn: { stats?: SlotLearnConfig['stats']; slots?: Record<string, { reward?: SlotLearnConfig['reward'] }> }): (slot: string) => SlotLearnConfig {
  const stats = learn.stats ?? DEFAULT_STATS;
  return (slot) => ({ reward: learn.slots?.[slot]?.reward ?? 'click', stats, objective: (learn.slots?.[slot] as { objective?: 'unit' | 'revenue' | 'margin' } | undefined)?.objective ?? 'unit' });
}

export interface DecisionSources {
  catalog: { version: string | null; revision: number; pieces: number };
  slots: { version: string | null; revision: number; count: number };
  learn: { version: string | null; revision: number };
  config: { label: string; revision: number };
  /** Phase 3 (doc 22 §9): their model's answer for this page, when a slot on it weights one. */
  external: { kind: string; ref: string; ok: boolean; ms: number; version: string | null; reason: string | null } | null;
  state: 'do' | 'session' | 'none';
  /** CW31: the shopper's consent switches as the host reported them, and whether the engine personalized at all. */
  consent: Consent & { personalized: boolean };
  /** Milliseconds per stage of this decision: documents, shopper, trend, lift, decide. */
  timings: Record<string, number>;
}

interface ShopperRead {
  affinity: AffinitySnapshot | null;
  sessionId: string | null;
  isNewSession: boolean | null;
  state: DecisionSources['state'];
  /** CW29: the journey stage the engine last derived for this shopper, from whichever host holds it; null when none. */
  stage: string | null;
  /** CW31: the shopper's two consent switches, from whichever host holds them; a host that says nothing is consenting. */
  consent: Consent;
}

/**
 * The shopper's live affinity, from whichever host holds it. Mirrors the two
 * branches of GET /realtime/reflex so the decision reads the same state the
 * instrument shows. A read failure is a cold shopper, not an error.
 */
async function readShopper(
  env: Env, visitorId: string, cookieHeader: string | null, cfg: ReflexConfig, now: number, tenant: TenantId,
  /** CW37: where the session write goes, so it is not on the decision's path. */
  defer?: (p: Promise<unknown>) => void,
  /** CW39: the browsing session the client sent, which names the session it creates. */
  clientSessionId?: string | null,
): Promise<ShopperRead> {
  if ((env.REFLEX_HOST ?? 'session') === 'do') {
    try {
      // The brand's object for this visitor; the default brand keeps the bare name.
      const stub = shopperObject(env.SHOPPER_REFLEX, visitorId, tenant);
      const res = await stub.fetch('https://shopper-reflex/snapshot');
      const body = (await res.json()) as { affinity?: AffinitySnapshot | null; journeyStage?: string | null; consent?: { tracking?: unknown; personalization?: unknown } | null };
      return { affinity: body.affinity ?? null, sessionId: null, isNewSession: null, state: 'do', stage: body.journeyStage ?? null, consent: consentOf({ consent: body.consent }) };
    } catch {
      return { affinity: null, sessionId: null, isNewSession: null, state: 'none', stage: null, consent: CONSENTING };
    }
  }
  try {
    const engine = new RealtimeSegmentEngine(env, getConnectors(env), { tenant });
    const { sessionId, sessionData, isNewSession } = await engine.getOrCreateSessionFromCookies(cookieHeader, visitorId, defer, clientSessionId ?? undefined);
    return {
      affinity: sessionData.reflex ? reflexSnapshot(sessionData.reflex, now, cfg) : null,
      sessionId, isNewSession, state: 'session',
      stage: sessionData.metadata?.journeyStage ?? null,
      consent: consentOf({ preferences: sessionData.preferences }),
    };
  } catch {
    return { affinity: null, sessionId: null, isNewSession: null, state: 'none', stage: null, consent: CONSENTING };
  }
}

export async function serveContentDecisions(
  env: Env, r: ServeRequest,
): Promise<ContentDecisionSet & { sources: DecisionSources; afterResponse: Promise<void>; /** CW31: false when tracking is withheld, and nothing about this request may be written. */ write: boolean }> {
  const now = r.nowMs ?? Date.now();
  const scope = r.tenant;
  const brand = r.brand ?? r.tenant;
  // Where the time goes, in milliseconds per stage, on the answer and on the Server-Timing header.
  const timings: Record<string, number> = {};
  let mark = performance.now();
  const lap = (name: string) => { const t = performance.now(); timings[name] = Math.round(t - mark); mark = t; };

  const [catalogRev, slotsRev, learnRev, cfgRev] = await Promise.all([
    readRevision(env, CONTENT_KIND, scope, now),
    readRevision(env, SLOTS_KIND, scope, now),
    readRevision(env, LEARN_KIND, scope, now),
    readReflexConfigRevision(env, scope, now),
  ]);
  const catalog = catalogRev?.value ?? EMPTY_CATALOG;
  const slotsDoc = slotsRev?.value ?? DEFAULT_SLOTS;
  const learn = learnRev?.value ?? DEFAULT_LEARN;
  const cfg = cfgRev?.config ?? DEFAULT_REFLEX_CONFIG;
  const configRevision = cfgRev?.revision ?? 0;
  lap('documents');

  // CW37 (doc 32 §4 item 1). Creating a shopper's session is two KV writes, and
  // doc 32 measured them as effectively the whole of a new shopper's 627 ms. The
  // decision does not depend on them having landed -- it is computed from the
  // record the call returns -- so they are collected here and handed to the
  // caller's waitUntil with the rest of the after-response work.
  const sessionWrites: Promise<unknown>[] = [];
  const shopper = await readShopper(env, r.visitorId, r.cookieHeader, cfg, now, r.stateTenant ?? DEFAULT_TENANT,
    (p) => { sessionWrites.push(p); }, r.sessionId);
  lap('shopper');
  const cell = cellFor({
    cf: r.cf, snap: shopper.affinity, cfg, channel: r.channel,
    // Only a session boundary the engine itself observed counts as evidence of
    // a first visit; anything else is unknown until CW7 gives visit number real semantics.
    visitNumber: shopper.isNewSession === true ? 1 : null,
    // CW29: the stage the host last derived; `cellFor` records anything else as unknown.
    stage: shopper.stage,
  });
  // CW31: either consent switch off means the site's own defaults, whatever the holdout hash says.
  const consent = shopper.consent;
  const arm = armUnder(consent, armFor(r.visitorId, { ...learn.holdout, salt: learn.holdout.salt || brand }));
  const slots = slotsDoc.pages[r.page] ?? [];

  // CW6: the population prior. Read from KV through the isolate cache, never
  // from the object; blended into a COPY of the affinity view. Off for the
  // holdout's default arm, since defaults are the point of that arm.
  const regionalCfg = learn.regional ?? { enabled: false, kBlend: 1, minEvents: 30 };
  let affinity: { dims: Record<string, Record<string, number>> } | null = shopper.affinity;
  let regional: Parameters<typeof decideContent>[0]['regional'] = null;
  if (regionalCfg.enabled && arm !== 'default') {
    const trend = await readTrend(env, scope, regionKeyOf(r.cf), regionalCfg.minEvents, now);
    if (trend) {
      const lambda = lambdaFor(shopper.affinity?.dims, regionalCfg.kBlend);
      const blended = blendAffinity(shopper.affinity?.dims, trend.snapshot.share, lambda);
      affinity = { dims: blended.dims };
      regional = { region: trend.region, level: trend.level, lambda, version: trend.snapshot.version, events: trend.snapshot.events, share: trend.snapshot.share };
    }
  }

  lap('trend');
  // What the state hung on: the DO host keys it on the durable visitor id, the
  // session host on the cookie, and a failed read on nothing at all.
  const identityAnchor = shopper.state === 'do' ? 'visitor' : shopper.state === 'session' ? 'session' : 'none';

  // W34.01: external scoring is withdrawn from live decisions, including table
  // lookup. Stored settings cannot authorize runtime inference or external work.
  // Keep the omission explicit on weighted receipts and replayable from them.
  const extCfg = learn.external ?? null;
  const extWeightOf = (slot: string) => learn.slots?.[slot]?.external?.weight ?? 0;
  const wantsExt = extCfg !== null && arm !== 'default' && slots.some((s) => extWeightOf(s.slot) > 0);
  const external: ExternalTerm | null = wantsExt && extCfg
    ? { kind: extCfg.kind, ref: extCfg.ref, weightOf: extWeightOf, status: 'unavailable', reason: 'external scoring disabled by deployment policy' }
    : null;

  // Phase 1: the lift snapshot per slot, and the trust dial. Shadow by default.
  const snapshots: Record<string, LiftSnapshot | null> = {};
  // CW30: the visitor's ring, only when a slot on the page has a fatigue dial, never for the default arm, under a time budget.
  const wantsRing = arm !== 'default' && slots.some((s) => (s.fatigue?.weight ?? 0) > 0);
  const [ring] = await Promise.all([wantsRing ? readRing(env, r.tenant, r.visitorId) : Promise.resolve(null), ...slots.map(async (s) => { snapshots[s.slot] = await readLift(env, scope, brand, s.slot, now); })]);
  const served = ring ? servedCounts(ring, slots, now) : null;
  lap('lift');
  const gammaOf = (slot: string) => learn.slots?.[slot]?.gamma ?? 0;
  const exploreOf = (slot: string) => learn.slots?.[slot]?.exploration ?? null;
  const controlOf = (slot: string, item: string) => learn.slots?.[slot]?.items?.[item] ?? null;

  const set = decideContent({
    tenant: r.tenant, brand, page: r.page, visitorId: r.visitorId, sessionId: r.sessionId || shopper.sessionId, identityAnchor, nowMs: now,
    pieces: catalog.pieces, slots, affinity, regional, cell, arm,
    versions: { config: configRevision, catalog: catalogRev?.revision ?? 0, slots: slotsRev?.revision ?? 0, learn: learnRev?.revision ?? 0, lift: 0, prior: 0, policy: learnRev?.revision ?? 0 },
    configLabel: cfg.version,
    learning: { snapshots, gammaOf, exploreOf, controlOf },
    external,
    served,
  });

  lap('decide');
  // CW31: a shopper who declined personalization sees why on every receipt.
  if (!personalizes(consent)) for (const rec of set.records) rec.explain.note = 'the site\'s defaults: personalization is off by the shopper\'s choice';
  // After the response: the visitor's ring and each slot's exposures. Never awaited here.
  // CW31: with tracking withheld the engine writes nothing about this request, here or in the ledger (`write`).
  const afterResponse = Promise.all([
    // The session write, off the response path but still before the request ends.
    Promise.all(sessionWrites).catch(() => undefined),
    consent.tracking ? fanDecisions(env, set, slotLearnConfigOf(learn)) : Promise.resolve(),
  ]).then(() => undefined);

  return {
    ...set,
    afterResponse,
    write: consent.tracking,
    sources: {
      catalog: { version: catalog.version ?? null, revision: catalogRev?.revision ?? 0, pieces: catalog.pieces.length },
      slots: { version: slotsDoc.version ?? null, revision: slotsRev?.revision ?? 0, count: slots.length },
      learn: { version: learn.version ?? null, revision: learnRev?.revision ?? 0 },
      config: { label: cfg.version, revision: configRevision },
      external: external ? { kind: external.kind, ref: external.ref, ok: false, ms: 0, version: null, reason: external.reason } : null,
      state: shopper.state,
      consent: { ...consent, personalized: personalizes(consent) },
      timings,
    },
  };
}

import type { Env } from '@/types/env';
import type { ReflexChanges, ReflexConfig, ReflexState } from '@/reflex/core';
import { mergeReflexStates } from '@/reflex/identityMerge';
import { z } from 'zod';

import {
  classifyEntryChannel, isNewVisit, nextVisitCount,
  type ChannelSignals, type EntryChannel,
} from '@/services/visit';
import { DEFAULT_TENANT, TenantKV, type KVLike, type TenantId } from '@/tenancy/tenant';

export interface SessionData {
  userId: string;
  anonymousId?: string;
  segments: string[];
  attributes: Record<string, any>;
  /** Demo surface this session belongs to (@/demos/registry). ABSENT ⇒ 'coach' —
      every session written before the multi-surface split is the retail demo's. */
  surface?: string;
  /** Edge Affinity Reflex state (doc 16) — raw (R, tLast) per dimension·value.
      P0 hosting: rides the session; relocates into the ShopperReflex DO in P2. */
  reflex?: ReflexState;
  /** ODP loop (doc 16 §8): the session's last-seeded qualified ODP audiences + when. */
  odpSeed?: string[];
  odpSeedAt?: number;
  /** Ring of the session's recent events in the FLAT recent_events shape (≤10, ≤55min)
      — injected inline into the GraphQL read for instant (~200ms) qualification. */
  odpRecentEvents?: Array<Record<string, unknown>>;
  /**
   * CW25. Set on a record whose visitor was linked to a person: reads and
   * writes addressed to this session land on the person's session instead. The
   * record keeps its old content underneath, so if the target ever expires the
   * browser still has what it had. One hop, never chained.
   */
  forwardTo?: string;
  /**
   * CW25. Present on the PERSON's session. Its userId is the shopper id, and a
   * write arriving with a browser's visitor id must not overwrite it, or the
   * ODP vuid and the identity anchor would flap between devices.
   */
  identity?: { shopperId: string; linkedAt: number };
  metadata: {
    firstSeen: number;
    lastSeen: number;
    /**
     * Interactions, NOT visits. It increments on every createOrUpdateSession
     * call, which is what it has always done; the name is misleading and the
     * field is kept because it is persisted and read. For "how many times has
     * this shopper been here", use visitCount.
     */
    sessionCount: number;
    /**
     * Visits, counted on an idle-gap boundary (see @/services/visit). Optional
     * because records written before this field existed must still parse:
     * getSession() runs the schema and swallows a failure as null, so a required
     * field here would silently wipe every live session on deploy.
     */
    visitCount?: number;
    /** When the current visit began. */
    lastVisitAt?: number;
    /** How this visit was entered. Classified once per visit, then carried. */
    entryChannel?: EntryChannel;
    engagementScore: number;
    lastSegmentUpdate: number;
    journeyStage?: 'early' | 'mid' | 'late';
  };
  preferences: {
    trackingConsent: boolean;
    personalizationEnabled: boolean;
    cookieConsent: boolean;
  };
}

export interface CookieConfig {
  name: string;
  value: string;
  maxAge?: number;
  httpOnly?: boolean;
  secure?: boolean;
  sameSite?: 'Strict' | 'Lax' | 'None';
  domain?: string;
  path?: string;
}

export interface SessionCookies {
  sessionId: string;
  segments: string;
  userId?: string;
  anonymousId?: string;
  engagementScore: string;
  lastUpdate: string;
  trackingConsent: string;
  personalizationEnabled: string;
}

const sessionDataSchema = z.object({
  userId: z.string(),
  anonymousId: z.string().optional(),
  segments: z.array(z.string()),
  attributes: z.record(z.string(), z.any()),
  // Declared or .parse() silently STRIPS it on every read/write (same trap as reflex).
  surface: z.string().optional(),
  // Reflex state must be declared or .parse() silently STRIPS it on every read/write.
  reflex: z.any().optional(),
  odpSeed: z.array(z.string()).optional(),
  odpSeedAt: z.number().optional(),
  odpRecentEvents: z.array(z.any()).optional(),
  // CW25. Declared or .parse() silently STRIPS them, same trap as reflex.
  forwardTo: z.string().optional(),
  identity: z.object({ shopperId: z.string(), linkedAt: z.number() }).optional(),
  metadata: z.object({
    firstSeen: z.number(),
    lastSeen: z.number(),
    sessionCount: z.number(),
    // Optional, deliberately: see the note on the interface above. A required
    // field would fail .parse() on every record written before this deploy, and
    // getSession() turns a parse failure into null.
    visitCount: z.number().optional(),
    lastVisitAt: z.number().optional(),
    // An enum, so the parsed type matches the interface, with .catch so an
    // unrecognised stored value degrades to undefined instead of failing the
    // parse and taking the whole session with it.
    entryChannel: z
      .enum(['direct', 'paid_social', 'paid_search', 'email', 'organic', 'referral'])
      .optional()
      .catch(undefined),
    engagementScore: z.number(),
    lastSegmentUpdate: z.number(),
    journeyStage: z.enum(['early', 'mid', 'late']).optional()
  }),
  preferences: z.object({
    trackingConsent: z.boolean(),
    personalizationEnabled: z.boolean(),
    cookieConsent: z.boolean()
  })
});

/**
 * CW25. Attributes that count events, which add across a person's devices. The
 * names are RETAIL_SIGNAL_DEFAULTS' (RealtimeSegmentEngine); anything not here
 * is a latest-value attribute, on which the person's record wins.
 */
/** How often a forwarding record has its TTL renewed under a browser that keeps using it. */
const FORWARD_REFRESH_MS = 24 * 60 * 60 * 1000;

const COUNTER_ATTRIBUTES = new Set(['product_views', 'cart_adds', 'wishlist_adds', 'page_views', 'category_dwell_ms', 'purchases']);

export class SessionManager {
  private env: Env;
  readonly tenant: TenantId;
  private sessionTTL: number = 30 * 24 * 60 * 60; // 30 days in seconds
  private cookieDomain: string;
  private isSecure: boolean;

  /**
   * Sessions scoped to one brand (CW1). A visitor on Kate Spade and a visitor on
   * Coach who happen to share a session id are two different people, and without
   * this they were one: `session:{id}` was a global key.
   *
   * The default tenant is unprefixed, so an existing `new SessionManager(env)`
   * reads and writes exactly the keys it always did and no live session moves.
   */
  private readonly kv: KVLike;

  constructor(env: Env, options?: { domain?: string; secure?: boolean; tenant?: TenantId }) {
    this.env = env;
    this.tenant = options?.tenant ?? DEFAULT_TENANT;
    this.kv = new TenantKV(env.SESSIONS as unknown as KVLike, this.tenant);
    this.cookieDomain = options?.domain || '';
    this.isSecure = options?.secure ?? true;
  }

  /**
   * Create a new session or update existing one
   */
  async createOrUpdateSession(
    sessionId: string,
    userId: string,
    data: Partial<SessionData>,
    /**
     * How this request arrived: utm tags and referrer. Only consulted when this
     * call opens a new visit, because entry is a property of the visit and not
     * of every event inside it. Optional, so no existing call site changes.
     */
    entry?: ChannelSignals,
    /**
     * CW37. Where the KV writes go instead of being awaited. A decision does not
     * depend on the session having been STORED -- it is computed from the record
     * this call returns -- and a KV write costs half a second or more from a
     * Worker, which doc 32 measured as the whole of a new shopper's 627 ms. Hand
     * this a sink (the request's `waitUntil`) and the write leaves the response
     * path. Omit it and nothing changes: every existing caller still awaits.
     */
    defer?: (p: Promise<unknown>) => void,
  ): Promise<SessionData> {
    try {
      // CW25. A browser that was linked to a person writes to the person's
      // session; the id on the cookie stays what it was, the record it names
      // forwards. Resolved once here, for the read below and the write at the end.
      const target = await this.resolveRecord(sessionId);
      sessionId = target.id;
      const existingSession = target.data;
      // A person's session keeps the person's id whatever browser is writing.
      if (existingSession?.identity && existingSession.userId !== userId) userId = existingSession.userId;

      const now = Date.now();

      // THE VISIT BOUNDARY. Read lastSeen from the STORED record, never from the
      // incoming data: a caller that passes `metadata.lastSeen: Date.now()` would
      // otherwise close the gap it is being measured against, and every event
      // would look like a new visit.
      const priorLastSeen = existingSession?.metadata.lastSeen;
      const openingNewVisit = isNewVisit(priorLastSeen, now);
      const visitCount = nextVisitCount(existingSession?.metadata.visitCount, priorLastSeen, now);
      // A record written before visitCount existed resolves to visit 1. That
      // under-counts a returning shopper once, which is honest; seeding from
      // sessionCount would import its wrongness instead.
      const entryChannel: EntryChannel = openingNewVisit && entry
        ? classifyEntryChannel(entry)
        : (existingSession?.metadata.entryChannel ?? (entry ? classifyEntryChannel(entry) : 'direct'));

      const sessionData: SessionData = {
        userId,
        anonymousId: data.anonymousId || existingSession?.anonymousId,
        segments: data.segments || existingSession?.segments || ['new_user'],
        attributes: {
          ...existingSession?.attributes,
          ...data.attributes
        },
        surface: data.surface ?? existingSession?.surface,
        reflex: data.reflex ?? existingSession?.reflex,
        odpSeed: data.odpSeed ?? existingSession?.odpSeed,
        odpSeedAt: data.odpSeedAt ?? existingSession?.odpSeedAt,
        odpRecentEvents: data.odpRecentEvents ?? existingSession?.odpRecentEvents,
        identity: data.identity ?? existingSession?.identity,
        metadata: {
          firstSeen: existingSession?.metadata.firstSeen || now,
          lastSeen: now,
          sessionCount: existingSession ? existingSession.metadata.sessionCount + 1 : 1,
          visitCount,
          lastVisitAt: openingNewVisit ? now : (existingSession?.metadata.lastVisitAt ?? now),
          entryChannel,
          engagementScore: data.metadata?.engagementScore || existingSession?.metadata.engagementScore || 0,
          lastSegmentUpdate: data.segments ? now : existingSession?.metadata.lastSegmentUpdate || now,
          journeyStage: data.metadata?.journeyStage ?? existingSession?.metadata.journeyStage
        },
        preferences: {
          trackingConsent: data.preferences?.trackingConsent ?? existingSession?.preferences.trackingConsent ?? true,
          personalizationEnabled: data.preferences?.personalizationEnabled ?? existingSession?.preferences.personalizationEnabled ?? true,
          cookieConsent: data.preferences?.cookieConsent ?? existingSession?.preferences.cookieConsent ?? true
        }
      };

      // Validate the session data
      const validatedData = sessionDataSchema.parse(sessionData);

      // CW31 (BTIE D10). A shopper who withheld tracking consent is still
      // ANSWERED, from the state that is already stored, and nothing this
      // request learned is kept. This is the object host's rule exactly
      // (ShopperReflex step 8, where the record is restored to what it was):
      // the two hosts must never disagree about the same shopper, because
      // REFLEX_HOST decides which one a brand runs on and consent is not a
      // property of that choice.
      //
      // The one write that still happens is the INSTRUCTION itself. Without it
      // the next request reads no stored preference, the default of that is
      // consenting, and the engine would start writing again on the request
      // after the shopper asked it to stop.
      if (!validatedData.preferences.trackingConsent) {
        const onlyTheInstruction = sessionDataSchema.parse(
          existingSession
            ? { ...existingSession, preferences: validatedData.preferences }
            : {
                userId,
                segments: [],
                attributes: {},
                metadata: { firstSeen: now, lastSeen: now, sessionCount: 0, engagementScore: 0, lastSegmentUpdate: now },
                preferences: validatedData.preferences,
              }
        );
        // The pointer stays, or the switches could not be found again.
        const refusal = Promise.all([
          this.kv.put(`session:${sessionId}`, JSON.stringify(onlyTheInstruction), { expirationTtl: this.sessionTTL }),
          this.kv.put(`user:${userId}`, sessionId, { expirationTtl: this.sessionTTL }),
        ]);
        if (defer) defer(refusal); else await refusal;
        return validatedData;
      }

      // The record, and the pointer that finds it by user id. These were two
      // awaits in sequence, which paid for two round trips where one would do;
      // neither depends on the other.
      const writes = Promise.all([
        this.kv.put(`session:${sessionId}`, JSON.stringify(validatedData), { expirationTtl: this.sessionTTL }),
        this.kv.put(`user:${userId}`, sessionId, { expirationTtl: this.sessionTTL }),
      ]);
      if (defer) defer(writes); else await writes;

      return validatedData;

    } catch (error) {
      console.error('Error creating/updating session');
      throw error;
    }
  }

  /** The record exactly as stored, forward and all. */
  async readRaw(sessionId: string): Promise<SessionData | null> {
    try {
      const sessionData = await this.kv.get(`session:${sessionId}`, 'json');
      if (!sessionData) return null;
      return sessionDataSchema.parse(sessionData);
    } catch (error) {
      console.error('Error retrieving session');
      return null;
    }
  }

  /**
   * The session a request for `sessionId` actually lands on: the record itself,
   * or the person's session it forwards to. One hop. If the target has expired
   * the browser's own record is returned, which is what it had before the link.
   */
  async resolveRecord(sessionId: string): Promise<{ id: string; data: SessionData | null }> {
    const raw = await this.readRaw(sessionId);
    if (raw?.forwardTo && raw.forwardTo !== sessionId) {
      const target = await this.readRaw(raw.forwardTo);
      if (target) {
        // The browser's record and its `user:` pointer are never rewritten by
        // the writes that now land on the person, so they would expire under a
        // browser that kept coming back. Refreshed once a day, off the hot path.
        const now = Date.now();
        if (now - raw.metadata.lastSeen > FORWARD_REFRESH_MS) {
          const refreshed = { ...raw, metadata: { ...raw.metadata, lastSeen: now } };
          await Promise.all([
            this.kv.put(`session:${sessionId}`, JSON.stringify(refreshed), { expirationTtl: this.sessionTTL }),
            this.kv.put(`user:${raw.userId}`, raw.forwardTo, { expirationTtl: this.sessionTTL }),
          ]);
        }
        return { id: raw.forwardTo, data: target };
      }
    }
    return { id: sessionId, data: raw };
  }

  /**
   * Get session data by session ID. Follows a link (CW25), so a browser that
   * was recognised reads the person's profile from its old cookie.
   */
  async getSession(sessionId: string): Promise<SessionData | null> {
    return (await this.resolveRecord(sessionId)).data;
  }

  /**
   * CW25. Fold a browser's session into a person's, and leave the browser's
   * record forwarding there.
   *
   * The person's session is `user:{shopperId}`'s, created here on the first
   * link. The reflex vectors merge on the decay invariant (identityMerge.ts);
   * visits add, because two devices' visits are one person's visits; first seen
   * is the earliest, last seen the latest, the counters sum, and on anything
   * else the person's existing record wins over the browser's. Segments are
   * unioned and the reflex memberships re-evaluated, so the returned changes
   * are exactly what the link did to this person's audiences.
   */
  async absorbIntoShopper(input: {
    shopperId: string;
    /** The browser being linked. Its `user:` key is pointed at the person even when it had no session yet. */
    visitorId?: string;
    from: SessionData | null;
    fromSessionId: string | null;
    config: ReflexConfig;
    now?: number;
    /**
     * `merge` folds the browser's profile in (a first link). `repoint` only moves
     * the browser: it was linked to someone else before, its profile already
     * went there, and a shared computer's second account must not inherit it.
     */
    mode?: 'merge' | 'repoint';
  }): Promise<{ sessionId: string; data: SessionData; changes: ReflexChanges; created: boolean }> {
    const now = input.now ?? Date.now();
    const { shopperId } = input;
    const browserId = input.visitorId ?? input.from?.userId;
    // THE GUARD. Only a browser's own record is ever folded or forwarded: one
    // that carries no identity and is named by the browser being linked. A
    // person's session handed in here by mistake (the `user:` key of a linked
    // browser points at the person, not the browser) must never be forwarded to
    // another person, which would hand one shopper's profile to another.
    const from = input.from && !input.from.identity && input.from.userId === browserId ? input.from : null;

    let canonicalId = (await this.kv.get(`user:${shopperId}`)) as string | null;
    let base: SessionData | null = canonicalId ? await this.readRaw(canonicalId) : null;
    const created = !base;
    if (!base) canonicalId = this.generateSessionId();
    // A browser already forwarding here, or one being repointed, has nothing to fold in.
    const fold = input.mode !== 'repoint' && from && from.forwardTo !== canonicalId && from.userId !== shopperId ? from : null;

    const merged = mergeReflexStates(base?.reflex, fold?.reflex, now, input.config);
    const counters: Record<string, unknown> = { ...(fold?.attributes ?? {}), ...(base?.attributes ?? {}) };
    for (const k of Object.keys(fold?.attributes ?? {})) {
      const a = base?.attributes?.[k]; const b = fold?.attributes?.[k];
      if (typeof a === 'number' && typeof b === 'number' && COUNTER_ATTRIBUTES.has(k)) counters[k] = a + b;
    }
    const laterVisit = (fold?.metadata.lastVisitAt ?? 0) > (base?.metadata.lastVisitAt ?? 0) ? fold : base;

    const data: SessionData = {
      userId: shopperId,
      anonymousId: base?.anonymousId ?? fold?.anonymousId,
      segments: [...new Set([...(base?.segments ?? []), ...(fold?.segments ?? []), ...merged.state.audiences])].sort(),
      attributes: counters,
      surface: base?.surface ?? fold?.surface,
      reflex: merged.state,
      odpSeed: base?.odpSeed ?? fold?.odpSeed,
      odpSeedAt: base?.odpSeedAt ?? fold?.odpSeedAt,
      odpRecentEvents: [...(fold?.odpRecentEvents ?? []), ...(base?.odpRecentEvents ?? [])].slice(-10),
      identity: base?.identity ?? { shopperId, linkedAt: now },
      metadata: {
        firstSeen: Math.min(base?.metadata.firstSeen ?? now, fold?.metadata.firstSeen ?? now),
        lastSeen: Math.max(base?.metadata.lastSeen ?? 0, fold?.metadata.lastSeen ?? 0) || now,
        sessionCount: (base?.metadata.sessionCount ?? 0) + (fold?.metadata.sessionCount ?? 0),
        visitCount: (base?.metadata.visitCount ?? 0) + (fold?.metadata.visitCount ?? 0) || undefined,
        lastVisitAt: laterVisit?.metadata.lastVisitAt,
        entryChannel: laterVisit?.metadata.entryChannel,
        engagementScore: Math.max(base?.metadata.engagementScore ?? 0, fold?.metadata.engagementScore ?? 0),
        lastSegmentUpdate: now,
        journeyStage: base?.metadata.journeyStage ?? fold?.metadata.journeyStage,
      },
      preferences: base?.preferences ?? fold?.preferences ?? { trackingConsent: true, personalizationEnabled: true, cookieConsent: true },
    };
    const validated = sessionDataSchema.parse(data);

    await this.kv.put(`session:${canonicalId}`, JSON.stringify(validated), { expirationTtl: this.sessionTTL });
    await this.kv.put(`user:${shopperId}`, canonicalId!, { expirationTtl: this.sessionTTL });
    if (browserId && browserId !== shopperId) {
      await this.kv.put(`user:${browserId}`, canonicalId!, { expirationTtl: this.sessionTTL });
    }
    if (from) {
      if (input.fromSessionId && input.fromSessionId !== canonicalId) {
        // The browser's record stays as it was, plus the pointer: roll forward, never rewind.
        const tomb = sessionDataSchema.parse({ ...from, forwardTo: canonicalId });
        await this.kv.put(`session:${input.fromSessionId}`, JSON.stringify(tomb), { expirationTtl: this.sessionTTL });
      }
    }
    return { sessionId: canonicalId!, data: validated, changes: merged.changes, created };
  }

  /**
   * CW25. Write an imported reflex vector onto a shopper's session, and nothing
   * else about the visit. History informs interest; it does not claim visits the
   * engine never saw, so lastSeen and the visit number are left exactly as they
   * were. A shopper met first through an import gets a record with the identity
   * block and no visit at all.
   */
  async applyImport(input: {
    userId: string;
    reflex: ReflexState;
    identity?: { shopperId: string; linkedAt: number };
    now?: number;
  }): Promise<{ sessionId: string; data: SessionData; created: boolean }> {
    const now = input.now ?? Date.now();
    const sid0 = (await this.kv.get(`user:${input.userId}`)) as string | null;
    const resolved = sid0 ? await this.resolveRecord(sid0) : { id: this.generateSessionId(), data: null };
    const existing = resolved.data;
    const sessionId = resolved.id;
    const data: SessionData = existing
      ? {
          ...existing,
          reflex: input.reflex,
          segments: [...new Set([...existing.segments, ...input.reflex.audiences])].sort(),
          identity: existing.identity ?? input.identity,
          metadata: { ...existing.metadata, lastSegmentUpdate: now },
        }
      : {
          userId: input.userId,
          segments: [...input.reflex.audiences].sort(),
          attributes: {},
          reflex: input.reflex,
          identity: input.identity,
          metadata: { firstSeen: now, lastSeen: 0, sessionCount: 0, engagementScore: 0, lastSegmentUpdate: now },
          preferences: { trackingConsent: true, personalizationEnabled: true, cookieConsent: true },
        };
    const validated = sessionDataSchema.parse(data);
    await this.kv.put(`session:${sessionId}`, JSON.stringify(validated), { expirationTtl: this.sessionTTL });
    await this.kv.put(`user:${validated.userId}`, sessionId, { expirationTtl: this.sessionTTL });
    return { sessionId, data: validated, created: !existing };
  }

  /**
   * CW28. Forget a browser entirely: its `user:` pointer, and its own record
   * when the link remembered one (after a link the pointer names the person, so
   * the browser's pre-link record is reachable only this way).
   */
  async forgetVisitor(userId: string, ownSessionId?: string | null): Promise<void> {
    try {
      if (ownSessionId) await this.kv.delete(`session:${ownSessionId}`);
      await this.kv.delete(`user:${userId}`);
    } catch (error) {
      console.error('Error forgetting visitor');
    }
  }

  /**
   * Get session data by user ID
   */
  async getSessionByUserId(userId: string): Promise<SessionData | null> {
    try {
      const sessionId = (await this.kv.get(`user:${userId}`)) as string | null;
      if (!sessionId) {
        return null;
      }

      return this.getSession(sessionId);
    } catch (error) {
      console.error('Error retrieving session by user ID');
      return null;
    }
  }

  /**
   * Resolve the current sessionId for a stable userId (anon vuid), if any.
   * Used as a continuity fallback when the session cookie is absent or blocked.
   */
  async resolveSessionIdByUserId(userId: string): Promise<string | null> {
    try {
      return (await this.kv.get(`user:${userId}`)) as string | null;
    } catch (error) {
      console.error('Error resolving session id by user ID');
      return null;
    }
  }

  /**
   * Update user segments in session
   */
  async updateUserSegments(
    sessionId: string,
    segments: string[],
    engagementScore?: number
  ): Promise<SessionData | null> {
    try {
      const existingSession = await this.getSession(sessionId);
      if (!existingSession) {
        return null;
      }

      const updatedSession = await this.createOrUpdateSession(sessionId, existingSession.userId, {
        ...existingSession,
        segments,
        metadata: {
          ...existingSession.metadata,
          engagementScore: engagementScore ?? existingSession.metadata.engagementScore,
          lastSegmentUpdate: Date.now()
        }
      });

      return updatedSession;
    } catch (error) {
      console.error('Error updating user segments');
      return null;
    }
  }

  /**
   * Generate secure cookies for client-side persistence
   */
  generateSessionCookies(sessionData: SessionData, sessionId: string): CookieConfig[] {
    const cookieOptions: Partial<CookieConfig> = {
      maxAge: this.sessionTTL,
      httpOnly: false, // Need to be accessible to JavaScript for personalization
      secure: this.isSecure,
      sameSite: 'Lax',
      path: '/',
      ...(this.cookieDomain && { domain: this.cookieDomain })
    };

    const cookies: CookieConfig[] = [
      {
        name: 'opt_session_id',
        value: sessionId,
        ...cookieOptions,
        httpOnly: true // Session ID should be HTTP-only for security
      },
      {
        name: 'opt_user_id',
        value: sessionData.userId,
        ...cookieOptions
      },
      {
        name: 'opt_segments',
        value: sessionData.segments.join(','),
        ...cookieOptions
      },
      {
        name: 'opt_engagement_score',
        value: sessionData.metadata.engagementScore.toString(),
        ...cookieOptions
      },
      {
        name: 'opt_last_update',
        value: sessionData.metadata.lastSegmentUpdate.toString(),
        ...cookieOptions
      },
      {
        name: 'opt_tracking_consent',
        value: sessionData.preferences.trackingConsent.toString(),
        ...cookieOptions
      },
      {
        name: 'opt_personalization_enabled',
        value: sessionData.preferences.personalizationEnabled.toString(),
        ...cookieOptions
      }
    ];

    // Add anonymous ID cookie if available
    if (sessionData.anonymousId) {
      cookies.push({
        name: 'opt_anonymous_id',
        value: sessionData.anonymousId,
        ...cookieOptions
      });
    }

    return cookies;
  }

  /**
   * Parse session cookies from request headers
   */
  parseSessionCookies(cookieHeader: string | null): Partial<SessionCookies> {
    if (!cookieHeader) {
      return {};
    }

    const cookies: Record<string, string> = {};

    cookieHeader.split(';').forEach(cookie => {
      const [name, ...value] = cookie.trim().split('=');
      if (name && value.length > 0) {
        cookies[name] = decodeURIComponent(value.join('='));
      }
    });

    return {
      sessionId: cookies['opt_session_id'],
      userId: cookies['opt_user_id'],
      anonymousId: cookies['opt_anonymous_id'],
      segments: cookies['opt_segments'],
      engagementScore: cookies['opt_engagement_score'],
      lastUpdate: cookies['opt_last_update'],
      trackingConsent: cookies['opt_tracking_consent'],
      personalizationEnabled: cookies['opt_personalization_enabled']
    };
  }

  /**
   * Create cookie header string for HTTP response
   */
  /**
   * CW25. Every cookie this manager sets, expired. What a detach (logout) sends:
   * the device forgets which session it was on; nothing server-side changes.
   * `maxAge` 0 is rendered by hand because createCookieHeaders treats 0 as unset.
   */
  clearCookieHeaders(): string[] {
    const names = ['opt_session_id', 'opt_user_id', 'opt_anonymous_id', 'opt_segments',
      'opt_engagement_score', 'opt_last_update', 'opt_tracking_consent', 'opt_personalization_enabled'];
    const domain = this.cookieDomain ? `; Domain=${this.cookieDomain}` : '';
    return names.map((n) => `${n}=; Max-Age=0; Path=/${domain}; SameSite=Lax`);
  }

  createCookieHeaders(cookies: CookieConfig[]): string[] {
    return cookies.map(cookie => {
      let header = `${cookie.name}=${encodeURIComponent(cookie.value)}`;

      if (cookie.maxAge) {
        header += `; Max-Age=${cookie.maxAge}`;
      }

      if (cookie.domain) {
        header += `; Domain=${cookie.domain}`;
      }

      if (cookie.path) {
        header += `; Path=${cookie.path}`;
      }

      if (cookie.secure) {
        header += '; Secure';
      }

      if (cookie.httpOnly) {
        header += '; HttpOnly';
      }

      if (cookie.sameSite) {
        header += `; SameSite=${cookie.sameSite}`;
      }

      return header;
    });
  }

  /**
   * Generate a new session ID
   */
  generateSessionId(): string {
    return crypto.randomUUID();
  }

  /**
   * Delete session and clear cookies
   */
  async deleteSession(sessionId: string): Promise<boolean> {
    try {
      // The record as stored, NOT what it forwards to: deleting a linked
      // browser's session detaches that browser; only the person's own session
      // id erases the person.
      const sessionData = await this.readRaw(sessionId);

      // Delete session data
      await this.kv.delete(`session:${sessionId}`);

      // Delete user ID mapping
      if (sessionData) {
        await this.kv.delete(`user:${sessionData.userId}`);
      }

      return true;
    } catch (error) {
      console.error('Error deleting session');
      return false;
    }
  }

  /**
   * Clear expired sessions (to be called by scheduled worker)
   */
  async cleanupExpiredSessions(): Promise<number> {
    try {
      // KV automatically handles TTL expiration, but we can manually clean up if needed
      // This is more for logging/metrics purposes
      console.log('Session cleanup scheduled - KV TTL handles automatic expiration');
      return 0;
    } catch (error) {
      console.error('Error during session cleanup');
      return 0;
    }
  }

  /**
   * Get session analytics data
   */
  async getSessionAnalytics(sessionId: string): Promise<{
    sessionDuration: number;
    pageViews: number;
    engagementScore: number;
    segmentHistory: string[];
  } | null> {
    try {
      const sessionData = await this.getSession(sessionId);
      if (!sessionData) {
        return null;
      }

      const sessionDuration = Date.now() - sessionData.metadata.firstSeen;

      return {
        sessionDuration,
        pageViews: sessionData.attributes.page_views || 0,
        engagementScore: sessionData.metadata.engagementScore,
        segmentHistory: sessionData.segments
      };
    } catch (error) {
      console.error('Error retrieving session analytics');
      return null;
    }
  }

  /**
   * Update user preferences
   */
  async updateUserPreferences(
    sessionId: string,
    preferences: Partial<SessionData['preferences']>
  ): Promise<SessionData | null> {
    try {
      const existingSession = await this.getSession(sessionId);
      if (!existingSession) {
        return null;
      }

      return this.createOrUpdateSession(sessionId, existingSession.userId, {
        ...existingSession,
        preferences: {
          ...existingSession.preferences,
          ...preferences
        }
      });
    } catch (error) {
      console.error('Error updating user preferences');
      return null;
    }
  }
}

// src/services/RealtimeSegmentEngine.ts
// Connector-driven, catalog-aware real-time personalization engine.
// See docs/architecture/05-demo-build-spec.md §2.1.
//
// REAL SEAMS, MOCKED CALLS: this engine no longer hardcodes B2B segment rules or
// Optimizely flag keys. Qualification is delegated to the ODP seam
// (connectors.segments.fetchQualifiedSegments) and decisioning to the Optimizely
// Feature Experimentation seam (connectors.decisions.decideAll). Coach launch
// audiences are seeded idempotently into the shared AudienceStore at boot, so the
// very first (cold) event a shopper generates is qualified against every audience —
// and an audience Opal creates at runtime becomes qualifiable with zero redeploy.
//
// The public methods routes call are preserved verbatim (processActionEvent,
// processActionEventWithSession, getOrCreateSessionFromCookies,
// getSessionPersonalizationConfig, getUserSegments, assignSegment, …). The
// constructor accepts an optional Connectors so existing single-arg route calls
// (`new RealtimeSegmentEngine(env)`) keep working while the spec's two-arg form
// (`new RealtimeSegmentEngine(env, getConnectors(env))`) is also supported.

