}

export interface PersonalizationConfig {
  /** Optimizely decisions, one per CATALOG_FLAG_KEYS slot — drives which module renders. */
  decisions: Record<string, Decision>;
  /** Back-compat: enabled-state per flag, derived from `decisions` (was getFeatureFlagDecisions). */
  featureFlags: Record<string, boolean>;
  /** Back-compat: chosen variation per flag, derived from `decisions` (was getExperimentDecisions). */
  experiments: Record<string, string>;
  /** Flat module-variables view of `decisions` (back-compat with featureVariables consumers). */
  featureVariables: Record<string, any>;
  enhancedFeatureVariables: Record<string, FeatureVariableResult>;
  cookieUpdates: Record<string, string>;
  cookieHeaders: string[];
  segments: string[];
  /** Personalized catalog recommendations for the current session. */
  recommendations: Product[];
  /** Personalized PLP sort order (product ids) for the current session. */
  sortOrder: string[];
  journeyStage: 'early' | 'mid' | 'late';
  sessionData: SessionData;
}

/**
 * Retail signals every QualificationContext starts with, so a cold session still
 * evaluates the audience condition trees sensibly (e.g. a `cart_adds eq 0` predicate
 * must be true for a brand-new shopper). Numeric counters initialize to 0.
 * Exported for the ShopperReflex DO (doc 16 §6, P2) — both hosts qualify against
 * the identical baseline.
 */
export const RETAIL_SIGNAL_DEFAULTS: Record<string, number> = {
  product_views: 0,
  cart_adds: 0,
  wishlist_adds: 0,
  page_views: 0,
  category_dwell_ms: 0,
  // `purchases eq 0` gates the ready-to-buy/cart audiences — without a default an
  // anonymous session evaluates undefined === 0 → false, and they can NEVER qualify.
  purchases: 0,
};

// ─────────────────────────────────────────────────────────────────────────────
// P2 seam (doc 16 §6): the pure/pipeline pieces of this engine that the
// ShopperReflex Durable Object must run IDENTICALLY are lifted to module scope
// and exported. The class methods below delegate to these — same behavior, one
// source, two hosts (request path today, per-shopper DO behind REFLEX_HOST='do').
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Update attributes based on a retail action event. Retail intent can arrive either
 * as a typed event or carried in `event.data.action` (the storefront posts catalog
 * events as page_view/custom with a `line`/`productId`/`action` payload), so we
 * inspect both. Derives the attributes the Coach audiences are written against:
 * viewed_product_line, product_views, cart_adds, wishlist_adds, price_band_viewed,
 * category_dwell_ms, page_views.
 */
export function applyEventToAttributes(
  attributes: Record<string, any>,
  event: ActionEvent,
  catalog: CatalogService
): void {
  const data = event.data ?? {};
  // The retail action: explicit data.action wins, else the event type.
  const action = actionOf(event);

  const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
  const inc = (key: string, by = 1) => {
    attributes[key] = num(attributes[key]) + by;
  };

  // Resolve a product (if referenced) so we can enrich line / price band from the catalog.
  const productId: string | undefined = data.productId ?? data.product_id ?? data.sku;
  const product = productId ? catalog.getProduct(productId) : undefined;
  const line: string | undefined =
    product?.line ?? (typeof data.line === 'string' ? data.line : undefined);
  const priceUsd: number | undefined =
    product?.price_usd ?? (typeof data.price_usd === 'number' ? data.price_usd : undefined);

  const applyLineAndBand = () => {
    if (line) attributes.viewed_product_line = line;
    if (typeof priceUsd === 'number') attributes.price_band_viewed = priceBandOf(priceUsd);
  };

  switch (action) {
    case 'product_view':
    case 'pdp_view':
    case 'view_product':
      inc('product_views');
      applyLineAndBand();
      if (typeof data.dwellMs === 'number') inc('category_dwell_ms', data.dwellMs);
      break;

    case 'add_to_cart':
    case 'cart_add':
      inc('cart_adds');
      applyLineAndBand();
      break;

    case 'wishlist':
    case 'wishlist_add':
    case 'add_to_wishlist':
    case 'save_for_later':
      inc('wishlist_adds');
      applyLineAndBand();
      break;

    case 'purchase':
    case 'checkout':
    case 'order_complete':
      inc('purchases');
      applyLineAndBand();
      break;

    case 'page_view':
      inc('page_views');
      if (typeof data.path === 'string') attributes.last_page_path = data.path;
      if (typeof data.dwellMs === 'number') inc('category_dwell_ms', data.dwellMs);
      // A page_view that carries a product line/category still updates affinity.
      applyLineAndBand();
      break;

    case 'button_click':
      inc('button_clicks');
      if (data.buttonId) attributes.last_button_clicked = data.buttonId;
      break;

    default:
      // Unknown/custom retail signal: still capture line/band if present so affinity grows.
      applyLineAndBand();
      if (typeof data.dwellMs === 'number') inc('category_dwell_ms', data.dwellMs);
      break;
  }

  attributes.last_activity = Date.now();
}

/**
 * Catalog-aware engagement score. Weights real retail intent: cart adds and
 * wishlist saves dominate, PDP views and dwell contribute, page views are a light
 * signal. Clamped to 0–100 so it stays a stable, comparable session score.
 */
export function calculateEngagementScore(attributes: Record<string, any>): number {
  const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

  const productViews = num(attributes.product_views);
  const cartAdds = num(attributes.cart_adds);
  const wishlistAdds = num(attributes.wishlist_adds);
  const purchases = num(attributes.purchases);
  const pageViews = num(attributes.page_views);
  const dwellMinutes = num(attributes.category_dwell_ms) / 60000;

  const score =
    productViews * 8 +
    cartAdds * 25 +
    wishlistAdds * 15 +
    purchases * 40 +
    pageViews * 2 +
    dwellMinutes * 5;

  return Math.min(100, Math.round(score));
}

/** Set-diff over segment keys — the change-detect both hosts trigger pushes on. */
export function hasSegmentChanges(oldSegments: string[], newSegments: string[]): boolean {
  if (oldSegments.length !== newSegments.length) {
    return true;
  }
  const oldSet = new Set(oldSegments);
  return newSegments.some((segment) => !oldSet.has(segment));
}

/**
 * Idempotently load the Coach launch audiences + the catalog-generated affinity
 * audiences (doc 16 §5) into the shared AudienceStore. Version-gated on a hash of
 * the generated set so the hot path pays ONE KV read; the diff
 * (regenerateCatalogAudiences) runs only when the catalog or generator config
 * actually changed — and never clobbers pinned/human edits.
 *
 * Multi-surface (PH build spec §3): each surface owns its OWN version marker and
 * its own archive scope, so two demos regenerating over one store cannot archive
 * each other's audiences on alternating passes. The Coach launch seeds belong to
 * the default surface and are seeded only on its pass.
 */
export async function ensureAudiencesSeeded(
  env: Env,
  catalogService: CatalogService,
  surface: DemoSurface = DEFAULT_SURFACE,
  tenant: TenantId = DEFAULT_TENANT
): Promise<void> {
  const store = new KvAudienceStore(env, tenant);
  if (surface === DEFAULT_SURFACE) await store.seed(SEED_AUDIENCES);
  const generated = generateAffinityAudiences(
    catalogService.getAllProducts() as unknown as Array<Record<string, unknown>>,
    await resolveReflexConfig(env, surface),
    surface === DEFAULT_SURFACE
      ? DEFAULT_GENERATOR_CONFIG
      : { ...DEFAULT_GENERATOR_CONFIG, surface, keyPrefix: audienceKeyPrefixFor(surface) }
  );
  const setHash = generated.map((d) => `${d.key}:${d.generatorHash}`).join('|');
  const MARKER = audgenMarkerFor(surface);
  if ((await new TenantKV(env.CACHE as unknown as KVLike, tenant).get(MARKER)) === setHash) return;
  const s = await regenerateCatalogAudiences(store, generated, surface);
  await new TenantKV(env.CACHE as unknown as KVLike, tenant).put(MARKER, setHash);
  console.log(
    `[reflex] catalog audiences regenerated: +${s.published.length} ~${s.updated.length} −${s.archived.length}` +
      ` (skipped: ${s.skippedHumanEdited.length} human-edited, ${s.skippedPinned.length} pinned)`
  );
}

export class RealtimeSegmentEngine {
  readonly tenant: TenantId;
  private readonly cache: KVLike;
  private readonly sessions: KVLike;
  /**
   * CW6: how background work outlives the response. The route hands in its
   * execution context per call; without one (tests), a promise is simply let go.
   */
  private keepAlive?: (p: Promise<unknown>) => void;

  private env: Env;
  private connectors: Connectors;
  private sessionManager: SessionManager;
  private featureVariableManager: FeatureVariableManager;
  private catalogService: CatalogService;
  /** Audiences are seeded once per engine instance PER SURFACE (idempotent on the
      store regardless). */
  private seeded = new Set<DemoSurface>();

  constructor(
    env: Env,
    connectors?: Connectors,
    options?: { domain?: string; secure?: boolean; tenant?: TenantId }
  ) {
    this.env = env;
    // The brand this engine decides for. Flows straight through to SessionManager
    // via `options`; the audience store and the socket name need it explicitly.
    this.tenant = options?.tenant ?? DEFAULT_TENANT;
    // Default to getConnectors(env) so existing single-arg route calls keep working
    // while the spec's two-arg `new RealtimeSegmentEngine(env, getConnectors(env))` is honored.
    this.connectors = connectors ?? getConnectors(env);
    this.sessionManager = new SessionManager(env, options);
    this.featureVariableManager = new FeatureVariableManager(env, this.tenant);
    // The two raw stores this class still touched directly, now scoped like
    // everything that goes through SessionManager and the audience store.
    this.cache = new TenantKV(env.CACHE as unknown as KVLike, this.tenant);
    this.sessions = new TenantKV(env.SESSIONS as unknown as KVLike, this.tenant);
    this.catalogService = new CatalogService();
  }

  /**
   * Idempotently load the Coach launch audiences into the shared AudienceStore.
   * Called at the start of any operation that qualifies segments, so ODP (mock or
   * live) always has the seed audiences plus any Opal-created ones to evaluate.
   * Delegates to the exported ensureAudiencesSeeded (shared with the P2 DO).
   */
  private async ensureSeeded(surface: DemoSurface = DEFAULT_SURFACE): Promise<void> {
    if (this.seeded.has(surface)) return;
    try {
      await ensureAudiencesSeeded(this.env, await this.catalogFor(surface), surface);
      this.seeded.add(surface);
    } catch (error) {
      console.error('Error seeding audiences');
    }
  }

  /** The surface an event belongs to — explicit field, else `source`, else coach. */
  private surfaceOf(event: ActionEvent): DemoSurface {
    return resolveSurface({
      source: event.source,
      surface: event.surface ?? (event.data as Record<string, unknown> | undefined)?.surface as string | undefined,
    });
  }

  /**
   * The catalog this surface scores against. The default surface keeps the
   * instance built in the constructor — same object, same graph, same order — so
   * nothing about the retail path moves; other surfaces resolve a memoized
   * per-surface CatalogService from the registry.
   */
  private async catalogFor(surface: DemoSurface): Promise<CatalogService> {
    return surface === DEFAULT_SURFACE ? this.catalogService : catalogServiceFor(surface);
  }

  async processActionEvent(event: ActionEvent, sessionId?: string): Promise<PersonalizationUpdate | null> {
    try {
      // 0. Resolve the demo surface this event belongs to, then seed THAT surface's
      // audiences idempotently (cold sessions qualify on first event). Everything
      // below reads the surface's catalog + reflex config; 'coach' resolves to the
      // exact objects this method used before the multi-surface split.
      const surface = this.surfaceOf(event);
      const catalogService = await this.catalogFor(surface);
      const reflexConfig = await resolveReflexConfig(this.env, surface);
      const audiencePrefix = audienceKeyPrefixFor(surface);
      await this.ensureSeeded(surface);

      // 1. Get or create session
      const currentSessionId = sessionId || this.sessionManager.generateSessionId();
      let sessionData = await this.sessionManager.getSession(currentSessionId);

      // If no session exists, get user profile data from legacy method
      if (!sessionData) {
        const userProfile = await this.getUserProfile(event.userId);
        sessionData = await this.sessionManager.createOrUpdateSession(currentSessionId, event.userId, {
          anonymousId: event.anonymousId,
          segments: userProfile.segments,
          attributes: userProfile.attributes,
          metadata: {
            firstSeen: userProfile.metadata.firstSeen,
            lastSeen: Date.now(),
            sessionCount: userProfile.metadata.sessionCount,
            engagementScore: calculateEngagementScore(userProfile.attributes),
            lastSegmentUpdate: userProfile.lastUpdated
          },
          preferences: {
            trackingConsent: true,
            personalizationEnabled: true,
            cookieConsent: true
          }
        }, event.entry);
      }

      // 2. Apply this event's retail signals to a fresh attribute snapshot.
      const newAttributes = { ...sessionData.attributes };
      applyEventToAttributes(newAttributes, event, catalogService);
      const newEngagementScore = calculateEngagementScore(newAttributes);

      // 2.5 Edge Affinity Reflex (doc 16): decayed per-dimension affinity via the
      // pure core. State rides the session in P0 (relocates into the DO in P2).
      // The ENGINE clock is authoritative — client timestamps are advisory only.
      const nowMs = Date.now();
      const reflexOn = (this.env.REFLEX_ENABLED ?? 'true') !== 'false';
      let reflex: ReflexResult | null = null;
      if (reflexOn) {
        const data = event.data ?? {};
        const pid = data.productId ?? data.product_id ?? data.sku;
        const product = pid ? catalogService.getProduct(String(pid)) : undefined;
        const action = actionOf(event);
        reflex = applyReflex(
          sessionData.reflex,
          {
            action,
            // A held product's attributes, or, where the scope allows it, the
            // event's own (CW24): a customer's site scores against their catalog.
            touches: isContentAction(action)
              ? contentTouches(data as Record<string, unknown>, reflexConfig)
              : touchesForEvent(data as Record<string, unknown>, product as unknown as Record<string, unknown> | undefined, reflexConfig),
          },
          nowMs,
          reflexConfig
        );
        // CW6: the same touches, fanned into the shopper's region as a population count.
        (this.keepAlive ?? ((p: Promise<unknown>) => { void p; }))(fanInRegionTrend(this.env, {
          tenant: surface, geo: event.geo, now: nowMs,
          touches: touchesForEvent(data as Record<string, unknown>, product as unknown as Record<string, unknown> | undefined, reflexConfig),
          w: reflexConfig.weights[action] ?? 0,
        }));
      }

      // 3. Qualify segments through the ODP seam against the live context.
      const ctx = this.buildQualificationContext(
        event.userId,
        event.anonymousId ?? sessionData.anonymousId,
        newAttributes,
        sessionData.segments
      );
      ctx.surface = surface; // qualification evaluates only THIS surface's audiences
      const journeyStage = deriveStage(ctx);
      ctx.attributes.journey_stage = journeyStage; // stage is itself an audience attribute
      // Reflex scores are computed FRESH into the context (never persisted — they
      // decay by construction), so store-published affinity audiences can gte them.
      if (reflex) Object.assign(ctx.attributes, reflexAttributes(reflex.state, nowMs, reflexConfig));
      const localSegments = await this.connectors.segments.fetchQualifiedSegments(event.userId, ctx);
      // ODP loop (doc 16 §8): seed/refresh the session's LIVE ODP-qualified audiences.
      // Additive + hard-capped (1.5s in fetchOdpAudiences) — ODP can only ever ADD;
      // slow or down degrades to exactly the pre-ODP behavior.
      let odpSeed = sessionData.odpSeed ?? [];
      let odpSeedAt = sessionData.odpSeedAt ?? 0;
      let odpRing = Array.isArray(sessionData.odpRecentEvents) ? sessionData.odpRecentEvents.slice() : [];
      if (odpEnabled(this.env)) {
        // Ring maintenance + seed read policy live in odpLoop (updateOdpRing /
        // refreshOdpSeedIfDue) — shared verbatim with the ShopperReflex DO (P2)
        // so the two hosts can never drift.
        odpRing = updateOdpRing(odpRing, event, nowMs);
        const membershipChanged = !!reflex && (reflex.changes.entered.length > 0 || reflex.changes.exited.length > 0);
        ({ seed: odpSeed, seedAt: odpSeedAt } = await refreshOdpSeedIfDue(
          this.env,
          // event.userId is the stable first-party visitor id the client mints
          // and persists; the session id is only the fallback for a client that
          // does not send one.
          { visitorId: event.userId, sessionId: currentSessionId },
          odpRing,
          { seed: odpSeed, seedAt: odpSeedAt },
          nowMs,
          membershipChanged
        ));
      }
      // Union: local evaluation ∪ live reflex memberships ∪ ODP-confirmed seed —
      // any enter/exit drives the same change-detect → persist → decide → push loop.
      // The reflex core names memberships from the catalog alone; the surface
      // namespace is applied HERE so they match the generated audience keys
      // (prefix '' for coach ⇒ the same array, untouched).
      const reflexAudiences = reflex
        ? audiencePrefix
          ? reflex.state.audiences.map((k) => audiencePrefix + k)
          : reflex.state.audiences
        : [];
      const newSegments = Array.from(new Set([
        ...localSegments,
        ...reflexAudiences,
        ...odpSeed,
      ]));

      // 4. Detect what actually changed (segments OR journey stage) — either is a trigger.
      const segmentsChanged = hasSegmentChanges(sessionData.segments, newSegments);
      const stageChanged = sessionData.metadata.journeyStage !== journeyStage;

      if (!segmentsChanged && !stageChanged) {
        // No personalization change — persist the accrued attributes/activity and stop.
        await this.sessionManager.createOrUpdateSession(currentSessionId, event.userId, {
          ...sessionData,
          attributes: newAttributes,
          surface,
          reflex: reflex ? reflex.state : sessionData.reflex,
          odpSeed,
          odpSeedAt,
          odpRecentEvents: odpRing,
          metadata: {
            ...sessionData.metadata,
            lastSeen: Date.now(),
            engagementScore: newEngagementScore,
            journeyStage
          }
        }, event.entry);
        return null;
      }

      // 5. Persist new attributes, segments, engagement score, and journey stage.
      await this.sessionManager.createOrUpdateSession(currentSessionId, event.userId, {
        ...sessionData,
        attributes: newAttributes,
        surface,
        reflex: reflex ? reflex.state : sessionData.reflex,
        odpSeed,
        odpSeedAt,
        odpRecentEvents: odpRing,
        segments: newSegments,
        metadata: {
          ...sessionData.metadata,
          lastSeen: Date.now(),
          engagementScore: newEngagementScore,
          lastSegmentUpdate: Date.now(),
          journeyStage
        }
      }, event.entry);

      const updatedSessionData = await this.sessionManager.getSession(currentSessionId);
      if (!updatedSessionData) {
        throw new Error('Failed to update session data');
      }

      // 6. Decide the storefront modules through the Optimizely FX seam.
      const personalizationConfig = await this.getPersonalizationConfig(updatedSessionData, currentSessionId);

      // 7. Create the personalization update with retail payloads.
      const update: PersonalizationUpdate = {
        type: 'personalization_update',
        userId: event.userId,
        data: {
          segments: newSegments,
          decisions: personalizationConfig.decisions,
          featureVariables: personalizationConfig.featureVariables,
          recommendations: personalizationConfig.recommendations,
          sortOrder: personalizationConfig.sortOrder,
          journeyStage,
          // Live affinity payload for the Affinity Instrument (dims use original
          // catalog value names; changed = this event's explain records).
          affinity: reflex
            ? { ...reflexSnapshot(reflex.state, nowMs, reflexConfig), changed: reflex.changes.explain, odpConfirmed: odpSeed }
            : undefined,
          cookies: personalizationConfig.cookieUpdates,
          cookieHeaders: personalizationConfig.cookieHeaders,
          sessionId: currentSessionId,
          engagementScore: newEngagementScore,
          timestamp: Date.now(),
          source: event.source
        } as PersonalizationUpdate['data']
      };

      // 8. Broadcast update via WebSocket
      await this.broadcastUpdate(update);

      return update;

    } catch (error) {
      console.error('Error processing action event');
      throw error;
    }
  }

  async getUserProfile(userId: string): Promise<UserProfile> {
    const cacheKey = `profile:${userId}`;
    const cached = await this.cache.get(cacheKey, 'json') as UserProfile;

    if (cached) {
      return cached;
    }

    // Create new profile — cold start: no segments yet (ODP qualifies on first event).
    return {
      userId,
      segments: [],
      attributes: {},
      lastUpdated: Date.now(),
      events: [],
      metadata: {
        firstSeen: Date.now(),
        lastSeen: Date.now(),
        sessionCount: 1,
        emailOpens: 0,
        formSubmissions: 0,
        pageViews: 0
      }
    };
  }

  async saveUserProfile(profile: UserProfile): Promise<void> {
    const cacheKey = `profile:${profile.userId}`;
    await this.cache.put(cacheKey, JSON.stringify(profile), {
      expirationTtl: 7 * 24 * 60 * 60 // 7 days
    });
  }

  /**
   * Build the real-time QualificationContext the SegmentProvider qualifies against.
   * Numeric retail signals are initialized to 0 so cold sessions evaluate condition
   * trees sensibly (e.g. `cart_adds eq 0` is true for a brand-new shopper).
   */
  private buildQualificationContext(
    userId: string,
    anonymousId: string | undefined,
    attributes: Record<string, any>,
    segments: string[]
  ): QualificationContext {
    return {
      userId,
      anonymousId,
      attributes: { ...RETAIL_SIGNAL_DEFAULTS, ...attributes },
      segments
    };
  }

  // updateAttributesWithEvent / hasSegmentChanges / calculateEngagementScore were
  // lifted verbatim to exported module functions (applyEventToAttributes, …) so
  // the ShopperReflex DO runs the identical pipeline — see the P2 seam block above.

  private async getPersonalizationConfig(sessionData: SessionData, sessionId: string): Promise<PersonalizationConfig> {
    // The session remembers which demo it belongs to (absent ⇒ coach), so the
    // config path resolves the same catalog/config the event path scored with.
    const surface = resolveSurface({ surface: sessionData.surface });
    const catalogService = await this.catalogFor(surface);
    const attributes = { ...RETAIL_SIGNAL_DEFAULTS, ...sessionData.attributes };
    // Live affinity reads for the decision layer (doc 16 §10 choreography):
    // computed FRESH from the reflex state — they decay by construction, so they
    // are never persisted; the decision sees the score as of THIS moment.
    if ((this.env.REFLEX_ENABLED ?? 'true') !== 'false' && sessionData.reflex) {
      Object.assign(
        attributes,
        reflexAttributes(sessionData.reflex, Date.now(), await resolveReflexConfig(this.env, surface))
      );
    }

    const visitNumber = sessionData.metadata.visitCount ?? 1;
    const userAttributes = {
      segments: sessionData.segments,
      ...attributes,
      engagement_score: sessionData.metadata.engagementScore,
      // session_count is the INTERACTION count and always has been. It is kept
      // because it is persisted and read elsewhere; it is not the visit number
      // and must never be used as one.
      session_count: sessionData.metadata.sessionCount,
      // The two dimensions Mandeep named, and levels 1 and 2 of doc 22's pooling
      // ladder. visit_bucket is the cut the learning statistics pool on; the raw
      // number rides along for anything that wants finer grain.
      visit_number: visitNumber,
      visit_bucket: visitBucket(visitNumber),
      entry_channel: sessionData.metadata.entryChannel ?? 'direct',
      journey_stage: sessionData.metadata.journeyStage,
      days_since_first_seen: Math.floor((Date.now() - sessionData.metadata.firstSeen) / (24 * 60 * 60 * 1000)),
      tracking_consent: sessionData.preferences.trackingConsent,
      personalization_enabled: sessionData.preferences.personalizationEnabled
    };

    const journeyStage: 'early' | 'mid' | 'late' = sessionData.metadata.journeyStage ?? 'early';

    // Decide the full storefront module set through the Optimizely FX seam.
    const decisions = await this.connectors.decisions.decideAll(
      CATALOG_FLAG_KEYS,
      sessionData.userId,
      sessionData.segments,
      userAttributes
    );

    // Flat views derived from decisions (back-compat with the existing route response shape).
    const featureVariables: Record<string, any> = {};
    const featureFlags: Record<string, boolean> = {};
    const experiments: Record<string, string> = {};
    for (const [flagKey, decision] of Object.entries(decisions)) {
      featureVariables[flagKey] = decision.variables;
      featureFlags[flagKey] = decision.enabled;
      if (decision.variationKey) experiments[flagKey] = decision.variationKey;
    }

    // Catalog-aware recommendations + personalized sort for this session.
    const anchorLine =
      typeof sessionData.attributes.viewed_product_line === 'string'
        ? sessionData.attributes.viewed_product_line
        : undefined;
    const recommendations = catalogService.getRecommendations(
      { line: anchorLine },
      sessionData.segments,
      8
    );
    const sortOrder = catalogService
      .sortForSegments(null, sessionData.segments, sessionData.attributes)
      .slice(0, 24)
      .map((p) => p.id);

    // Enhanced feature variables (unchanged — driven by FeatureVariableManager).
    const enhancedFeatureVariables = await this.featureVariableManager.getSessionFeatureVariables(sessionData);

    // Legacy cookie updates for backward compatibility.
    const cookieUpdates = this.generateCookieUpdates(sessionData.segments, attributes, journeyStage);

    // Enhanced secure cookies via SessionManager.
    const sessionCookies = this.sessionManager.generateSessionCookies(sessionData, sessionId);
    const cookieHeaders = this.sessionManager.createCookieHeaders(sessionCookies);

    return {
      decisions,
      featureFlags,
      experiments,
      featureVariables,
      enhancedFeatureVariables,
      cookieUpdates,
      cookieHeaders,
      segments: sessionData.segments,
      recommendations,
      sortOrder,
      journeyStage,
      sessionData
    };
  }

  private generateCookieUpdates(
    segments: string[],
    attributes: Record<string, any>,
    journeyStage: 'early' | 'mid' | 'late'
  ): Record<string, string> {
    return {
      'opt_segments': segments.join(','),
      'opt_last_update': Date.now().toString(),
      'opt_product_views': (attributes.product_views ?? 0).toString(),
      'opt_cart_adds': (attributes.cart_adds ?? 0).toString(),
      'opt_journey_stage': journeyStage,
      'opt_engagement_score': calculateEngagementScore(attributes).toString()
    };
  }

  private async broadcastUpdate(update: PersonalizationUpdate): Promise<void> {
    try {
      const id = this.env.PERSONALIZATION_WEBSOCKET.idFromName(shopperObjectName(this.tenant, update.userId));
      const websocketObject = this.env.PERSONALIZATION_WEBSOCKET.get(id);

      await websocketObject.fetch(new Request('http://fake/broadcast', {
        method: 'POST',
        body: JSON.stringify(update),
        headers: { 'Content-Type': 'application/json' }
      }));
    } catch (error) {
      console.error('Error broadcasting update');
    }
  }

  // Get user segments for external API calls
  async getUserSegments(userId: string): Promise<string[]> {
    // Prefer the live session context if one exists, so segments reflect accrued signals.
    const sessionData = await this.sessionManager.getSessionByUserId(userId);
    const surface = resolveSurface({ surface: sessionData?.surface });
    await this.ensureSeeded(surface);

    const attributes = sessionData?.attributes ?? {};
    const segments = sessionData?.segments ?? [];
    const ctx = this.buildQualificationContext(
      userId,
      sessionData?.anonymousId,
      attributes,
      segments
    );
    ctx.surface = surface;
    ctx.attributes.journey_stage = deriveStage(ctx);
    return this.connectors.segments.fetchQualifiedSegments(userId, ctx);
  }

  // Manual segment assignment (operator/admin path) — adds a segment to the profile and broadcasts.
  async assignSegment(userId: string, segment: string, source: string = 'manual'): Promise<void> {
    const profile = await this.getUserProfile(userId);

    if (!profile.segments.includes(segment)) {
      profile.segments.push(segment);
      profile.lastUpdated = Date.now();
      await this.saveUserProfile(profile);

      // Mirror onto the live session if present, so subsequent decisions see it.
      const sessionData = await this.sessionManager.getSessionByUserId(userId);
      if (sessionData) {
        const merged = Array.from(new Set([...sessionData.segments, segment]));
        await this.sessionManager.updateUserSegments(
          await this.sessionIdForUser(userId),
          merged,
          sessionData.metadata.engagementScore
        );
      }

      // Broadcast update
      const update: PersonalizationUpdate = {
        type: 'segment_update',
        userId,
        data: {
          segments: profile.segments,
          timestamp: Date.now(),
          source
        }
      };

      await this.broadcastUpdate(update);
    }
  }

  /** Resolve the active sessionId for a user (used by manual segment assignment). */
  private async sessionIdForUser(userId: string): Promise<string> {
    const sid = (await this.sessions.get(`user:${userId}`)) as string | null;
    return sid ?? this.sessionManager.generateSessionId();
  }

  // Session Management Methods for API integration

  /**
   * Create or get session from cookie header
   */
  async getOrCreateSessionFromCookies(
    cookieHeader: string | null,
    userId: string,
    /** CW37. Where the session write goes instead of the response path. See SessionManager. */
    defer?: (p: Promise<unknown>) => void,
    /**
     * CW39. The browsing session the CLIENT is already carrying. The SDK keeps
     * one with an idle rule and sends it on the snapshot and on every event, and
     * both the decision record and the outcome prefer it -- but nothing used it
     * to find or name the session, so two requests arriving together each made a
     * session of their own and one visit was counted as two. Used when the
     * cookie says nothing, which on the decision route is always: that route
     * sets no cookie.
     */
    clientSessionId?: string,
  ): Promise<{
    sessionId: string;
    sessionData: SessionData;
    isNewSession: boolean;
  }> {
    const cookies = this.sessionManager.parseSessionCookies(cookieHeader);
    let sessionId = cookies.sessionId || (clientSessionId || '').trim();
    let sessionData: SessionData | null = null;
    let isNewSession = false;

    // Try to get existing session
    if (sessionId) {
      sessionData = await this.sessionManager.getSession(sessionId);
    }

    // Fallback: resolve by stable userId (anon vuid) when the cookie is absent/blocked.
    if (!sessionData) {
      const sid = await this.sessionManager.resolveSessionIdByUserId(userId);
      if (sid) {
        const existing = await this.sessionManager.getSession(sid);
        if (existing) {
          sessionId = sid;
          sessionData = existing;
        }
      }
    }

    // If no valid session, create new one
    if (!sessionData) {
      // CW37. THE ID THE BROWSER ALREADY HOLDS WINS. A cookie naming a session
      // this read could not find is not a reason to mint a second id: KV is
      // eventually consistent, so a record written moments ago can read as
      // absent, and deferring the write off the response path widens that
      // window on purpose. Minting a new id there would split one visit across
      // two sessions, and session-scope attribution compares the decision's
      // session to the outcome's -- a split credits nothing, which is the exact
      // failure found on 2026-09-04. Reusing the id the browser presents costs
      // nothing when it is genuinely new (an id nobody has written is an empty
      // session either way) and keeps the visit whole when it is not.
      sessionId = sessionId || this.sessionManager.generateSessionId();
      isNewSession = true;

      // Get user profile for initial session creation
      const userProfile = await this.getUserProfile(userId);
      sessionData = await this.sessionManager.createOrUpdateSession(sessionId, userId, {
        anonymousId: cookies.anonymousId,
        segments: cookies.segments ? cookies.segments.split(',').filter(Boolean) : userProfile.segments,
        attributes: userProfile.attributes,
        metadata: {
          firstSeen: userProfile.metadata.firstSeen,
          lastSeen: Date.now(),
          sessionCount: userProfile.metadata.sessionCount,
          engagementScore: parseInt(cookies.engagementScore || '0') || calculateEngagementScore(userProfile.attributes),
          lastSegmentUpdate: parseInt(cookies.lastUpdate || '0') || userProfile.lastUpdated
        },
        preferences: {
          // CW31: a cookie the browser has not been given yet says nothing, and nothing means consenting,
          // the same default createOrUpdateSession itself uses. Only an explicit 'false' withholds.
          // Before this, a first visit was stored as having refused both, which nothing honoured until CW31.
          trackingConsent: cookies.trackingConsent !== 'false',
          personalizationEnabled: cookies.personalizationEnabled !== 'false',
          cookieConsent: true
        }
      }, undefined, defer);
    }

    return {
      sessionId: sessionId!,
      sessionData,
      isNewSession
    };
  }

  /**
   * Get personalization configuration for current session
   */
  async getSessionPersonalizationConfig(sessionId: string): Promise<PersonalizationConfig | null> {
    const sessionData = await this.sessionManager.getSession(sessionId);
    if (!sessionData) {
      await this.ensureSeeded();
      return null;
    }
    await this.ensureSeeded(resolveSurface({ surface: sessionData.surface }));

    return this.getPersonalizationConfig(sessionData, sessionId);
  }

  /**
   * Update session preferences
   */
  async updateSessionPreferences(
    sessionId: string,
    preferences: Partial<SessionData['preferences']>
  ): Promise<SessionData | null> {
    return this.sessionManager.updateUserPreferences(sessionId, preferences);
  }

  /**
   * Get session analytics data
   */
  async getSessionAnalytics(sessionId: string): Promise<{
    sessionDuration: number;
    pageViews: number;
    engagementScore: number;
    segmentHistory: string[];
  } | null> {
    return this.sessionManager.getSessionAnalytics(sessionId);
  }

  /**
   * Process action event with session ID from request
   */
  async processActionEventWithSession(
    event: ActionEvent,
    cookieHeader: string | null,
    ctx?: { waitUntil(p: Promise<unknown>): void },
  ): Promise<{
    update: PersonalizationUpdate | null;
    sessionId: string;
    cookieHeaders: string[];
  }> {
    this.keepAlive = ctx ? (p) => { try { ctx.waitUntil(p); } catch { /* no execution context */ } } : undefined;
    const { sessionId } = await this.getOrCreateSessionFromCookies(
      cookieHeader,
      event.userId
    );

    const update = await this.processActionEvent(event, sessionId);

    // Get updated session for cookies
    const updatedSession = await this.sessionManager.getSession(sessionId);
    const cookies = updatedSession ?
      this.sessionManager.generateSessionCookies(updatedSession, sessionId) :
      [];
    const cookieHeaders = this.sessionManager.createCookieHeaders(cookies);

    return {
      update,
      sessionId,
      cookieHeaders
    };
  }

  // Enhanced Feature Variable Management Methods

  /**
   * Get feature variables for a user with enhanced functionality
   */
  async getEnhancedFeatureVariables(
    userId: string,
    userAttributes?: Record<string, any>
  ): Promise<Record<string, FeatureVariableResult>> {
    // Get session data to create enhanced attributes if not provided
    const sessionData = await this.sessionManager.getSessionByUserId(userId);

    if (sessionData && !userAttributes) {
      return this.featureVariableManager.getSessionFeatureVariables(sessionData);
    }

    return this.featureVariableManager.getFeatureVariables(
      userId,
      userAttributes || {}
    );
  }

  /**
   * Set feature variable override for testing/personalization
   */
  async setFeatureVariableOverride(
    userId: string,
    featureKey: string,
    variableKey: string,
    value: any,
    options?: {
      expiresAt?: number;
      reason?: string;
    }
  ): Promise<void> {
    await this.featureVariableManager.setUserOverride({
      userId,
      featureKey,
      variableKey,
      value,
      expiresAt: options?.expiresAt,
      reason: options?.reason
    });

    // Clear any cached personalization configs for this user
    const sessionData = await this.sessionManager.getSessionByUserId(userId);
    if (sessionData) {
      // Trigger a personalization update to reflect the override
      const update: PersonalizationUpdate = {
        type: 'feature_flag_update',
        userId,
        data: {
          featureKey,
          variableKey,
          value,
          source: 'override',
          timestamp: Date.now()
        } as PersonalizationUpdate['data']
      };

      await this.broadcastUpdate(update);
    }
  }

  /**
   * Remove feature variable override
   */
  async removeFeatureVariableOverride(
    userId: string,
    featureKey: string,
    variableKey: string
  ): Promise<void> {
    await this.featureVariableManager.removeUserOverride(userId, featureKey, variableKey);

    // Trigger update to reflect removal
    const sessionData = await this.sessionManager.getSessionByUserId(userId);
    if (sessionData) {
      const update: PersonalizationUpdate = {
        type: 'feature_flag_update',
        userId,
        data: {
          featureKey,
          variableKey,
          source: 'override_removed',
          timestamp: Date.now()
        } as PersonalizationUpdate['data']
      };

      await this.broadcastUpdate(update);
    }
  }

  /**
   * Get all feature variable overrides for a user
   */
  async getUserFeatureVariableOverrides(userId: string) {
    return this.featureVariableManager.getUserOverrides(userId);
  }

  /**
   * Get feature variable configurations for demo/testing
   */
  getFeatureVariableConfigurations() {
    return this.featureVariableManager.getFeatureConfigurations();
  }

  /**
   * Create demo feature variable overrides for testing
   */
  async createDemoFeatureVariableOverrides(userId: string): Promise<void> {
    await this.featureVariableManager.createDemoOverrides(userId);

    // Broadcast update about demo overrides
    const update: PersonalizationUpdate = {
      type: 'feature_flag_update',
      userId,
      data: {
        source: 'demo_overrides_created',
        timestamp: Date.now()
      }
    };

    await this.broadcastUpdate(update);
  }

  /**
   * Get feature variable analytics
   */
  async getFeatureVariableAnalytics() {
    return this.featureVariableManager.getFeatureVariableAnalytics();
  }
}

// src/durable-objects/ShopperReflex.ts
// ─────────────────────────────────────────────────────────────────────────────
// ShopperReflex — the per-shopper hot Durable Object (doc 16 §6, P2).
//
// A SQLite-backed DO (wrangler migration v4, `new_sqlite_classes`) that owns BOTH
// the WebSocket and the affinity state, so state and compute are co-located and
// hot: event → decay+add → evaluate audiences → changed? → push, all inside one
// object, no KV session round-trip, no cross-object hop on the push.
//
//   • One object per shopper, keyed on the STABLE visitor id
//     (SHOPPER_REFLEX.idFromName(opt_visitor_id)) — every tab/device carrying the
//     same id lands on the same object and receives the same pushes.
//   • WebSocket Hibernation API (`state.acceptWebSocket` / `webSocketMessage`):
//     objects park at near-zero cost between events and survive eviction. The
//     socket attachment carries ONLY `{shopperId}` — the ~2KB attachment cap is a
//     hard rule; ALL state lives in `ctx.storage` and rehydrates on wake.
//   • Two ingest doors, ONE handler: `webSocketMessage` (`{type:'action', …}`
//     frames) and `fetch POST /ingest` (no-WS clients, sendBeacon on unload, and
//     the existing POST /realtime/action which forwards here when
//     REFLEX_HOST='do'). Both call the same `ingest(event)`; the DO stamps
//     `Date.now()` on arrival — client timestamps are advisory only (§4).
//   • Closed-form alarms: core's `nextCrossing()` solves the exact instant the
//     earliest current membership decays below θ_out; `alarm()` re-evaluates
//     lazily (decay is read-time math — the alarm never mutates scores), pushes
//     the exits, and schedules the next crossing. No polling, exact-time exits.
//   • Retention lifecycle (§12): an object idle past REFLEX_RETENTION_DAYS
//     (default 30) self-expires via `ctx.storage.deleteAll()`.
//
// ENGINE REUSE, NOT REIMPLEMENTATION — the design decision, recorded:
// RealtimeSegmentEngine is session-coupled by construction (SessionManager/KV
// sessions, cookie headers, and a broadcast that hops to the relay DO), so it is
// NOT instantiated in here. Instead this DO hosts a THIN pipeline that calls the
// SAME modules the request path calls — zero math or policy is copied:
//   ReflexCore (@/reflex/core)      → apply/tick/snapshot/attributesFrom/nextCrossing
//   attribute accrual + engagement  → applyEventToAttributes / calculateEngagementScore
//                                     (exported verbatim from RealtimeSegmentEngine)
//   qualification                   → getConnectors(env).segments — KvAudienceStore +
//                                     evaluateCondition via MockSegmentProvider,
//                                     seeded by the shared ensureAudiencesSeeded
//   journey stage                   → deriveStage (@/services/JourneyStage)
//   ODP loop                        → updateOdpRing / refreshOdpSeedIfDue /
//                                     forwardEventToOdp / upsertOdpProfile (@/services/odpLoop)
//   decisions                       → getConnectors(env).decisions.decideAll over
//                                     CATALOG_FLAG_KEYS (Mock or Live per DECISION_SOURCE)
//
// Identity note: the ODP vuid remains SESSION-derived (SHA-256 of the DO-held
// sessionId, minted once per shopper object) until the identity cutover maps
// vuid ⇄ stable shopperId (doc 16 §8). "New shopper" rotates the client's
// visitor id → a fresh object → a fresh sessionId → a fresh vuid.
// ─────────────────────────────────────────────────────────────────────────────

import { actionOf, contentTouches, isContentAction } from '@/reflex/contentTelemetry';
import type { Env } from '@/types/env';
import { ACTION_EVENT_TYPE_SET } from '@/events/actionTypes';
import { applyHistorical, mergeReflexStates } from '@/reflex/identityMerge';
import { fanInRegionTrend } from '@/reflex/regionTrend';
import type { PersonalizationUpdate } from './PersonalizationWebSocket';
import {
  apply as applyReflex,
  attributesFrom as reflexAttributes,
  emptyState,
  extractTouches,
  touchesForEvent,
  nextCrossing,
  snapshot as reflexSnapshot,
  tick as tickReflex,
  type ReflexConfig,
  type ReflexResult,
  type ReflexState,
} from '@/reflex/core';
import { getConnectors, type Connectors } from '@/connectors';
import { CATALOG_FLAG_KEYS } from '@/connectors/DecisionProvider';
import { CatalogService } from '@/services/CatalogService';
import { deriveStage } from '@/services/JourneyStage';
import {
  RETAIL_SIGNAL_DEFAULTS,
  applyEventToAttributes,
  calculateEngagementScore,
  ensureAudiencesSeeded,
  hasSegmentChanges,
  type ActionEvent,
} from '@/services/RealtimeSegmentEngine';
import {
  forwardEventToOdp,
  mapActionToOdp,
  odpEnabled,
  refreshOdpSeedIfDue,
  updateOdpRing,
  upsertOdpProfile,
} from '@/services/odpLoop';
import {
  DEFAULT_SURFACE,
  audienceKeyPrefixFor,
  catalogServiceFor,
  resolveReflexConfig,
  resolveSurface,
  type DemoSurface,
} from '@/demos/registry';

/**
 * Storage key `'affinity'` — exactly the record doc 16 §6 / the P2 spec mandates.
 * `reflex` is raw (R, tLast) per dimension·value — NEVER pre-decayed (§4).
 */
export interface AffinityRecord {
  shopperId: string;
  reflex: ReflexState;
  odpSeed: string[];
  odpSeedAt: number;
  odpRecentEvents: Array<Record<string, unknown>>;
  lastSeen: number;
  configVersion: string;
}

/**
 * Storage key `'pipeline'` — the DO-side companion record that lets ingest() run
 * the SAME pipeline as the request path (behavioral counters → journey stage →
 * qualification → decisions). Kept under a SEPARATE key so `'affinity'` stays
 * byte-shaped to the spec. (Documented deviation: doc 16 §6 lists only the
 * affinity record; without these the DO could not qualify the counter-based seed
 * audiences or derive the journey stage the request path derives.)
 */
export interface PipelineRecord {
  attributes: Record<string, any>;
  segments: string[];
  journeyStage: 'early' | 'mid' | 'late';
  /** DO-held session id. No longer what the ODP vuid derives from — see visitorId. */
  sessionId: string;
  /**
   * The stable first-party visitor id (`opt_visitor_id`), which is also the name
   * this object is keyed on. Persisted for the same reason `surface` is: the
   * alarm and snapshot paths run with no event to resolve it from, and the ODP
   * vuid must not change just because a write happened on one of those paths.
   * ABSENT on records written before the CW7b cutover; those fall back to the
   * session id and keep exactly the identity they already had.
   */
  visitorId?: string;
  firstSeen: number;
  sessionCount: number;
  /** Demo surface this shopper object belongs to (@/demos/registry). ABSENT ⇒
      'coach' — every record written before the multi-surface split is retail's.
      Persisted because the alarm/snapshot paths have no event to resolve from. */
  surface?: DemoSurface;
}

interface IngestOutcome {
  status: number;
  body: Record<string, unknown>;
  update: PersonalizationUpdate | null;
}

/**
 * Event types accepted at this object's doors. The same list POST /realtime/action
 * validates against, imported rather than restated: this Set used to be written
 * out here beside a comment asking it to stay in step, and it did not. It was
 * missing `purchase` and all four content events, so the object answered 400 to
 * every content click and staging stayed on the slower session host (doc 31 §4).
 */
const ACTION_EVENT_TYPES = ACTION_EVENT_TYPE_SET;

/** Never set an alarm in the past; give the current event a beat to settle. */
const MIN_ALARM_DELAY_MS = 50;

/** Cheap per-minute in-DO rate limit (doc 16 §12) — override with REFLEX_RATE_LIMIT_PER_MIN. */
const DEFAULT_RATE_LIMIT_PER_MIN = 240;

const DEFAULT_RETENTION_DAYS = 30;

/**
 * Closed-form alarm time (doc 16 §6): the earlier of
 *   • the exact instant the earliest CURRENT membership decays below θ_out
 *     (core's nextCrossing — t* = tLast + τ·ln(R·(1−θ_out)/(K·θ_out))), and
 *   • the retention horizon (lastSeen + retentionMs — idle self-expiry, §12),
 * clamped to now+MIN_ALARM_DELAY_MS so a boundary crossing fires immediately but
 * never busy-loops. Pure — exported for the P2 test suite.
 */
export function computeNextAlarm(
  reflex: ReflexState,
  lastSeen: number,
  now: number,
  config: ReflexConfig,
  retentionMs: number
): number {
  const crossing = nextCrossing(reflex, now, config);
  const retentionAt = lastSeen + retentionMs;
  const at = crossing === null ? retentionAt : Math.min(crossing, retentionAt);
  return Math.max(at, now + MIN_ALARM_DELAY_MS);
}

// One catalog per isolate — the item-item graph precompute never runs per event.
let _catalog: CatalogService | null = null;
function catalog(): CatalogService {
  return (_catalog = _catalog ?? new CatalogService());
}

/**
 * The catalog a surface scores against. The default surface keeps the isolate-wide
 * instance above (same object, same graph); other surfaces resolve their own
 * memoized CatalogService from the registry — this is what makes the trust gate
 * below surface-aware instead of dropping every foreign product id (P4).
 */
async function catalogFor(surface: DemoSurface): Promise<CatalogService> {
  return surface === DEFAULT_SURFACE ? catalog() : catalogServiceFor(surface);
}

export class ShopperReflex {
  private state: DurableObjectState;
  /** CW25. The NAME of the person's object this browser's object forwards to; undefined until read. */
  private forwardTo: string | null | undefined = undefined;
  /**
   * CW31. The shopper's two consent switches, stored under their own key so the
   * instruction survives when nothing else may be written. Absent means
   * consenting. undefined until read.
   */
  private consent: { tracking: boolean; personalization: boolean } | null | undefined = undefined;
  private env: Env;

  /** In-memory mirrors of storage; rehydrated from ctx.storage on wake. */
  private affinity: AffinityRecord | null = null;
  private pipeline: PipelineRecord | null = null;
  private loaded = false;
  private seeded = new Set<DemoSurface>();

  /** Serializes ingest/alarm runs — the reducer is strictly sequential even when
      awaits on KV/ODP would otherwise let events interleave. */
  private chain: Promise<unknown> = Promise.resolve();

  /** Cheap per-minute rate limit. In-memory by design (zero storage writes): a
      hibernation wake resets it, but sustained bursts — the abuse case — keep the
      object alive, so the window holds exactly when it matters. */
  private rate = { windowStart: 0, count: 0 };
  private dropped = { rateLimited: 0, unknownProduct: 0, invalid: 0 };

  constructor(state: DurableObjectState, env: Env) {
    this.state = state;
    this.env = env;
  }

  // ── HTTP surface ────────────────────────────────────────────────────────────

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);

    if (request.headers.get('Upgrade') === 'websocket') {
      return this.handleUpgrade(url);
    }

    // CW25. A browser that was recognised forwards to the person's object: the
    // same ingest, the same snapshot, one hop. Nothing else is forwarded; the
    // identity doors below act on THIS object by design.
    if (url.pathname === '/ingest' || url.pathname === '/snapshot') {
      const forwarded = await this.forwardIfLinked(request);
      if (forwarded) return forwarded;
    }
    if (request.method === 'POST' && url.pathname === '/ingest') {
      return this.handleIngest(request);
    }
    if (request.method === 'GET' && url.pathname === '/snapshot') {
      return this.handleSnapshot();
    }
    // CW25, the identity doors. `export` reads what this browser learned;
    // `absorb` folds another object's export into this one, which then IS the
    // person; `forward` leaves this object pointing at the person's.
    if (request.method === 'GET' && url.pathname === '/identity/export') {
      await this.load();
      return json({ ok: true, affinity: this.affinity, pipeline: this.pipeline, forwardTo: await this.forwardTarget() });
    }
    if (request.method === 'POST' && url.pathname === '/identity/absorb') {
      return this.handleAbsorb(request);
    }
    if (request.method === 'POST' && url.pathname === '/identity/import') {
      return this.handleImport(request);
    }
    // CW31. The shopper's consent switches, as the site reports them. This is the
    // one write that happens even when tracking is off: it is the instruction
    // not to write, and it has to be remembered to be honoured.
    if (request.method === 'POST' && url.pathname === '/consent') {
      let body: { tracking?: unknown; personalization?: unknown } = {};
      try { body = await request.json(); } catch { return json({ ok: false, error: 'invalid JSON body' }, 400); }
      const consent = await this.setConsent(body);
      return json({ ok: true, consent });
    }
    if (request.method === 'POST' && url.pathname === '/identity/forward') {
      let body: { to?: unknown } = {};
      try { body = await request.json(); } catch { /* fallthrough */ }
      if (typeof body.to !== 'string' || body.to === '') return json({ ok: false, error: 'to required' }, 400);
      await this.state.storage.put('forwardTo', body.to);
      this.forwardTo = body.to;
      return json({ ok: true, forwardTo: body.to });
    }
    if (request.method === 'GET' && url.pathname === '/health') {
      await this.load();
      return json({
        status: 'healthy',
        shopperId: this.affinity?.shopperId ?? null,
        sockets: this.state.getWebSockets().length,
        audiences: this.affinity?.reflex.audiences ?? [],
        lastSeen: this.affinity?.lastSeen ?? null,
        dropped: this.dropped,
      });
    }
    // Erasure door (§12 privacy/lifecycle): wipes the vector + memberships.
    // GDPR/CCPA path and the operator's hard reset; retention uses the same wipe.
    if (request.method === 'POST' && url.pathname === '/reset') {
      await this.serialize(async () => {
        await this.state.storage.deleteAll();
        this.affinity = null;
        this.pipeline = null;
        this.forwardTo = null;
        this.consent = null;
        this.loaded = true;
      });
      return json({ ok: true });
    }

    return new Response('Not Found', { status: 404 });
  }

  // ── Door 1: the WebSocket (Hibernation API) ─────────────────────────────────

  private async handleUpgrade(url: URL): Promise<Response> {
    const shopperId = url.searchParams.get('userId');
    if (!shopperId) {
      return new Response('Missing userId parameter', { status: 400 });
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);

    // Hibernation accept: the runtime may evict this object between messages and
    // wake it on the next frame — near-zero idle cost, sockets stay connected.
    this.state.acceptWebSocket(server);
    // HARD RULE: the attachment carries ONLY {shopperId} (~2KB cap). All affinity
    // state lives in ctx.storage and rehydrates via load() on wake.
    server.serializeAttachment({ shopperId });

    // Same welcome frame the relay DO sends — client transport code is unchanged.
    server.send(
      JSON.stringify({
        type: 'connected',
        connectionId: crypto.randomUUID(),
        userId: shopperId,
        timestamp: Date.now(),
      })
    );

    return new Response(null, { status: 101, webSocket: client });
  }

  /** Hibernation handler — wakes the object on any client frame. */
  async webSocketMessage(ws: WebSocket, message: string | ArrayBuffer): Promise<void> {
    if (typeof message !== 'string') return;
    let frame: any;
    try {
      frame = JSON.parse(message);
    } catch {
      return;
    }
    if (!frame || typeof frame !== 'object') return;

    if (frame.type === 'heartbeat') {
      try {
        ws.send(JSON.stringify({ type: 'heartbeat_response', timestamp: Date.now() }));
      } catch { /* dying socket — close handler cleans up */ }
      return;
    }

    if (frame.type !== 'action') return; // subscribe/unsubscribe etc. — no-ops here

    const attachment = (safeAttachment(ws) ?? {}) as { shopperId?: string };
    const event = this.normalizeEvent(frame, attachment.shopperId);
    if (!event) {
      this.dropped.invalid++;
      return;
    }
    // Same reducer as POST /ingest; the outcome reaches the client as the push
    // this ingest emits over the DO's own sockets (no HTTP response on this door).
    await this.serialize(() => this.ingest(event));
  }

  async webSocketClose(_ws: WebSocket, _code: number, _reason: string, _wasClean: boolean): Promise<void> {
    // Nothing to clean: connection bookkeeping IS state.getWebSockets(); shopper
    // state persists in storage; the pending alarm keeps decay-out + retention live.
  }

  async webSocketError(_ws: WebSocket, error: unknown): Promise<void> {
    console.error('ShopperReflex webSocketError');
  }

  // ── Door 2: POST /ingest ────────────────────────────────────────────────────

  private async handleIngest(request: Request): Promise<Response> {
    let body: any;
    try {
      body = await request.json();
    } catch {
      return json({ success: false, error: 'invalid JSON body' }, 400);
    }
    const event = this.normalizeEvent(body, undefined);
    if (!event) {
      this.dropped.invalid++;
      return json({ success: false, error: 'invalid action event' }, 400);
    }
    const outcome = await this.serialize(() => this.ingest(event));
    return json(outcome.body, outcome.status);
  }

  /**
   * Accept either a bare ActionEvent (the POST /realtime/action body shape) or a
   * WS frame `{type:'action', event:{…}}` / flattened `{type:'action', action, data}`.
   */
  private normalizeEvent(raw: any, fallbackShopperId?: string): ActionEvent | null {
    const src = raw && typeof raw === 'object' && raw.event && typeof raw.event === 'object' ? raw.event : raw;
    if (!src || typeof src !== 'object') return null;

    const type =
      typeof src.type === 'string' && ACTION_EVENT_TYPES.has(src.type)
        ? src.type
        : typeof src.action === 'string' && ACTION_EVENT_TYPES.has(src.action)
          ? src.action
          : null;
    if (!type) return null;

    const userId = typeof src.userId === 'string' && src.userId ? src.userId : fallbackShopperId;
    if (!userId) return null;

    return {
      type: type as ActionEvent['type'],
      userId,
      ...(typeof src.anonymousId === 'string' ? { anonymousId: src.anonymousId } : {}),
      data: src.data && typeof src.data === 'object' ? src.data : {},
      source: typeof src.source === 'string' ? src.source : 'ws',
      ...(typeof src.surface === 'string' ? { surface: src.surface } : {}),
      // Advisory only — ingest() stamps its own arrival time (§4).
      timestamp: typeof src.timestamp === 'number' ? src.timestamp : Date.now(),
    };
  }

  // ── THE reducer: one handler behind both doors ──────────────────────────────

  private async ingest(event: ActionEvent): Promise<IngestOutcome> {
    // The ENGINE clock is authoritative — a forged/skewed client clock cannot
    // inflate affinity (doc 16 §4). Everything downstream uses this stamp.
    const now = Date.now();

    if (!this.allowIngest(now)) {
      this.dropped.rateLimited++;
      return {
        status: 429,
        body: { success: false, error: 'rate_limited', retryAfterMs: this.rate.windowStart + 60_000 - now },
        update: null,
      };
    }

    // Which demo posted this — resolved from the event alone (explicit field, else
    // `source`, else coach), so the trust gate below can consult the RIGHT catalog
    // before any storage read.
    const surface = resolveSurface({
      source: event.source,
      surface: event.surface ?? (event.data as Record<string, unknown> | undefined)?.surface as string | undefined,
    });
    const surfaceCatalog = await catalogFor(surface);
    const cfg = await resolveReflexConfig(this.env, surface);

    // Trust & abuse (§12): validate referenced products against the in-memory
    // catalog index — an unknown productId is dropped and counted, never scored.
    const data = event.data ?? {};
    const pid = data.productId ?? data.product_id ?? data.sku;
    const product = pid != null ? surfaceCatalog.getProduct(String(pid)) : undefined;
    // CW24: where the scope scores event-carried attributes, an unknown id with
    // registry attributes on it is a customer's product, not an abuse attempt.
    const eventTouches = !product && cfg.eventAttributes === 'event-when-unknown'
      ? touchesForEvent(data as Record<string, unknown>, undefined, cfg) : [];
    if (pid != null && !product && eventTouches.length === 0) {
      this.dropped.unknownProduct++;
      return {
        status: 200,
        body: {
          success: true,
          message: 'Action ignored: unknown productId',
          dropped: 'unknown_product',
          sessionId: this.pipeline?.sessionId ?? null,
          cookiesUpdated: false,
          consent: await this.consentNow(),
        },
        update: null,
      };
    }

    await this.load();
    await this.ensureSeeded(surface);
    const connectors = getConnectors(this.env); // fresh per run — mirrors the per-request triad

    // CW31. An event may carry the switches (`data.consent`); a change is
    // remembered before anything else happens. With tracking off, the pipeline
    // still answers this request from the state it has, but nothing it computes
    // is kept, forwarded or persisted: the object is restored to what it was.
    const eventConsent = data.consent;
    const consent = eventConsent && typeof eventConsent === 'object'
      ? await this.setConsent(eventConsent as { tracking?: unknown; personalization?: unknown })
      : await this.consentNow();
    const before = consent.tracking ? null : { affinity: structuredClone(this.affinity), pipeline: structuredClone(this.pipeline) };

    const aff: AffinityRecord = this.affinity ?? {
      shopperId: event.userId,
      reflex: emptyState(cfg),
      odpSeed: [],
      odpSeedAt: 0,
      odpRecentEvents: [],
      lastSeen: now,
      configVersion: cfg.version,
    };
    const pipe: PipelineRecord = this.pipeline ?? {
      attributes: {},
      segments: [],
      journeyStage: 'early',
      sessionId: crypto.randomUUID(),
      firstSeen: now,
      sessionCount: 0,
      // Only non-default surfaces are tagged, so a retail record's stored bytes
      // are exactly what they were before the split.
      ...(surface === DEFAULT_SURFACE ? {} : { surface }),
    };

    // The stable id rides in on every event as `userId`. Recorded once and kept,
    // so a later alarm or snapshot resolves the same vuid as a live event would.
    if (!pipe.visitorId && typeof event.userId === 'string' && event.userId !== '') {
      pipe.visitorId = event.userId;
    }

    // 1. Behavioral counters — the SAME accrual the request path runs.
    const attributes = { ...pipe.attributes };
    applyEventToAttributes(attributes, event, surfaceCatalog);
    const engagementScore = calculateEngagementScore(attributes);

    // 2. The pure core (§4): decay-then-accumulate + hysteresis evaluation.
    const reflexOn = (this.env.REFLEX_ENABLED ?? 'true') !== 'false';
    let reflex: ReflexResult | null = null;
    if (reflexOn) {
      const action = actionOf(event);
      reflex = applyReflex(
        aff.reflex,
        {
          action,
          touches: isContentAction(action)
            ? contentTouches(data as Record<string, unknown>, cfg)
            : product ? extractTouches(product as unknown as Record<string, unknown>, cfg) : eventTouches,
        },
        now,
        cfg
      );
      // CW6: the same touches, fanned into the shopper's region as a population count.
      // Registered with the object's own waitUntil so the call survives the reply.
      const keepAlive = (p: Promise<unknown>) => { try { (this.state as unknown as { waitUntil?: (p: Promise<unknown>) => void }).waitUntil?.(p); } catch { /* older runtime */ } };
      keepAlive(fanInRegionTrend(this.env, {
        tenant: surface, geo: (event as { geo?: { country?: string | null; regionCode?: string | null } }).geo, now,
        touches: product ? extractTouches(product as unknown as Record<string, unknown>, cfg) : eventTouches,
        w: cfg.weights[action] ?? 0,
      }));
    }

    // 3. Local qualification through the ODP seam (KvAudienceStore + evaluateCondition).
    const ctxAttrs: Record<string, any> = { ...RETAIL_SIGNAL_DEFAULTS, ...attributes };
    const qualCtx = {
      userId: aff.shopperId,
      anonymousId: event.anonymousId,
      attributes: ctxAttrs,
      segments: pipe.segments,
      surface, // qualification evaluates only THIS surface's audiences
    };
    const journeyStage = deriveStage(qualCtx);
    ctxAttrs.journey_stage = journeyStage;
    // Reflex scores are computed FRESH into the context (they decay by construction —
    // never persisted), so store-published affinity audiences can gte them.
    if (reflex) Object.assign(ctxAttrs, reflexAttributes(reflex.state, now, cfg));
    let localSegments: string[] = [];
    try {
      localSegments = await connectors.segments.fetchQualifiedSegments(aff.shopperId, qualCtx);
    } catch (e) {
      console.error('ShopperReflex qualification failed (degrading to reflex-only)');
    }

    // 4. ODP loop (§8) — same ring + seed policy as the request path (shared fns).
    let odpSeed = aff.odpSeed;
    let odpSeedAt = aff.odpSeedAt;
    let odpRing = aff.odpRecentEvents.slice();
    let odpReceipt: { receiptId: string; type: string; action?: string; product_id?: string } | undefined;
    const membershipChanged = !!reflex && (reflex.changes.entered.length > 0 || reflex.changes.exited.length > 0);
    if (odpEnabled(this.env)) {
      odpRing = updateOdpRing(odpRing, event, now);
      ({ seed: odpSeed, seedAt: odpSeedAt } = await refreshOdpSeedIfDue(
        this.env,
        { visitorId: pipe.visitorId, sessionId: pipe.sessionId },
        odpRing,
        { seed: odpSeed, seedAt: odpSeedAt },
        now,
        membershipChanged
      ));
      // Forward to the memory OFF the hot path. Fire-and-forget: a DO stays alive
      // while I/O is in flight, and forwardEventToOdp never throws. The receipt
      // lands over THIS object's own sockets — no relay hop.
      const mapped = mapActionToOdp(event);
      if (mapped) {
        odpReceipt = {
          receiptId: crypto.randomUUID(),
          type: mapped.type,
          ...(mapped.action ? { action: mapped.action } : {}),
          ...(typeof mapped.data.product_id === 'string' ? { product_id: mapped.data.product_id } : {}),
        };
        if (consent.tracking) {
          void forwardEventToOdp(this.env, event, { visitorId: pipe.visitorId, sessionId: pipe.sessionId }, odpReceipt.receiptId, (receipt) =>
            this.pushFrame({ type: 'odp_receipt', userId: aff.shopperId, data: receipt })
          );
        } else {
          odpReceipt = undefined;   // nothing left the edge
        }
      }
    }

    // 5. Union (local ∪ reflex ∪ ODP seed) + change detection — same triggers.
    // The surface namespace is applied to the core's membership keys here so they
    // match the generated audience keys (prefix '' for coach ⇒ same array).
    const prefix = audienceKeyPrefixFor(surface);
    const reflexAudiences = reflex
      ? prefix
        ? reflex.state.audiences.map((k) => prefix + k)
        : reflex.state.audiences
      : [];
    const newSegments = Array.from(
      new Set([...localSegments, ...reflexAudiences, ...odpSeed])
    );
    const segmentsChanged = hasSegmentChanges(pipe.segments, newSegments);
    const stageChanged = pipe.journeyStage !== journeyStage;

    // 6. Commit the new records to the in-memory mirrors.
    this.affinity = {
      shopperId: aff.shopperId,
      reflex: reflex ? reflex.state : aff.reflex,
      odpSeed,
      odpSeedAt,
      odpRecentEvents: odpRing,
      lastSeen: now,
      configVersion: cfg.version,
    };
    this.pipeline = {
      attributes,
      segments: newSegments,
      journeyStage,
      sessionId: pipe.sessionId,
      firstSeen: pipe.firstSeen,
      sessionCount: pipe.sessionCount + 1,
      ...(surface === DEFAULT_SURFACE ? {} : { surface }),
    };

    // 7. Changed? → decide + push over the DO's OWN sockets, in the same object.
    let update: PersonalizationUpdate | null = null;
    if (segmentsChanged || stageChanged) {
      update = await this.buildUpdate(connectors, now, event.source, reflex, engagementScore);
      this.pushFrame({ ...update, serverTimestamp: Date.now() });
      // §4 score upsert: on membership changes, persist the reflex's live scores
      // onto the ODP profile (the memory carrying the edge's numbers).
      const affPayload = update.data.affinity;
      if (consent.tracking && odpEnabled(this.env) && affPayload && membershipChanged) {
        void upsertOdpProfile(this.env, { visitorId: pipe.visitorId, sessionId: pipe.sessionId }, affPayload, journeyStage);
      }
    }

    // 8. Persist (single coalesced SQLite write, output-gated) + closed-form alarm.
    // CW31: with tracking off, nothing is written and the object forgets this
    // request; the answer above was computed, not kept.
    const sessionIdOut = this.pipeline.sessionId;
    if (before) {
      this.affinity = before.affinity;
      this.pipeline = before.pipeline;
    } else {
      await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
      await this.scheduleNextCrossing(now);
    }

    return {
      status: 200,
      body: {
        success: true,
        message: update
          ? 'Action processed and personalization updated'
          : 'Action processed, no personalization changes needed',
        ...(update ? { update } : {}),
        sessionId: sessionIdOut,
        cookiesUpdated: false, // identity is the stable visitor id — no session cookies on this host
        ...(odpReceipt ? { odp: odpReceipt } : {}),
        consent,
      },
      update,
    };
  }

  // ── The push envelope (same PersonalizationUpdate shape as the request path) ─

  private async buildUpdate(
    connectors: Connectors,
    now: number,
    source: string,
    reflex: ReflexResult | null,
    engagementScore: number
  ): Promise<PersonalizationUpdate> {
    const aff = this.affinity!;
    const pipe = this.pipeline!;
    const surface = this.surface();
    const cfg = await resolveReflexConfig(this.env, surface);
    const surfaceCatalog = await catalogFor(surface);
    const reflexOn = (this.env.REFLEX_ENABLED ?? 'true') !== 'false';

    const attributes: Record<string, any> = { ...RETAIL_SIGNAL_DEFAULTS, ...pipe.attributes };
    if (reflexOn) Object.assign(attributes, reflexAttributes(aff.reflex, now, cfg));

    const userAttributes = {
      segments: pipe.segments,
      ...attributes,
      engagement_score: engagementScore,
      session_count: pipe.sessionCount,
      journey_stage: pipe.journeyStage,
      days_since_first_seen: Math.floor((now - pipe.firstSeen) / (24 * 60 * 60 * 1000)),
      // No cookie-consent surface on this host (no PII either) — mirrors the
      // session path's defaults for a consenting shopper.
      tracking_consent: true,
      personalization_enabled: true,
    };

    const decisions = await connectors.decisions.decideAll(
      CATALOG_FLAG_KEYS,
      aff.shopperId,
      pipe.segments,
      userAttributes
    );
    const featureVariables: Record<string, any> = {};
    for (const [flagKey, decision] of Object.entries(decisions)) {
      featureVariables[flagKey] = decision.variables;
    }

    const anchorLine =
      typeof pipe.attributes.viewed_product_line === 'string'
        ? pipe.attributes.viewed_product_line
        : undefined;
    const recommendations = surfaceCatalog.getRecommendations({ line: anchorLine }, pipe.segments, 8);
    const sortOrder = surfaceCatalog
      .sortForSegments(null, pipe.segments, pipe.attributes)
      .slice(0, 24)
      .map((p) => p.id);

    return {
      type: 'personalization_update',
      userId: aff.shopperId,
      data: {
        segments: pipe.segments,
        decisions,
        featureVariables,
        recommendations,
        sortOrder,
        journeyStage: pipe.journeyStage,
        // Live affinity payload for the Affinity Instrument: dims (original catalog
        // value names) + memberships + this event's EXPLAIN records (§12 glass box)
        // + the ODP-confirmed subset — the exact shape the request path pushes.
        affinity: reflexOn
          ? {
              ...reflexSnapshot(aff.reflex, now, cfg),
              changed: reflex ? reflex.changes.explain : [],
              odpConfirmed: aff.odpSeed,
            }
          : undefined,
        sessionId: pipe.sessionId,
        engagementScore,
        timestamp: now,
        source,
      } as PersonalizationUpdate['data'],
    };
  }

  /** Push to every socket THIS object holds — never a cross-object hop. */
  private pushFrame(frame: unknown): void {
    const message = JSON.stringify(frame);
    for (const ws of this.state.getWebSockets()) {
      try {
        ws.send(message);
      } catch {
        /* runtime reaps dead hibernated sockets */
      }
    }
  }

  // ── Closed-form alarm: exit-by-decay without polling + retention ────────────

  private retentionMs(): number {
    const days = Number(this.env.REFLEX_RETENTION_DAYS ?? DEFAULT_RETENTION_DAYS);
    return (Number.isFinite(days) && days > 0 ? days : DEFAULT_RETENTION_DAYS) * 24 * 60 * 60 * 1000;
  }

  private async scheduleNextCrossing(now: number): Promise<void> {
    if (!this.affinity) return;
    const at = computeNextAlarm(
      this.affinity.reflex,
      this.affinity.lastSeen,
      now,
      await resolveReflexConfig(this.env, this.surface()),
      this.retentionMs()
    );
    await this.state.storage.setAlarm(at);
  }

  async alarm(): Promise<void> {
    await this.serialize(async () => {
      await this.load();
      if (!this.affinity) return; // already erased
      const now = Date.now();
      const surface = this.surface();
      const cfg = await resolveReflexConfig(this.env, surface);

      // Retention (§12): idle past N days with no live sockets → self-expire.
      if (now - this.affinity.lastSeen >= this.retentionMs() && this.state.getWebSockets().length === 0) {
        await this.state.storage.deleteAll();
        this.affinity = null;
        this.pipeline = null;
        return;
      }

      // Lazy re-evaluation: tick() NEVER accumulates — decay is read-time math, so
      // the alarm never mutates scores; it only re-reads them at `now` and applies
      // the θ_out exits the closed form predicted.
      const res = tickReflex(this.affinity.reflex, now, cfg);
      this.affinity = { ...this.affinity, reflex: res.state, configVersion: cfg.version };

      const exited = res.changes.exited.length > 0 || res.changes.entered.length > 0;
      if (exited && this.pipeline) {
        await this.ensureSeeded(surface);
        const connectors = getConnectors(this.env);
        // Re-run the qualification tail with the decayed memberships — the union
        // shrinks, decisions revert, and the "they wandered off" push goes out.
        const ctxAttrs: Record<string, any> = { ...RETAIL_SIGNAL_DEFAULTS, ...this.pipeline.attributes };
        const qualCtx = {
          userId: this.affinity.shopperId,
          attributes: ctxAttrs,
          segments: this.pipeline.segments,
          surface,
        };
        const journeyStage = deriveStage(qualCtx);
        ctxAttrs.journey_stage = journeyStage;
        Object.assign(ctxAttrs, reflexAttributes(res.state, now, cfg));
        let localSegments: string[] = [];
        try {
          localSegments = await connectors.segments.fetchQualifiedSegments(this.affinity.shopperId, qualCtx);
        } catch (e) {
          console.error('ShopperReflex alarm qualification failed');
        }
        let odpSeed = this.affinity.odpSeed;
        let odpSeedAt = this.affinity.odpSeedAt;
        if (odpEnabled(this.env)) {
          ({ seed: odpSeed, seedAt: odpSeedAt } = await refreshOdpSeedIfDue(
            this.env,
            { visitorId: this.pipeline?.visitorId, sessionId: this.pipeline?.sessionId ?? '' },
            this.affinity.odpRecentEvents,
            { seed: odpSeed, seedAt: odpSeedAt },
            now,
            true // membership changed — instant read, same policy as the ingest path
          ));
          this.affinity = { ...this.affinity, odpSeed, odpSeedAt };
        }
        const prefix = audienceKeyPrefixFor(surface);
        const newSegments = Array.from(
          new Set([
            ...localSegments,
            ...(prefix ? res.state.audiences.map((k) => prefix + k) : res.state.audiences),
            ...odpSeed,
          ])
        );
        const changed =
          hasSegmentChanges(this.pipeline.segments, newSegments) ||
          this.pipeline.journeyStage !== journeyStage;
        this.pipeline = { ...this.pipeline, segments: newSegments, journeyStage };

        if (changed) {
          const engagementScore = calculateEngagementScore(this.pipeline.attributes);
          const update = await this.buildUpdate(connectors, now, 'reflex_alarm', res, engagementScore);
          this.pushFrame({ ...update, serverTimestamp: Date.now() });
        }
      }

      await this.state.storage.put({
        affinity: this.affinity,
        ...(this.pipeline ? { pipeline: this.pipeline } : {}),
      });
      await this.scheduleNextCrossing(now); // next exit, or the retention horizon
    });
  }

  // ── Snapshot door (same shape as GET /realtime/reflex) ─────────────────────

  private async handleSnapshot(): Promise<Response> {
    await this.load();
    const cfg = await resolveReflexConfig(this.env, this.surface());
    const now = Date.now();
    return json({
      ok: true,
      now,
      // Shape mirrors the session-path handler in src/routes/realtime.ts (the
      // client's honest drain animation reads these) — keep the two in sync.
      config: {
        tauMs: cfg.tauMs,
        K: cfg.K,
        thetaIn: cfg.thetaIn,
        thetaOut: cfg.thetaOut,
        dims: Object.fromEntries(
          cfg.dimensions
            .filter((d) => d.tauMs || d.K || d.thetaIn || d.thetaOut)
            .map((d) => [d.key, { tauMs: d.tauMs, K: d.K, thetaIn: d.thetaIn, thetaOut: d.thetaOut }])
        ),
      },
      affinity: this.affinity
        ? {
            ...reflexSnapshot(this.affinity.reflex, now, cfg),
            odpConfirmed: this.affinity.odpSeed ?? [],
          }
        : null,
      // CW29: the stage this object last derived, so the content decision can
      // put it on the cell without recomputing from counters it does not hold.
      journeyStage: this.pipeline?.journeyStage ?? null,
      // CW31: the switches the content decision and the outcome path honour.
      consent: await this.consentNow(),
    });
  }

  // ── Plumbing ────────────────────────────────────────────────────────────────

  /** Rehydrate the in-memory mirrors from ctx.storage (one read for both keys). */
  // ── CW31: consent ──────────────────────────────────────────────────────────

  /** The stored switches, or consenting when nothing was ever said. */
  private async consentNow(): Promise<{ tracking: boolean; personalization: boolean }> {
    if (this.consent === undefined) {
      const stored = (await this.state.storage.get('consent')) as { tracking?: unknown; personalization?: unknown } | undefined;
      this.consent = stored ? { tracking: stored.tracking !== false, personalization: stored.personalization !== false } : null;
    }
    return this.consent ?? { tracking: true, personalization: true };
  }

  /** Merge what the site said into the stored switches. Only an explicit boolean changes a switch. */
  private async setConsent(body: { tracking?: unknown; personalization?: unknown }): Promise<{ tracking: boolean; personalization: boolean }> {
    const current = await this.consentNow();
    const next = {
      tracking: typeof body.tracking === 'boolean' ? body.tracking : current.tracking,
      personalization: typeof body.personalization === 'boolean' ? body.personalization : current.personalization,
    };
    if (next.tracking !== current.tracking || next.personalization !== current.personalization || this.consent === null) {
      this.consent = next;
      await this.state.storage.put('consent', next);
    }
    return next;
  }

  // ── CW25: identity ─────────────────────────────────────────────────────────

  private async forwardTarget(): Promise<string | null> {
    if (this.forwardTo === undefined) {
      this.forwardTo = ((await this.state.storage.get('forwardTo')) as string | undefined) ?? null;
    }
    return this.forwardTo;
  }

  /**
   * When this object forwards, hand the request to the person's object by its
   * stored name. The name carries the brand prefix already, so no tenant needs
   * to be known here. A socket upgrade is NOT forwarded: the client is told the
   * id to reconnect under, and reconnects.
   */
  private async forwardIfLinked(request: Request): Promise<Response | null> {
    const to = await this.forwardTarget();
    if (!to) return null;
    const stub = this.env.SHOPPER_REFLEX.get(this.env.SHOPPER_REFLEX.idFromName(to));
    const res = await stub.fetch(request);
    const body = await res.text();
    const headers = new Headers(res.headers);
    headers.set('X-Forwarded-Shopper', to);
    return new Response(body, { status: res.status, headers });
  }

  /**
   * Fold another object's export into this one. The reflex vectors merge on the
   * decay invariant; counters add; first seen is the earliest. This object
   * becomes the person: its shopper id is the canonical one from here on.
   */
  private async handleAbsorb(request: Request): Promise<Response> {
    let body: { shopperId?: unknown; affinity?: AffinityRecord | null; pipeline?: PipelineRecord | null; now?: unknown } = {};
    try { body = await request.json(); } catch { return json({ ok: false, error: 'invalid JSON body' }, 400); }
    if (typeof body.shopperId !== 'string' || body.shopperId === '') return json({ ok: false, error: 'shopperId required' }, 400);
    const shopperId = body.shopperId;
    const now = typeof body.now === 'number' ? body.now : Date.now();

    return this.serialize(async () => {
      await this.load();
      const cfg = await resolveReflexConfig(this.env, this.surface());
      const from = body.affinity ?? null;
      const fromPipe = body.pipeline ?? null;
      const merged = mergeReflexStates(this.affinity?.reflex, from?.reflex, now, cfg);

      this.affinity = {
        shopperId,
        reflex: merged.state,
        odpSeed: this.affinity?.odpSeed ?? from?.odpSeed ?? [],
        odpSeedAt: this.affinity?.odpSeedAt ?? from?.odpSeedAt ?? 0,
        odpRecentEvents: [...(from?.odpRecentEvents ?? []), ...(this.affinity?.odpRecentEvents ?? [])].slice(-10),
        lastSeen: Math.max(this.affinity?.lastSeen ?? 0, from?.lastSeen ?? 0) || now,
        configVersion: cfg.version,
      };
      const attributes: Record<string, any> = { ...(fromPipe?.attributes ?? {}), ...(this.pipeline?.attributes ?? {}) };
      for (const k of Object.keys(RETAIL_SIGNAL_DEFAULTS)) {
        const a = this.pipeline?.attributes?.[k]; const b = fromPipe?.attributes?.[k];
        if (typeof a === 'number' && typeof b === 'number') attributes[k] = a + b;
      }
      this.pipeline = {
        attributes,
        segments: [...new Set([...(this.pipeline?.segments ?? []), ...(fromPipe?.segments ?? []), ...merged.state.audiences])].sort(),
        journeyStage: this.pipeline?.journeyStage ?? fromPipe?.journeyStage ?? 'early',
        sessionId: this.pipeline?.sessionId ?? fromPipe?.sessionId ?? crypto.randomUUID(),
        visitorId: shopperId,
        firstSeen: Math.min(this.pipeline?.firstSeen ?? now, fromPipe?.firstSeen ?? now),
        sessionCount: (this.pipeline?.sessionCount ?? 0) + (fromPipe?.sessionCount ?? 0),
        surface: this.pipeline?.surface ?? fromPipe?.surface,
      };
      await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
      await this.scheduleNextCrossing(now);
      return json({ ok: true, shopperId, audiences: merged.state.audiences, changes: merged.changes });
    });
  }

  /**
   * Apply historical rows, each at its own time, then evaluate at now. Touches
   * arrive already extracted by the route against the registry; this object
   * only does the arithmetic, and touches nothing about visits or lastSeen.
   */
  private async handleImport(request: Request): Promise<Response> {
    let body: { shopperId?: unknown; rows?: unknown; now?: unknown } = {};
    try { body = await request.json(); } catch { return json({ ok: false, error: 'invalid JSON body' }, 400); }
    const rows = Array.isArray(body.rows) ? body.rows as Array<{ action: string; at: number; touches: Array<{ dim: string; value: string }> }> : [];
    const now = typeof body.now === 'number' ? body.now : Date.now();
    return this.serialize(async () => {
      await this.load();
      const cfg = await resolveReflexConfig(this.env, this.surface());
      let state = this.affinity?.reflex ?? null;
      for (const r of rows) state = applyHistorical(state, { action: r.action, touches: r.touches }, r.at, cfg);
      const evaluated = tickReflex(state, now, cfg);
      const shopperId = typeof body.shopperId === 'string' && body.shopperId ? body.shopperId : (this.affinity?.shopperId ?? '');
      this.affinity = {
        shopperId,
        reflex: evaluated.state,
        odpSeed: this.affinity?.odpSeed ?? [],
        odpSeedAt: this.affinity?.odpSeedAt ?? 0,
        odpRecentEvents: this.affinity?.odpRecentEvents ?? [],
        lastSeen: this.affinity?.lastSeen ?? 0,
        configVersion: cfg.version,
      };
      if (!this.pipeline) {
        this.pipeline = {
          attributes: {}, segments: [...evaluated.state.audiences], journeyStage: 'early',
          sessionId: crypto.randomUUID(), visitorId: shopperId, firstSeen: now, sessionCount: 0,
        };
      } else {
        this.pipeline = { ...this.pipeline, segments: [...new Set([...this.pipeline.segments, ...evaluated.state.audiences])].sort() };
      }
      await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
      await this.scheduleNextCrossing(now);
      return json({ ok: true, applied: rows.length, audiences: evaluated.state.audiences, changes: evaluated.changes });
    });
  }

  private async load(): Promise<void> {
    if (this.loaded) return;
    const stored = await this.state.storage.get(['affinity', 'pipeline']);
    this.affinity = (stored.get('affinity') as AffinityRecord | undefined) ?? null;
    this.pipeline = (stored.get('pipeline') as PipelineRecord | undefined) ?? null;
    this.loaded = true;
  }

  /** Same audiences the request path seeds (idempotent; version-gated to one KV read). */
  private async ensureSeeded(surface: DemoSurface = DEFAULT_SURFACE): Promise<void> {
    if (this.seeded.has(surface)) return;
    try {
      await ensureAudiencesSeeded(this.env, await catalogFor(surface), surface);
      this.seeded.add(surface);
    } catch (error) {
      console.error('ShopperReflex: audience seeding failed');
    }
  }

  /** The surface this shopper object belongs to (persisted; absent ⇒ coach). */
  private surface(): DemoSurface {
    return this.pipeline?.surface ?? DEFAULT_SURFACE;
  }

  private allowIngest(now: number): boolean {
    const limitRaw = Number(this.env.REFLEX_RATE_LIMIT_PER_MIN ?? DEFAULT_RATE_LIMIT_PER_MIN);
    const limit = Number.isFinite(limitRaw) && limitRaw > 0 ? limitRaw : DEFAULT_RATE_LIMIT_PER_MIN;
    if (now - this.rate.windowStart >= 60_000) {
      this.rate = { windowStart: now, count: 0 };
    }
    this.rate.count++;
    return this.rate.count <= limit;
  }

  private serialize<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.chain.then(fn, fn);
    this.chain = run.then(
      () => undefined,
      () => undefined
    );
    return run;
  }
}

function safeAttachment(ws: WebSocket): unknown {
  try {
    return ws.deserializeAttachment();
  } catch {
    return null;
  }
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

import type { Decision } from '@/connectors';

export interface PersonalizationUpdate {
  type: 'segment_update' | 'personalization_update' | 'feature_flag_update' | 'audience_published' | 'odp_receipt';
  userId: string;
  data: {
    segments?: string[];
    featureVariables?: Record<string, any>;
    cookies?: Record<string, string>;
    timestamp: number;
    source: string;
    decisions?: Record<string, Decision>;
    recommendations?: any[];
    sortOrder?: string[];
    journeyStage?: 'early' | 'mid' | 'late';
    audienceWentLive?: { key: string; name: string };
    /** Edge Affinity Reflex (doc 16): live per-dimension scores + memberships
        + the explain records for this event — feeds the Affinity Instrument. */
    affinity?: {
      dims: Record<string, Record<string, number>>;
      audiences: string[];
      changed?: unknown[];
      /** Audiences ODP's real-time segments ALSO confirm (the memory agreeing with the reflex). */
      odpConfirmed?: string[];
    };
  };
}

export interface WebSocketMessage {
  type: 'subscribe' | 'unsubscribe' | 'heartbeat' | 'update';
  userId?: string;
  data?: any;
}

export class PersonalizationWebSocket {
  private state: DurableObjectState;
  private connections: Map<string, WebSocket> = new Map();
  private userConnections: Map<string, Set<string>> = new Map();

  constructor(state: DurableObjectState) {
    this.state = state;
    this.state.blockConcurrencyWhile(async () => {
      // Load persisted connections state if needed
      const stored = await this.state.storage.get('connections');
      if (stored) {
        // Restore connection mappings (connections themselves can't be persisted)
        this.userConnections = new Map(stored as any);
      }
    });
  }

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);

    // Handle WebSocket upgrade
    if (request.headers.get('Upgrade') === 'websocket') {
      return this.handleWebSocketUpgrade(request);
    }

    // Handle HTTP API calls
    switch (url.pathname) {
      case '/broadcast':
        return this.handleBroadcast(request);
      case '/connections':
        return this.handleConnectionsInfo(request);
      case '/health':
        return new Response(JSON.stringify({ 
          status: 'healthy',
          connections: this.connections.size,
          users: this.userConnections.size 
        }), {
          headers: { 'Content-Type': 'application/json' }
        });
      default:
        return new Response('Not Found', { status: 404 });
    }
  }

  private async handleWebSocketUpgrade(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const userId = url.searchParams.get('userId');

    if (!userId) {
      return new Response('Missing userId parameter', { status: 400 });
    }

    const webSocketPair = new WebSocketPair();
    const [client, server] = Object.values(webSocketPair);

    server.accept();

    const connectionId = crypto.randomUUID();
    this.connections.set(connectionId, server);

    // Track user connections
    if (!this.userConnections.has(userId)) {
      this.userConnections.set(userId, new Set());
    }
    this.userConnections.get(userId)!.add(connectionId);

    // Set up event handlers
    server.addEventListener('message', (event) => {
      this.handleWebSocketMessage(connectionId, userId, event);
    });

    server.addEventListener('close', () => {
      this.handleWebSocketClose(connectionId, userId);
    });

    server.addEventListener('error', (error) => {
      console.error('WebSocket error');
      this.handleWebSocketClose(connectionId, userId);
    });

    // Send welcome message
    server.send(JSON.stringify({
      type: 'connected',
      connectionId,
      userId,
      timestamp: Date.now()
    }));

    // Persist connection state
    await this.saveConnectionState();

    return new Response(null, {
      status: 101,
      webSocket: client,
    });
  }

  private async handleWebSocketMessage(connectionId: string, userId: string, event: MessageEvent) {
    try {
      const message: WebSocketMessage = JSON.parse(event.data as string);

      switch (message.type) {
        case 'heartbeat':
          this.sendToConnection(connectionId, {
            type: 'heartbeat_response',
            timestamp: Date.now()
          });
          break;

        case 'subscribe':
          // User can subscribe to specific event types
          break;

        case 'unsubscribe':
          break;

        default:
          console.warn('Unknown message type');
      }
    } catch (error) {
      console.error('Error handling WebSocket message');
    }
  }

  private async handleWebSocketClose(connectionId: string, userId: string) {
    this.connections.delete(connectionId);

    const userConnections = this.userConnections.get(userId);
    if (userConnections) {
      userConnections.delete(connectionId);
      if (userConnections.size === 0) {
        this.userConnections.delete(userId);
      }
    }

    await this.saveConnectionState();
  }

  private async handleBroadcast(request: Request): Promise<Response> {
    try {
      const update: PersonalizationUpdate = await request.json();
      await this.broadcastUpdate(update);

      return new Response(JSON.stringify({ 
        success: true, 
        broadcast: true,
        connections: this.getUserConnections(update.userId).length
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (error) {
      return new Response(JSON.stringify({ 
        error: 'Failed to broadcast update',
        details: error instanceof Error ? error.message : 'Unknown error'
      }), { 
        status: 500,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  }

  private async handleConnectionsInfo(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const userId = url.searchParams.get('userId');

    if (userId) {
      return new Response(JSON.stringify({
        userId,
        connections: this.getUserConnections(userId).length,
        connected: this.getUserConnections(userId).length > 0
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    }

    return new Response(JSON.stringify({
      totalConnections: this.connections.size,
      totalUsers: this.userConnections.size,
      users: Array.from(this.userConnections.keys())
    }), {
      headers: { 'Content-Type': 'application/json' }
    });
  }

  async broadcastUpdate(update: PersonalizationUpdate): Promise<void> {
    const userConnections = this.getUserConnections(update.userId);

    const message = JSON.stringify({
      ...update,
      serverTimestamp: Date.now()
    });

    const broadcastPromises = userConnections.map(async (connectionId) => {
      try {
        const connection = this.connections.get(connectionId);
        if (connection && connection.readyState === WebSocket.READY_STATE_OPEN) {
          connection.send(message);
        } else {
          // Clean up dead connections
          this.connections.delete(connectionId);
          const userConnections = this.userConnections.get(update.userId);
          if (userConnections) {
            userConnections.delete(connectionId);
          }
        }
      } catch (error) {
        console.error('Error sending to connection');
      }
    });

    await Promise.all(broadcastPromises);

    // Save state after cleanup
    if (userConnections.length > 0) {
      await this.saveConnectionState();
    }
  }

  async broadcastToAll(update: Omit<PersonalizationUpdate, 'userId'>): Promise<void> {
    const message = JSON.stringify({
      ...update,
      scope: 'global',
      serverTimestamp: Date.now()
    });

    const broadcastPromises = Array.from(this.connections.entries()).map(async ([connectionId, connection]) => {
      try {
        if (connection.readyState === WebSocket.READY_STATE_OPEN) {
          connection.send(message);
        }
      } catch (error) {
        console.error('Error broadcasting to connection');
      }
    });

    await Promise.all(broadcastPromises);
  }

  private getUserConnections(userId: string): string[] {
    const userConnections = this.userConnections.get(userId);
    return userConnections ? Array.from(userConnections) : [];
  }

  private sendToConnection(connectionId: string, data: any): void {
    const connection = this.connections.get(connectionId);
    if (connection && connection.readyState === WebSocket.READY_STATE_OPEN) {
      connection.send(JSON.stringify(data));
    }
  }

  private async saveConnectionState(): Promise<void> {
    try {
      await this.state.storage.put('connections', Array.from(this.userConnections.entries()));
    } catch (error) {
      console.error('Error saving connection state');
    }
  }

  // Cleanup method for old connections
  async cleanup(): Promise<void> {
    const deadConnections: string[] = [];

    for (const [connectionId, connection] of this.connections.entries()) {
      if (connection.readyState !== WebSocket.READY_STATE_OPEN) {
        deadConnections.push(connectionId);
      }
    }

    for (const connectionId of deadConnections) {
      this.connections.delete(connectionId);

      // Remove from user connections
      for (const [userId, userConnections] of this.userConnections.entries()) {
        userConnections.delete(connectionId);
        if (userConnections.size === 0) {
          this.userConnections.delete(userId);
        }
      }
    }

    if (deadConnections.length > 0) {
      await this.saveConnectionState();
      console.log(`Cleaned up ${deadConnections.length} dead connections`);
    }
  }
}

