import { meridianRoutes } from '@/demos/meridian/routes';
import { decisionRoutes } from '@/routes/decisions';
import { MeridianReflex } from '@/demos/meridian/MeridianReflex';

import { RegionTrend } from '@/durable-objects/RegionTrend';
import { DecisionRing } from '@/durable-objects/DecisionRing';
import { LearnStats } from '@/durable-objects/LearnStats';
import { rollupTenant } from '@/reflex/regionTrend';
import { consumeLedger } from '@/ledger/consume';
import { runCycle } from '@/learn/cycle';

export { StateManager, RateLimiter, PersonalizationWebSocket, ShopperReflex, OpalAgent, MeridianReflex, RegionTrend, DecisionRing, LearnStats };

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    // The obsolete raw-store API is unavailable before binding discovery,
    // logging or CORS. Use Hono's decoding so encoded aliases are covered too.
    const path = getPath(request);
    if (path === '/api' || path.startsWith('/api/')) {
      return new Response(request.method === 'HEAD' ? null : '{"error":"Not Found"}', {
        status: 404,
        headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
      });
    }
    // Route /agents/* to the Cloudflare Agents SDK (Opal chat). Returns null for
    // every other path, so all existing Hono routes are untouched.
    const agentResponse = await routeAgentRequest(request, env);
    if (agentResponse) return agentResponse;
    return app.fetch(request, env, ctx);
  },
  scheduled: async (event: ScheduledEvent, env: Env, ctx: ExecutionContext) => {
    switch (event.cron) {
      case '*/5 * * * *': {
        // The platform watching itself (src/ops/monitor.ts): every store, and a real decision, per tenant.
        for (const tenant of tenantConfig(env).provisioned) {
          ctx.waitUntil(runMonitor(env, tenant).then(
            (r) => { if (!r.ok) console.error('monitor check failed; problems', r.problems.length); },
            (e) => console.error('monitor failed to run'),
          ));
        }
        // Doc 31 §3: the closed hours the ledger holds, folded into their aggregates, oldest first, two per run;
        // then the day report of each date touched, so GET learn/report answers for today through the last closed hour.
        for (const tenant of tenantConfig(env).provisioned) {
          ctx.waitUntil((async () => {
            const learn = await read<LearnConfig>(env, LEARN_KIND, tenant, DEFAULT_LEARN);
            const r = await catchUp(env.STORAGE as unknown as Parameters<typeof catchUp>[0], tenant, learn);
            if (r.built.length) console.log('hourly fold completed; hours/objects/decisions/outcomes/truncated/pending', r.built.length, r.built.reduce((n, b) => n + b.objects, 0), r.built.reduce((n, b) => n + b.decisions, 0), r.built.reduce((n, b) => n + b.outcomes, 0), r.built.filter((b) => b.truncated).length, r.pending);
            if (r.failed.length) console.error('hourly fold hours failed and skipped', r.failed.length);
          })().catch((e) => console.error('hourly fold failed')));
        }
        break;
      }
      case '0 3 * * *': {
        // Doc 22 §11: the autonomy cycle, daily. Slots in configured mode are untouched.
        const tenants = (env.TREND_ROLLUP_TENANTS ?? 'coach').split(',').map((t) => t.trim()).filter(Boolean);
        for (const tenant of tenants) {
          ctx.waitUntil(runCycle(env, tenant).then(
            (r) => console.log('autonomy cycle; actions/slots', r.filter((x) => x.action !== 'none').length, r.length),
            (e) => console.error('autonomy cycle failed'),
          ));
        }
        // Doc 31: yesterday's day report, built once by the platform and read by the console with GET.
        const yesterday = new Date(Date.now() - 86_400_000).toISOString().slice(0, 10);
        for (const tenant of tenantConfig(env).provisioned) {
          ctx.waitUntil((async () => {
            const learn = await read<LearnConfig>(env, LEARN_KIND, tenant, DEFAULT_LEARN);
            const r = await runDayReport(env.STORAGE as unknown as Parameters<typeof runDayReport>[0], { tenant, brand: tenant, date: yesterday }, learn, null);
            console.log('day report; decisions/outcomes/unfolded/truncated', Number.isFinite(r.counts.decisions) ? r.counts.decisions : -1, Number.isFinite(r.counts.outcomes) ? r.counts.outcomes : -1, r.hours?.missing.length ?? 0, r.counts.truncated ? 1 : 0);
          })().catch((e) => console.error('day report failed')));
        }
        // CW28 (doc 22 §15): the erasure rewrite. Newest day first over the retention window, capped per run, resumes tomorrow.
        for (const tenant of tenantConfig(env).provisioned) {
          ctx.waitUntil(rewriteErasures(env.STORAGE as unknown as R2Erasable, tenant, { retentionDays: retentionDays(env) }).then(
            (r) => { if (r.tombstones) console.log('erasure rewrite; rows/objects/days/retired/pending/more', r.rows_removed, r.objects_opened, r.days.length, r.retired, r.remaining, r.more ? 1 : 0); },
            (e) => console.error('erasure rewrite failed'),
          ));
        }
        break;
      }
      case '0 * * * *': {
        // CW6: sum each tenant's published regions into its countries and into everyone.
        const tenants = (env.TREND_ROLLUP_TENANTS ?? 'coach').split(',').map((t) => t.trim()).filter(Boolean);
        for (const tenant of tenants) {
          ctx.waitUntil(rollupTenant(env, tenant).then(
            (r) => console.log('trend rollup; regions/countries', r.regions, r.countries.length),
            (e) => console.error('trend rollup failed'),
          ));
        }
        break;
      }
      default:
        console.log('Unknown scheduled event');
    }
  },
  queue: async (batch: MessageBatch, env: Env, ctx: ExecutionContext) => {
    // Phase 0 of the outcome-learning design: every ledger message in the batch is
    // written to R2 in one pass, as range-named objects under the brand and hour.
    // Only an R2 failure retries; anything the writer cannot place is acknowledged
    // and counted, so a poison message can never stall the ledger behind it.
    const ledger = batch.messages.filter((m) => (m.body as { kind?: unknown } | null)?.kind === 'ledger');
    if (ledger.length) {
      const res = await consumeLedger(env, ledger.map((m) => m.body));
      if (res.ok) { for (const m of ledger) m.ack(); }
      else { console.error('ledger batch failed'); for (const m of ledger) m.retry(); }
      if (res.skipped) console.warn(`ledger: ${res.skipped} unplaceable message(s) acknowledged and dropped`);
    }
    for (const message of batch.messages) {
      if ((message.body as { kind?: unknown } | null)?.kind === 'ledger') continue;
      try {
        const event = message.body as any;
        if (event && event.kind === 'scene') {
          // Background styled-scene generation → R2 (so the request path never blocks on ~8s gen).
          const res = await generateSceneToR2(env, event);
          if (!res.ok) console.error('queue scene failed');
          message.ack(); // ack even on a handled failure — no poison loop; client falls back to the grid
        } else {
          message.ack();
        }
      } catch (error) {
        console.error('Error processing message');
        message.retry(); // transient/unexpected → retry
      }
    }
  },
};

// src/sdk/core.ts
// The shared core: identity, the event bus, and transport. Non-negotiable as a
// shared piece because events and decisions must be keyed to the same visitor
// id and one socket serves both directions. Extracted from the demo storefront:
// the socket URL, the welcome frame, the reconnect delay, the action envelope
// and the POST-versus-push dedupe are its behavior, verbatim.

import { currentSessionId, DEFAULT_VISITOR_KEY, entrySignals, mintAnonId, mintVisitorId, writeVisitorId } from './identity';
import { toWire } from './wire';
import type {
  ActionEnvelope, ClientConfig, CoreEvents, DecisionSet, EngineUpdate, EntrySignals, Host, Paths,
  SdkEventType, SocketLike, SocketStatus,
} from './types';

export const DEFAULT_PATHS: Paths = {
  action: '/realtime/action',
  ws: '/realtime/ws',
  reflex: '/realtime/reflex',
  snapshot: '/v1/{tenant}/decisions/snapshot',
  identityLink: '/v1/{tenant}/identity/link',
  identityDetach: '/v1/{tenant}/identity/detach',
};

export interface ResolvedConfig {
  tenant: string;
  brand?: string;
  endpoint: string;
  sdkKey?: string;
  source: string;
  surface?: string;
  listenOnly: boolean;
  heartbeatMs: number;
  reconnectMs: number;
  hydrateTimeoutMs: number;
  visitorIdKey: string;
  paths: Paths;
}

export function resolveConfig(c: ClientConfig, host: Host): ResolvedConfig {
  const origin = host.location ? `${host.location.protocol}//${host.location.host}` : '';
  return {
    tenant: c.tenant,
    ...(c.brand ? { brand: c.brand } : {}),
    endpoint: (c.endpoint ?? origin).replace(/\/+$/, ''),
    ...(c.sdkKey ? { sdkKey: c.sdkKey } : {}),
    source: c.source ?? 'sdk',
    ...(c.surface ? { surface: c.surface } : {}),
    listenOnly: Boolean(c.listenOnly),
    heartbeatMs: c.heartbeatMs ?? 25_000,
    reconnectMs: c.reconnectMs ?? 3_000,
    hydrateTimeoutMs: c.hydrateTimeoutMs ?? 1_500,
    visitorIdKey: c.visitorIdKey ?? DEFAULT_VISITOR_KEY,
    paths: { ...DEFAULT_PATHS, ...(c.paths ?? {}) },
  };
}

export interface SendOptions {
  /** Fire-and-forget through the beacon API, for page-hide moments. */
  beacon?: boolean;
  keepalive?: boolean;
}

export interface Core {
  readonly config: ResolvedConfig;
  readonly host: Host;
  readonly visitorId: string;
  readonly anonId: string;
  readonly sessionId: string;
  readonly entry: EntrySignals;
  readonly socketStatus: SocketStatus;
  on<K extends keyof CoreEvents>(event: K, fn: CoreEvents[K]): () => void;
  emit<K extends keyof CoreEvents>(event: K, ...args: Parameters<CoreEvents[K]>): void;
  /** The envelope POST /realtime/action validates, for this event. Pure. */
  envelope(type: SdkEventType, data?: Record<string, unknown>): ActionEnvelope;
  send(type: SdkEventType, data?: Record<string, unknown>, opts?: SendOptions): Promise<EngineUpdate | null>;
  url(path: string, query?: Record<string, string | undefined>): string;
  headers(extra?: Record<string, string>): Record<string, string>;
  getJson(path: string, query?: Record<string, string | undefined>): Promise<unknown | null>;
  /** POST JSON with the site key and credentials; never throws. */
  postJson(path: string, body: unknown): Promise<{ ok: boolean; status: number; json: unknown }>;
  /** CW25: the browser now carries this id. Writes both stores, announces the change, reconnects the socket if it was open. */
  setVisitorId(id: string, reason: 'identified' | 'logout'): void;
  connect(): void;
  disconnect(): void;
  /** Apply an engine update from either door, once. */
  applyIncoming(update: EngineUpdate, fromPush: boolean, rttMs: number | null): void;
}

export function createCore(config: ClientConfig, host: Host): Core {
  const cfg = resolveConfig(config, host);
  let visitorId = mintVisitorId(host, cfg.visitorIdKey);
  const anonId = mintAnonId(host);
  let sessionId = currentSessionId(host);
  /** The session as of now: the same id until the shopper has been idle for thirty minutes, then a new one. */
  const session = () => { sessionId = currentSessionId(host); return sessionId; };
  const entry = entrySignals(host);

  const listeners = new Map<string, Set<(...args: unknown[]) => void>>();
  function on<K extends keyof CoreEvents>(event: K, fn: CoreEvents[K]): () => void {
    const set = listeners.get(event) ?? new Set();
    set.add(fn as (...args: unknown[]) => void);
    listeners.set(event, set);
    return () => { set.delete(fn as (...args: unknown[]) => void); };
  }
  function emit<K extends keyof CoreEvents>(event: K, ...args: Parameters<CoreEvents[K]>): void {
    for (const fn of listeners.get(event) ?? []) { try { fn(...args); } catch { /* a listener must never break the page */ } }
  }

  // A shopper's own action returns the update in the POST response AND echoes
  // it over the socket. Apply once: both carry the same server timestamp.
  let lastAppliedTs: number | undefined;
  function applyIncoming(update: EngineUpdate, fromPush: boolean, rttMs: number | null): void {
    if (typeof update.timestamp === 'number') {
      if (fromPush && update.timestamp === lastAppliedTs) return;
      lastAppliedTs = update.timestamp;
    }
    emit('update', update, { fromPush, rttMs });
  }

  function url(path: string, query?: Record<string, string | undefined>): string {
    const base = `${cfg.endpoint}${path.replace('{tenant}', encodeURIComponent(cfg.tenant))}`;
    const parts = Object.entries(query ?? {}).filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`);
    return parts.length ? `${base}?${parts.join('&')}` : base;
  }
  function headers(extra: Record<string, string> = {}): Record<string, string> {
    return { ...(cfg.sdkKey ? { 'X-SDK-Key': cfg.sdkKey } : {}), ...extra };
  }

  function envelope(type: SdkEventType, data: Record<string, unknown> = {}): ActionEnvelope {
    const w = toWire(type, data);
    return {
      type: w.type,
      userId: visitorId,
      anonymousId: anonId,
      sessionId: session(),
      data: w.data,
      source: cfg.source,
      ...(cfg.surface ? { surface: cfg.surface } : {}),
      entry,
      timestamp: host.now(),
    };
  }

  async function send(type: SdkEventType, data: Record<string, unknown> = {}, opts: SendOptions = {}): Promise<EngineUpdate | null> {
    const env = envelope(type, data);
    const body = JSON.stringify(env);
    const target = url(cfg.paths.action);
    if (opts.beacon && host.sendBeacon) {
      let ok = false;
      try { ok = host.sendBeacon(target, body); } catch { ok = false; }
      if (ok) { emit('sent', env, { via: 'beacon' }); return null; }
    }
    const t0 = host.now();
    try {
      const res = await host.fetch(target, {
        method: 'POST', headers: headers({ 'Content-Type': 'application/json' }), credentials: 'include', body,
        ...(opts.keepalive ? { keepalive: true } : {}),
      });
      const json = (await res.json()) as { update?: { data?: EngineUpdate }; odp?: unknown } | null;
      emit('sent', env, { via: 'fetch' });
      if (json?.odp) emit('receipt', json.odp, { via: 'fetch' });
      const update = json?.update?.data ?? null;
      if (update) applyIncoming(update, false, host.now() - t0);
      return update;
    } catch {
      return null;
    }
  }

  async function getJson(path: string, query?: Record<string, string | undefined>): Promise<unknown | null> {
    try {
      const res = await host.fetch(url(path, query), { method: 'GET', headers: headers(), credentials: 'include' });
      return await res.json();
    } catch {
      return null;
    }
  }

  async function postJson(path: string, body: unknown): Promise<{ ok: boolean; status: number; json: unknown }> {
    try {
      const res = await host.fetch(url(path), { method: 'POST', headers: headers({ 'Content-Type': 'application/json' }), credentials: 'include', body: JSON.stringify(body) });
      let json: unknown = null;
      try { json = await res.json(); } catch { json = null; }
      return { ok: res.ok, status: res.status, json };
    } catch {
      return { ok: false, status: 0, json: null };
    }
  }

  function setVisitorId(id: string, reason: 'identified' | 'logout'): void {
    const previous = visitorId;
    if (!id || id === previous) return;
    visitorId = id;
    writeVisitorId(host, cfg.visitorIdKey, id);
    emit('identity', { visitorId: id, previous, reason });
    // Pushes go to the object named by the id: a socket still open under the old one hears nothing.
    if (wanted) { disconnect(); connect(); }
  }

  // ── The socket ──────────────────────────────────────────────────────────────
  let socket: SocketLike | null = null;
  let status: SocketStatus = host.openSocket ? 'closed' : 'unavailable';
  let wanted = false;
  let heartbeat: unknown = null;
  let reconnectTimer: unknown = null;

  function setStatus(s: SocketStatus): void { status = s; emit('socket', s); }

  function socketUrl(): string | null {
    if (!cfg.endpoint) return null;
    const base = cfg.endpoint.replace(/^http(s?):/, (_m, secure: string) => `ws${secure}:`);
    const q = new URLSearchParams({ userId: visitorId, ...(cfg.sdkKey ? { sdkKey: cfg.sdkKey } : {}) });
    return `${base}${cfg.paths.ws}?${q.toString()}`;
  }

  function handleFrame(raw: unknown): void {
    let msg: { type?: string; data?: Record<string, unknown>; [k: string]: unknown };
    try { msg = typeof raw === 'string' ? JSON.parse(raw) : (raw as typeof msg); } catch { return; }
    if (!msg || typeof msg !== 'object') return;
    const data = (msg.data ?? {}) as Record<string, unknown>;
    switch (msg.type) {
      case 'connected': setStatus('connected'); return;
      case 'heartbeat_response': return;
      case 'odp_receipt': emit('receipt', data, { via: 'push' }); return;
      case 'content_decisions': emit('decisions', msg as unknown as DecisionSet); return;
      default: break;
    }
    if (msg.type === 'audience_published' || data.audienceWentLive) emit('audience', data.audienceWentLive ?? msg.audienceWentLive ?? data);
    if (msg.type === 'personalization_update' || msg.type === 'segment_update' || data.segments) {
      const ms = typeof data.decisionMs === 'number' ? data.decisionMs : null;
      applyIncoming(data as EngineUpdate, true, ms);
    }
  }

  function stopHeartbeat(): void { if (heartbeat !== null) { host.clearInterval(heartbeat); heartbeat = null; } }

  function connect(): void {
    wanted = true;
    if (!host.openSocket) { setStatus('unavailable'); return; }
    const target = socketUrl();
    if (!target) { setStatus('unavailable'); return; }
    if (reconnectTimer !== null) { host.clearTimeout(reconnectTimer); reconnectTimer = null; }
    setStatus('connecting');
    try { socket = host.openSocket(target); } catch { setStatus('error'); return; }
    const s = socket;
    s.onopen = () => {
      setStatus('connected');
      stopHeartbeat();
      heartbeat = host.setInterval(() => {
        if (s.readyState === 1) { try { s.send(JSON.stringify({ type: 'heartbeat' })); } catch { /* dying socket */ } }
      }, cfg.heartbeatMs);
    };
    s.onmessage = (ev) => handleFrame(ev.data);
    s.onerror = () => setStatus('error');
    s.onclose = () => {
      stopHeartbeat();
      if (!wanted) { setStatus('closed'); return; }
      setStatus('reconnecting');
      reconnectTimer = host.setTimeout(() => { reconnectTimer = null; if (wanted) connect(); }, cfg.reconnectMs);
    };
  }

  function disconnect(): void {
    wanted = false;
    stopHeartbeat();
    if (reconnectTimer !== null) { host.clearTimeout(reconnectTimer); reconnectTimer = null; }
    try { socket?.close(); } catch { /* ignore */ }
    socket = null;
    setStatus('closed');
  }

  return {
    config: cfg, host, anonId, entry,
    get visitorId() { return visitorId; },
    get sessionId() { return session(); },
    get socketStatus() { return status; },
    on, emit, envelope, send, url, headers, getJson, postJson, setVisitorId, connect, disconnect, applyIncoming,
  };
}

// src/sdk/identity.ts
// First-party identity, no fingerprinting. The visitor id is what every event
// and every decision is keyed on, and what the shopper's own object is named
// by, so it must be the same across tabs and reloads: localStorage first, the
// cookie as fallback, both written. The formats are the demo storefront's,
// verbatim, so a visitor known to the demo is the same visitor to the SDK.

import type { EntrySignals, Host } from './types';

export const DEFAULT_VISITOR_KEY = 'opt_visitor_id';
const YEAR_SECONDS = 60 * 60 * 24 * 365;

export function mintVisitorId(host: Host, key = DEFAULT_VISITOR_KEY): string {
  let id: string | null = null;
  try { id = host.storage.get(key); } catch { /* storage may be unavailable */ }
  if (!id) { try { id = host.cookie.get(key); } catch { /* cookies may be blocked */ } }
  if (!id) id = freshVisitorId(host);
  writeVisitorId(host, key, id);
  return id;
}

/** A brand-new anonymous visitor id, the format the storefront mints. */
export function freshVisitorId(host: Host): string {
  return `vis-${host.uuid()}`;
}

/** Both stores, the same format: what identify() and logout() write when the id changes (CW25). */
export function writeVisitorId(host: Host, key: string, id: string): void {
  try { host.storage.set(key, id); } catch { /* ignore */ }
  try { host.cookie.set(key, id, YEAR_SECONDS); } catch { /* ignore */ }
}

/** Per page load, for legacy capture paths that still key on it. */
export function mintAnonId(host: Host): string {
  return `v-${host.uuid().replace(/-/g, '').slice(0, 9).toUpperCase()}`;
}

/**
 * The browsing session: one id across page loads and tabs until the shopper has been idle for
 * `idleMs` (30 minutes by default, the convention analytics tools share). Kept in storage as
 * `{ id, at }`; every event touches `at`. This is the session attribution's "session scope" means:
 * the decision carries it and the outcome carries it, so the two can be compared.
 */
export const DEFAULT_SESSION_KEY = 'opt_session';
export const DEFAULT_SESSION_IDLE_MS = 30 * 60 * 1000;

export function currentSessionId(host: Host, key = DEFAULT_SESSION_KEY, idleMs = DEFAULT_SESSION_IDLE_MS): string {
  const now = host.now();
  let stored: { id?: unknown; at?: unknown } | null = null;
  try { const raw = host.storage.get(key); stored = raw ? (JSON.parse(raw) as { id?: unknown; at?: unknown }) : null; } catch { stored = null; }
  const id = stored && typeof stored.id === 'string' && typeof stored.at === 'number' && now - stored.at < idleMs ? stored.id : mintSessionId(host);
  try { host.storage.set(key, JSON.stringify({ id, at: now })); } catch { /* storage may be unavailable: the id lives for this load */ }
  return id;
}

export function mintSessionId(host: Host): string {
  return `s-${host.now().toString(36).toUpperCase()}${host.uuid().replace(/-/g, '').slice(0, 6).toUpperCase()}`;
}

/**
 * How this page load arrived: captured once from the current document and sent
 * with every action, because the client cannot know which event will be the
 * one that crosses a visit boundary. The server decides that.
 */
export function entrySignals(host: Host): EntrySignals {
  let utmMedium = '', utmSource = '';
  try {
    const usp = new URLSearchParams(host.location?.search ?? '');
    utmMedium = usp.get('utm_medium') ?? '';
    utmSource = usp.get('utm_source') ?? '';
  } catch { /* no search */ }
  return { utmMedium, utmSource, referrer: host.referrer ?? '', siteHost: host.location?.hostname ?? '' };
}

// src/sdk/identify.ts
// CW25, the client half of identity stitching (docs/architecture/25-identity-stitching.md §4).
// identify() tells the edge which account this browser belongs to; on success the
// browser carries the person's shopper id as its visitor id from then on, and the
// socket reconnects under it, because pushes go to the object named by the id.
// logout() detaches, mints a fresh anonymous id, and reconnects under that. The
// assertion is always computed by the site's backend and handed to the page.
// A proof provider can obtain a fresh visitor-bound assertion after a 409 and
// successful detach; static proof is never reused for a different visitor.

import type { Core } from './core';
import { freshVisitorId } from './identity';

export interface IdentifyOptions {
  /** HMAC from the site's backend over tenant, visitorId, accountId and exp (see signAssertion). */
  assertion?: string;
  /** Unix seconds the assertion expires, at most 24 h ahead. */
  exp?: number;
  /** Obtain backend proof for this exact request. Called again after a successful 409 detach. */
  getAssertion?: (claim: { tenant: string; visitorId: string; accountId: string }) =>
    { assertion: string; exp: number } | Promise<{ assertion: string; exp: number }>;
  /** Where the sign-in happened, for the audit trail: 'login', 'checkout', … */
  source?: string;
}

export type IdentifyResult =
  | { ok: true; shopperId: string; visitorId: string; outcome: string | null; retried: boolean }
  | { ok: false; status: number; error: string; retried: boolean };

export interface LogoutResult { ok: boolean; status: number; visitorId: string }

export interface Identity {
  identify(accountId: string, options?: IdentifyOptions): Promise<IdentifyResult>;
  logout(): Promise<LogoutResult>;
}

export function createIdentity(core: Core): Identity {
  const failure = (error: string, status = 0, retried = false): IdentifyResult => ({ ok: false, status, error, retried });
  async function attempt(accountId: string, o: IdentifyOptions, retry = false): Promise<
    { visitorId: string; response: Awaited<ReturnType<Core['postJson']>> } | { failure: IdentifyResult }
  > {
    const visitorId = core.visitorId;
    let assertion = o.assertion, exp = o.exp;
    if (o.getAssertion !== undefined) {
      try {
        if (typeof o.getAssertion !== 'function') return { failure: failure('identity proof provider invalid') };
        const proof = await o.getAssertion({ tenant: core.config.tenant, visitorId, accountId });
        if (core.visitorId !== visitorId) return { failure: failure('identity changed during identify') };
        assertion = proof?.assertion; exp = proof?.exp;
        if (typeof assertion !== 'string' || !assertion.trim() || assertion.length > 200 || !Number.isInteger(exp)) {
          return { failure: failure('identity proof provider returned invalid proof') };
        }
      } catch {
        return { failure: failure('identity proof provider failed') };
      }
    }
    if (core.visitorId !== visitorId) return { failure: failure('identity changed during identify') };
    const response = await core.postJson(core.config.paths.identityLink, {
      visitorId, accountId,
      ...(o.source ? { source: o.source } : {}),
      ...(typeof exp === 'number' ? { exp } : {}),
      ...(assertion ? { assertion } : {}),
    });
    if (core.visitorId !== visitorId) return { failure: failure('identity changed during identify', 0, retry) };
    return { visitorId, response };
  }

  async function logout(): Promise<LogoutResult> {
    const previous = core.visitorId;
    const res = await core.postJson(core.config.paths.identityDetach, { visitorId: previous });
    core.setVisitorId(freshVisitorId(core.host), 'logout');
    return { ok: res.ok, status: res.status, visitorId: core.visitorId };
  }

  async function identify(accountId: string, options: IdentifyOptions = {}): Promise<IdentifyResult> {
    if (!accountId || typeof accountId !== 'string') return { ok: false, status: 0, error: 'accountId required', retried: false };
    let retried = false;
    let attempted = await attempt(accountId, options);
    if ('failure' in attempted) return attempted.failure;
    if (core.visitorId !== attempted.visitorId) return failure('identity changed during identify');
    if (attempted.response.status === 409 && options.getAssertion !== undefined) {
      // A retry needs successful detach AND proof for the freshly minted id.
      const detached = await core.postJson(core.config.paths.identityDetach, { visitorId: attempted.visitorId });
      if (core.visitorId !== attempted.visitorId) return failure('identity changed during identify');
      const body = detached.json as { ok?: unknown; detached?: unknown } | null;
      if (!detached.ok || body?.ok !== true || body?.detached !== true) return failure('identity detach failed', detached.status);
      const fresh = freshVisitorId(core.host);
      core.setVisitorId(fresh, 'logout');
      if (core.visitorId !== fresh) return failure('identity changed during identify');
      attempted = await attempt(accountId, options, true);
      if ('failure' in attempted) return attempted.failure;
      retried = true;
    }
    if (core.visitorId !== attempted.visitorId) return failure('identity changed during identify', 0, retried);
    const res = attempted.response;
    const body = (res.json ?? {}) as { ok?: boolean; carry?: unknown; shopperId?: unknown; outcome?: unknown; error?: unknown };
    const shopperId = typeof body.carry === 'string' ? body.carry : typeof body.shopperId === 'string' ? body.shopperId : null;
    if (!res.ok || body.ok === false || !shopperId) {
      return { ok: false, status: res.status, error: typeof body.error === 'string' ? body.error : 'link refused', retried };
    }
    core.setVisitorId(shopperId, 'identified');
    return { ok: true, shopperId, visitorId: core.visitorId, outcome: typeof body.outcome === 'string' ? body.outcome : null, retried };
  }

  return { identify, logout };
}

// src/sdk/listen.ts
// The listen module: decisions in, defaults guaranteed. A page hydrates from the
// snapshot at first paint, subscribes per slot, and is told plainly when there
// is nothing — because the page never waits on us and never shows a hole.

import type { Core } from './core';
import type { ContentDecision, DecisionSet, ElementLike } from './types';

export interface HydrateOptions {
  page: string;
  /** The entry channel, if the page knows it; recorded on the decision's cell. */
  channel?: string;
}

export type SlotCallback = (decisions: ContentDecision[], set: DecisionSet) => void;
export type SetCallback = (set: DecisionSet | null) => void;

export interface Listen {
  /** Fetch the first-paint snapshot and apply it. Resolves null on absence or failure, never rejects. */
  hydrate(opts: HydrateOptions): Promise<DecisionSet | null>;
  /**
   * Called with the slot's decisions, in order, every time a set arrives —
   * with an empty array when the set has nothing for the slot, so a page can
   * revert to its default. Returns the unsubscribe function.
   */
  subscribe(slot: string, cb: SlotCallback): () => void;
  /** Called with each set as it arrives, and with null on graceful absence. */
  onDecisions(cb: SetCallback): () => void;
  /** Apply a set from any source (a socket frame, a server-rendered payload). */
  apply(set: DecisionSet): void;
  current(): DecisionSet | null;
  /**
   * Tell the SDK what was painted. The automatic capture path starts here: an
   * impression is sent once per slot and piece, and dwell is measured while the
   * element is on screen when one is given. Off in listen-only mode.
   */
  rendered(slot: string, contentId: string, el?: ElementLike): void;
}

export interface ListenOptions {
  /** Minimum on-screen time before a dwell event is worth sending. */
  dwellMinMs?: number;
}

export function createListen(core: Core, opts: ListenOptions = {}): Listen {
  const host = core.host;
  const dwellMinMs = opts.dwellMinMs ?? 1_000;
  const slotSubs = new Map<string, Set<SlotCallback>>();
  const setSubs = new Set<SetCallback>();
  const impressed = new Set<string>();
  let current: DecisionSet | null = null;

  function notifyAbsence(): void { for (const cb of setSubs) { try { cb(null); } catch { /* never break the page */ } } }

  function apply(set: DecisionSet): void {
    current = set;
    impressed.clear();
    const bySlot = new Map<string, ContentDecision[]>();
    for (const d of set.decisions ?? []) { const list = bySlot.get(d.slot) ?? []; list.push(d); bySlot.set(d.slot, list); }
    for (const list of bySlot.values()) list.sort((a, b) => a.order - b.order);
    for (const [slot, subs] of slotSubs) {
      const list = bySlot.get(slot) ?? [];
      for (const cb of subs) { try { cb(list, set); } catch { /* never break the page */ } }
    }
    for (const cb of setSubs) { try { cb(set); } catch { /* never break the page */ } }
  }

  core.on('decisions', (set) => apply(set));

  async function hydrate(o: HydrateOptions): Promise<DecisionSet | null> {
    let settled = false;
    let timedOut = false;
    const timer = host.setTimeout(() => { if (!settled) { timedOut = true; notifyAbsence(); } }, core.config.hydrateTimeoutMs);
    const json = (await core.getJson(core.config.paths.snapshot, {
      page: o.page, visitorId: core.visitorId, sessionId: core.sessionId, brand: core.config.brand, channel: o.channel,
    })) as { ok?: boolean; page?: string; arm?: string; versions?: Record<string, number>; config_label?: string; decisions?: unknown; ts?: number } | null;
    settled = true;
    host.clearTimeout(timer);
    if (!json || json.ok !== true || !Array.isArray(json.decisions)) {
      if (!timedOut) notifyAbsence();
      return null;
    }
    const set: DecisionSet = {
      page: json.page ?? o.page,
      ...(json.arm ? { arm: json.arm } : {}),
      ...(json.versions ? { versions: json.versions } : {}),
      ...(json.config_label ? { config_label: json.config_label } : {}),
      ...(typeof json.ts === 'number' ? { ts: json.ts } : {}),
      decisions: json.decisions as ContentDecision[],
    };
    // A late snapshot after the timeout is still applied: absence first, then
    // the decision when it arrives. The page never waited.
    apply(set);
    return set;
  }

  function subscribe(slot: string, cb: SlotCallback): () => void {
    const set = slotSubs.get(slot) ?? new Set<SlotCallback>();
    set.add(cb);
    slotSubs.set(slot, set);
    if (current) {
      const list = (current.decisions ?? []).filter((d) => d.slot === slot).sort((a, b) => a.order - b.order);
      try { cb(list, current); } catch { /* ignore */ }
    }
    return () => { set.delete(cb); };
  }

  function onDecisions(cb: SetCallback): () => void {
    setSubs.add(cb);
    return () => { setSubs.delete(cb); };
  }

  function rendered(slot: string, contentId: string, el?: ElementLike): void {
    if (core.config.listenOnly) return;
    const key = `${slot}:${contentId}`;
    if (impressed.has(key)) return;
    impressed.add(key);
    const piece = (current?.decisions ?? []).find((d) => d.slot === slot && d.contentId === contentId);
    const data = { contentId, slot, ...(piece ? { customerContentId: piece.customerContentId, contentType: piece.type } : {}) };
    void core.send('content_impression', data);
    if (el && host.dom) {
      let shownAt: number | null = null;
      const off = host.dom.observe(el, (visible) => {
        if (visible) { if (shownAt === null) shownAt = host.now(); return; }
        if (shownAt === null) return;
        const ms = host.now() - shownAt;
        shownAt = null;
        if (ms >= dwellMinMs) void core.send('content_dwell', { ...data, ms });
        off();
      });
    }
  }

  return { hydrate, subscribe, onDecisions, apply, current: () => current, rendered };
}

// src/sdk/types.ts
// The customer SDK, one package with a shared core and two modules (the decision
// recorded in the delivery guide and the BTI architecture §12). Everything the
// SDK touches in a browser arrives through `Host`, so the same code runs in
// Node under test and is a port, not a rewrite, on a native client.

export interface ClientConfig {
  /** The scope the decisions are made for. Tenancy (CW1) binds it server-side. */
  tenant: string;
  brand?: string;
  /** Base URL of the platform. Defaults to the page's own origin. */
  endpoint?: string;
  /** Sent as a header on fetches and a query on the socket. Enforced by CW10. */
  sdkKey?: string;
  /** Names the caller on every event. */
  source?: string;
  /** Optional demo surface; the engine resolves tuning by it. */
  surface?: string;
  /**
   * Listen-only: the SDK's own capture paths (automatic and declarative) stay
   * off, for a customer keeping their existing analytics pipeline. The explicit
   * API and the dataLayer adapter still send, because they are that pipeline.
   */
  listenOnly?: boolean;
  heartbeatMs?: number;
  reconnectMs?: number;
  /** How long hydrate() waits for the snapshot before declaring graceful absence. */
  hydrateTimeoutMs?: number;
  /** Storage key for the first-party visitor id. Shared with the demo storefront by default. */
  visitorIdKey?: string;
  paths?: Partial<Paths>;
}

export interface Paths {
  action: string;
  ws: string;
  reflex: string;
  /** Receives `{tenant}` substitution. */
  snapshot: string;
  /** CW25: the identity stitching routes the client half calls. */
  identityLink: string;
  identityDetach: string;
}

/** A WebSocket-shaped thing. The browser's WebSocket satisfies it; tests fake it. */
export interface SocketLike {
  readyState: number;
  onopen: ((ev?: unknown) => void) | null;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onclose: ((ev?: unknown) => void) | null;
  onerror: ((ev?: unknown) => void) | null;
  send(data: string): void;
  close(): void;
}

export interface ElementLike {
  getAttribute(name: string): string | null;
  addEventListener(type: string, listener: (ev: unknown) => void): void;
}

/** The slice of a document the declarative capture path needs. */
export interface DomLike {
  querySelectorAll(selector: string): ArrayLike<ElementLike> & Iterable<ElementLike>;
  /** Visibility callbacks: `visible` true when at least half the element is on screen. */
  observe(el: ElementLike, cb: (visible: boolean) => void): () => void;
}

export interface Host {
  now(): number;
  uuid(): string;
  storage: { get(key: string): string | null; set(key: string, value: string): void };
  cookie: { get(key: string): string | null; set(key: string, value: string, maxAgeSeconds: number): void };
  location: { href: string; host: string; hostname: string; protocol: string; search: string } | null;
  referrer: string;
  fetch: (url: string, init?: RequestInitLike) => Promise<ResponseLike>;
  sendBeacon?: (url: string, body: string) => boolean;
  openSocket?: (url: string) => SocketLike;
  setTimeout(fn: () => void, ms: number): unknown;
  clearTimeout(handle: unknown): void;
  setInterval(fn: () => void, ms: number): unknown;
  clearInterval(handle: unknown): void;
  /** Fires on page hide / unload, for the beacon path. */
  onPageHide?: (fn: () => void) => void;
  dom?: DomLike;
  /** window.dataLayer, when a tag layer exists. */
  dataLayer?: unknown[];
}

export interface RequestInitLike {
  method?: string;
  headers?: Record<string, string>;
  body?: string;
  credentials?: 'include' | 'omit' | 'same-origin';
  keepalive?: boolean;
}
export interface ResponseLike { ok: boolean; status: number; json(): Promise<unknown> }

// ── Events ──────────────────────────────────────────────────────────────────

/** What the SDK lets an integrator say happened. */
export type SdkEventType =
  | 'page_view' | 'product_view' | 'add_to_cart' | 'wishlist_add' | 'purchase'
  | 'content_impression' | 'content_click' | 'content_dwell' | 'video_complete'
  | 'email_open' | 'form_submit' | 'button_click' | 'custom';

export interface EntrySignals { utmMedium: string; utmSource: string; referrer: string; siteHost: string }

/** The envelope POST /realtime/action validates. Field for field what the demo storefront sends. */
export interface ActionEnvelope {
  type: string;
  userId: string;
  anonymousId: string;
  sessionId: string;
  data: Record<string, unknown>;
  source: string;
  surface?: string;
  entry: EntrySignals;
  timestamp: number;
}

// ── Decisions ───────────────────────────────────────────────────────────────

/** One decision from GET /v1/:tenant/decisions/snapshot, or a `content_decisions` frame. */
export interface ContentDecision {
  contentId: string;
  customerContentId: string;
  type: string;
  slot: string;
  order: number;
  score: number;
  strategy: 'affinity' | 'default' | 'tenant-pinned';
  explain: { drivers: Array<{ dim: string; value: string; a: number; weight: number }>; note?: string };
}

export interface DecisionSet {
  page: string;
  arm?: string;
  versions?: Record<string, number>;
  config_label?: string;
  decisions: ContentDecision[];
  ts?: number;
}

/** What the engine pushes after an action: the demo storefront applies this whole. */
export interface EngineUpdate {
  timestamp?: number;
  segments?: string[];
  affinity?: unknown;
  decisions?: Record<string, unknown>;
  recommendations?: unknown[];
  sortOrder?: string[];
  journeyStage?: string;
  decisionMs?: number;
  [k: string]: unknown;
}

export type SocketStatus = 'connecting' | 'connected' | 'reconnecting' | 'error' | 'closed' | 'unavailable';

export interface CoreEvents {
  update: (update: EngineUpdate, meta: { fromPush: boolean; rttMs: number | null }) => void;
  decisions: (set: DecisionSet) => void;
  /** An ODP receipt: from the POST response (`fetch`, the dispatch) or the socket (`push`, ODP answered). */
  receipt: (receipt: unknown, meta: { via: 'fetch' | 'push' }) => void;
  audience: (audience: unknown) => void;
  socket: (status: SocketStatus) => void;
  sent: (envelope: ActionEnvelope, meta: { via: 'fetch' | 'beacon' | 'socket' }) => void;
  /** CW25: the visitor id changed, because a person signed in (identified) or out (logout). */
  identity: (change: { visitorId: string; previous: string; reason: 'identified' | 'logout' }) => void;
}

// src/sdk/host.ts
// Two hosts. `browserHost` binds the real browser. `memoryHost` runs the same
// SDK with nothing behind it: tests, server-side rendering, and the shape a
// native port fills in. Everything DOM-shaped in the SDK is reached through
// these, and only here.

import type { DomLike, ElementLike, Host, SocketLike } from './types';
export { memoryHost } from './memoryHost';


function domOf(doc: Document, win: Window & typeof globalThis): DomLike {
  return {
    querySelectorAll: (sel) => Array.from(doc.querySelectorAll(sel)) as unknown as ArrayLike<ElementLike> & Iterable<ElementLike>,
    observe: (el, cb) => {
      if (typeof win.IntersectionObserver !== 'function') { cb(true); return () => {}; }
      const io = new win.IntersectionObserver((entries) => {
        for (const e of entries) cb(e.intersectionRatio >= 0.5);
      }, { threshold: [0, 0.5] });
      io.observe(el as unknown as Element);
      return () => io.disconnect();
    },
  };
}

export function browserHost(): Host {
  const win = globalThis as unknown as Window & typeof globalThis;
  const doc: Document | undefined = typeof document !== 'undefined' ? document : undefined;
  const loc = typeof location !== 'undefined' ? location : undefined;
  const nav = typeof navigator !== 'undefined' ? navigator : undefined;
  const cookieRe = (k: string) => new RegExp(`(?:^|;\\s*)${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}=([^;]+)`);
  return {
    now: () => Date.now(),
    uuid: () => (win.crypto && typeof win.crypto.randomUUID === 'function')
      ? win.crypto.randomUUID()
      : `${Math.random().toString(36).slice(2)}${Date.now().toString(36)}`,
    storage: {
      get: (k) => { try { return win.localStorage.getItem(k); } catch { return null; } },
      set: (k, v) => { try { win.localStorage.setItem(k, v); } catch { /* blocked */ } },
    },
    cookie: {
      get: (k) => { try { return (doc?.cookie.match(cookieRe(k)) ?? [])[1] ?? null; } catch { return null; } },
      set: (k, v, maxAge) => { try { if (doc) doc.cookie = `${k}=${v}; Max-Age=${maxAge}; Path=/; SameSite=Lax`; } catch { /* blocked */ } },
    },
    location: loc ? { href: loc.href, host: loc.host, hostname: loc.hostname, protocol: loc.protocol, search: loc.search } : null,
    referrer: doc?.referrer ?? '',
    fetch: (url, init) => win.fetch(url, init as RequestInit),
    ...(nav && typeof nav.sendBeacon === 'function'
      ? { sendBeacon: (url: string, body: string) => { try { return nav.sendBeacon(url, new Blob([body], { type: 'application/json' })); } catch { return false; } } }
      : {}),
    ...(typeof win.WebSocket === 'function' ? { openSocket: (url: string) => new win.WebSocket(url) as unknown as SocketLike } : {}),
    setTimeout: (fn, ms) => win.setTimeout(fn, ms),
    clearTimeout: (h) => win.clearTimeout(h as number),
    setInterval: (fn, ms) => win.setInterval(fn, ms),
    clearInterval: (h) => win.clearInterval(h as number),
    onPageHide: (fn) => {
      try { win.addEventListener('pagehide', fn); } catch { /* ignore */ }
      try { doc?.addEventListener('visibilitychange', () => { if (doc.visibilityState === 'hidden') fn(); }); } catch { /* ignore */ }
    },
    ...(doc ? { dom: domOf(doc, win) } : {}),
    ...(Array.isArray((win as unknown as { dataLayer?: unknown }).dataLayer)
      ? { dataLayer: (win as unknown as { dataLayer: unknown[] }).dataLayer } : {}),
  };
}

// src/sdk/testHost.ts — a browser with nothing behind it, for the SDK's own tests.
import { memoryHost } from './memoryHost';
import type { Host, RequestInitLike, ResponseLike, SocketLike } from './types';

export class FakeSocket implements SocketLike {
  readyState = 0;
  onopen: ((ev?: unknown) => void) | null = null;
  onmessage: ((ev: { data: unknown }) => void) | null = null;
  onclose: ((ev?: unknown) => void) | null = null;
  onerror: ((ev?: unknown) => void) | null = null;
  sent: string[] = [];
  constructor(public url: string) {}
  send(data: string): void { this.sent.push(data); }
  close(): void { this.readyState = 3; this.onclose?.(); }
  open(): void { this.readyState = 1; this.onopen?.(); }
  receive(frame: unknown): void { this.onmessage?.({ data: JSON.stringify(frame) }); }
}

export interface Call { url: string; init?: RequestInitLike }

export function testHost(opts: {
  responses?: (url: string, init?: RequestInitLike) => unknown | Promise<unknown>;
  location?: Host['location'];
  referrer?: string;
  withSocket?: boolean;
  now?: () => number;
} = {}) {
  const calls: Call[] = [];
  const sockets: FakeSocket[] = [];
  const beacons: Array<{ url: string; body: string }> = [];
  let clock = 1_725_000_000_000;
  const host = memoryHost({
    now: opts.now ?? (() => clock),
    uuid: () => '0f0f0f0f-1111-2222-3333-444444444444',
    location: opts.location ?? { href: 'https://shop.example/home?utm_source=tiktok&utm_medium=paid_social', host: 'shop.example', hostname: 'shop.example', protocol: 'https:', search: '?utm_source=tiktok&utm_medium=paid_social' },
    referrer: opts.referrer ?? 'https://www.tiktok.com/',
    fetch: async (url, init): Promise<ResponseLike> => {
      calls.push({ url, init });
      const body = opts.responses ? await opts.responses(url, init) : { success: true };
      return { ok: true, status: 200, json: async () => body };
    },
    sendBeacon: (url, body) => { beacons.push({ url, body }); return true; },
    ...(opts.withSocket === false ? {} : { openSocket: (url: string) => { const s = new FakeSocket(url); sockets.push(s); return s; } }),
  });
  return { host, calls, sockets, beacons, tick: (ms: number) => { clock += ms; } };
}

// src/routes/identity.test.ts
//
// CW25 through the wire, on the session host: a phone and a laptop browse as
// strangers, both sign in to the same account, and the person is the sum. Then
// the rules around the edges: the assertion, the shopper-id refusal, the shared
// computer, detach, history in both formats, and who may ask what.

import { describe, it, expect, beforeEach, vi } from 'vitest';
import * as jose from 'jose';
import type { Env } from '@/types/env';
import { identityRoutes } from '@/routes/identity';
import { SessionManager } from '@/services/SessionManager';
import { DEFAULT_REFLEX_CONFIG, apply, audienceKey, emptyState, snapshot, type ReflexState } from '@/reflex/core';
import { signAssertion } from '@/identity/assertion';
import { shopperIdFor } from '@/identity/shopperId';
import { createCore } from '@/sdk/core';
import { createIdentity } from '@/sdk/identify';
