describe('erase: the right to be forgotten (CW28)', () => {
  it('forgets a person: links, both browsers\u2019 profiles, the person\u2019s session, and a tombstone per id', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    await seedDevice('vis-laptop', 's-laptop', ['Rogue']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-laptop', accountId: 'acct-1001' } });
    const sh = a.body.shopperId as string;

    const r = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { visitorId: 'vis-phone' } });
    expect(r.status).toBe(200);
    expect(r.body.shopperId).toBe(sh);
    expect([...r.body.erased].sort()).toEqual([sh, 'vis-laptop', 'vis-phone'].sort());
    expect(r.body.links).toEqual({ visitors: 2, shopper: true });
    expect(r.body.profiles.every((p: { result: string }) => p.result === 'erased' || p.result === 'absent')).toBe(true);
    expect(r.body.ledger.map((l: { id: string; tombstone: string | null }) => [l.id, !!l.tombstone]).every(([, t]: [string, boolean]) => t)).toBe(true);
    expect(r.body.notReached[0]).toMatch(/ODP/);
    expect(r.body.notReached.slice(1)).toEqual([
      'Analytics Engine: historical subject-bearing route events are not erased by this operation; dataset contents, retention and disposition remain unverified',
      'Worker/application logs: historical request, event and subject data are not erased by this operation; other logging paths remain and retention/disposition are unverified',
    ]);
    expect(env.ANALYTICS).toBeUndefined(); // Historical limits are unconditional, not a current-binding check.
    expect(r.body.actor).toBe('ops');

    // Nothing resolves to the person any more, and the person's session is gone.
    const sm = new SessionManager(env);
    expect(await sm.resolveSessionIdByUserId(sh)).toBeNull();
    expect(await sm.resolveSessionIdByUserId('vis-phone')).toBeNull();
    // The browsers' own pre-link records, which only the link remembered, are gone too.
    expect(await sm.readRaw('s-phone')).toBeNull();
    expect(await sm.readRaw('s-laptop')).toBeNull();
    expect((await call('/coach/identity/visitor/vis-laptop', { headers: auth })).body.shopperId).toBeNull();
    expect((await call(`/coach/identity/shopper/${sh}`, { headers: auth })).status).toBe(404);
    // The tombstones the ledger's readers honour at once.
    const r2 = (env as unknown as { STORAGE: FakeR2 }).STORAGE;
    expect([...r2.store.keys()].filter((k) => k.startsWith('erasures/coach/pending/'))).toHaveLength(3);
  });

  it('forgets an unlinked browser on its own', async () => {
    await seedDevice('vis-alone', 's-alone', ['Tabby']);
    const r = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { visitorId: 'vis-alone' } });
    expect(r.body.shopperId).toBeNull();
    expect(r.body.erased).toEqual(['vis-alone']);
    expect(r.body.profiles[0]).toMatchObject({ id: 'vis-alone', host: 'session', result: 'erased' });
  });

  it('accepts a shopper id directly, and is idempotent', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const first = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { shopperId: a.body.shopperId } });
    expect(first.body.links.visitors).toBe(1);
    const again = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { shopperId: a.body.shopperId } });
    expect(again.status).toBe(200);
    expect(again.body.links.visitors).toBe(0);
    expect(again.body.profiles[0].result).toBe('absent');
    expect(again.body.notReached).toEqual(first.body.notReached);
  });

  it('wants the operator token and a real id', async () => {
    expect((await call('/coach/identity/erase', { method: 'POST', json: { visitorId: 'vis-1' } })).status).toBe(401);
    expect((await call('/coach/identity/erase', { method: 'POST', headers: auth, json: {} })).status).toBe(400);
    expect((await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { shopperId: 'not-a-shopper' } })).status).toBe(400);
  });
});

// src/routes/realtime.sdkContract.test.ts
// The SDK's wire table against the server's own validator: every event the SDK
// can send must parse through actionEventSchema exactly as POST /realtime/action
// would parse it. When the server learns a new first-class type, the SDK row
// changes and this test is what says the two still agree.

import { describe, it, expect } from 'vitest';
import { actionEventSchema } from './realtime';
import { createCore } from '../sdk/core';
import { memoryHost } from '../sdk/memoryHost';
import { WIRE } from '../sdk/wire';
import type { SdkEventType } from '../sdk/types';

describe('SDK ↔ /realtime/action contract', () => {
  const core = createCore({ tenant: 'coach', source: 'sdk', surface: 'coach' }, memoryHost({ uuid: () => 'u' }));

  it('every SDK event type produces an envelope the server accepts', () => {
    for (const type of Object.keys(WIRE) as SdkEventType[]) {
      const env = core.envelope(type, { productId: 'SKU-1', contentId: 'c1', slot: 'hero' });
      const parsed = actionEventSchema.safeParse(env);
      expect(parsed.success, `${type} → ${env.type}: ${parsed.success ? '' : JSON.stringify(parsed.error.issues)}`).toBe(true);
    }
  });

  it('the conversion event and the content interactions travel under their own names, with no alias in the payload', () => {
    for (const type of ['purchase', 'content_impression', 'content_click', 'content_dwell', 'video_complete'] as const) {
      const env = core.envelope(type, { contentId: 'c1', slot: 'hero' });
      expect(env.type).toBe(type);
      expect(env.data).not.toHaveProperty('event');
      expect(env.data).toMatchObject({ contentId: 'c1', slot: 'hero' });
    }
  });
});

// src/routes/sort.test.ts
//
// The pure sorter is covered in sortCandidates.test.ts. This proves the route:
// the shape a commerce platform gets back, parity through the wire, and the two
// refusals.

import { describe, it, expect } from 'vitest';
import { sortRoutes } from '@/routes/sort';

class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string }) { const p = o?.prefix ?? ''; return { keys: [...this.store.keys()].filter((k) => k.startsWith(p)).map((name) => ({ name })) }; }
}

function env(overrides: Record<string, unknown> = {}) {
  return {
    CACHE: new FakeKV(), SESSIONS: new FakeKV(),
    ENVIRONMENT: 'test', CONNECTOR_MODE: 'mock',
    ...overrides,
  } as unknown as Record<string, unknown>;
}

const FEED = [
  { id: 'P1', line: 'Rogue', price_usd: 795 },
  { id: 'P2', line: 'Tabby', price_usd: 380 },
  { id: 'P3', line: 'Tabby', price_usd: 350 },
];

async function post(body: unknown, e = env()) {
  const res = await sortRoutes.request('/', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  }, e);
  return { status: res.status, body: (await res.json()) as Record<string, unknown> };
}

describe('POST /sort', () => {
  it('returns the ids in an order, plus the receipt a commerce team can read', async () => {
    const { status, body } = await post({ userId: 'vis-new', candidates: FEED });
    expect(status).toBe(200);
    expect(body.ok).toBe(true);
    expect(body.order).toEqual(['P1', 'P2', 'P3']);       // no history: the platform's order stands
    expect(body.tenant).toBe('coach');
    expect(typeof body.configVersion).toBe('string');
    expect(Array.isArray(body.items)).toBe(true);
  });

  it('reproduces the feed order at affinity 0, through the wire', async () => {
    const { body } = await post({ userId: 'vis-new', candidates: FEED, weights: { affinity: 0 } });
    expect(body.order).toEqual(['P1', 'P2', 'P3']);
    expect(body.affinityWeight).toBe(0);
  });

  it('refuses a malformed body with 400, not 500', async () => {
    expect((await post({ candidates: FEED })).status).toBe(400);
    expect((await post({ userId: 'v', candidates: 'nope' })).status).toBe(400);
    expect((await post({ userId: 'v', candidates: [{ line: 'x' }] })).status).toBe(400);
  });

  it('bounds the candidate set, because a page of results is not a catalog', async () => {
    const huge = Array.from({ length: 501 }, (_, i) => ({ id: `P${i}` }));
    expect((await post({ userId: 'v', candidates: huge })).status).toBe(400);
  });

  it('refuses a visitor id that addresses another brand, on the DO host', async () => {
    const asked: string[] = [];
    const e = env({
      REFLEX_HOST: 'do',
      SHOPPER_REFLEX: {
        idFromName: (n: string) => { asked.push(n); return n; },
        get: () => ({ fetch: async () => new Response(JSON.stringify({ affinity: { dims: {} } })) }),
      },
    });
    const { status } = await post({ userId: 't:kate-spade:vis-victim', candidates: FEED }, e);
    expect(status).toBe(400);
    expect(asked).toEqual([]);
  });
});

// src/services/SessionManager.identity.test.ts
//
// CW25 on the session host. What matters:
//
//   after a link, the browser's old cookie lands on the person, for reads AND
//   writes, and a write from the browser cannot rename the person;
//   a second device's link folds in, and the person is the sum;
//   a shared computer's second account inherits nothing;
//   logout detaches a browser; only the person's own session erases the person;
//   an import writes interest and claims no visit.

import { describe, it, expect, beforeEach } from 'vitest';
import type { Env } from '@/types/env';
import { SessionManager } from '@/services/SessionManager';
import { DEFAULT_REFLEX_CONFIG, apply, audienceKey, emptyState, snapshot, type ReflexState } from '@/reflex/core';

class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
}

const cfg = DEFAULT_REFLEX_CONFIG;
const SH = 'sh_' + 'a'.repeat(32);
const SH2 = 'sh_' + 'b'.repeat(32);
const T0 = 1_700_000_000_000;

const browse = (values: string[], at: number): ReflexState => {
  let s = emptyState(cfg);
  values.forEach((v, i) => { s = apply(s, { action: 'product_view', touches: [{ dim: 'line', value: v }] }, at + i * 1000, cfg).state; });
  return s;
};

let kv: FakeKV;
let sm: SessionManager;

beforeEach(() => {
  kv = new FakeKV();
  sm = new SessionManager({ SESSIONS: kv } as unknown as Env);
});

/** A browser with a session holding a reflex vector and a few counters. */
async function device(visitorId: string, sessionId: string, values: string[], at: number) {
  await sm.createOrUpdateSession(sessionId, visitorId, {
    reflex: browse(values, at), attributes: { product_views: values.length, viewed_product_line: values.at(-1) },
  });
  return sessionId;
}

describe('absorbIntoShopper: the first link', () => {
  it('creates the person from the browser, forwards the browser, repoints its user key', async () => {
    await device('vis-phone', 's-phone', ['Tabby', 'Tabby', 'Tabby'], T0);
    const r = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 5000 });
    expect(r.created).toBe(true);
    expect(r.data.userId).toBe(SH);
    expect(r.data.identity?.shopperId).toBe(SH);
    expect(r.data.reflex?.audiences).toContain(audienceKey('line', 'Tabby'));
    // The browser's record forwards; its content underneath is untouched.
    const tomb = await sm.readRaw('s-phone');
    expect(tomb?.forwardTo).toBe(r.sessionId);
    expect(tomb?.userId).toBe('vis-phone');
    expect(await sm.resolveSessionIdByUserId('vis-phone')).toBe(r.sessionId);
    expect(await sm.resolveSessionIdByUserId(SH)).toBe(r.sessionId);
  });

  it('the old cookie reads the person, and a write from the browser lands on the person without renaming it', async () => {
    await device('vis-phone', 's-phone', ['Tabby', 'Tabby', 'Tabby'], T0);
    const r = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 5000 });
    expect((await sm.getSession('s-phone'))?.userId).toBe(SH);

    const written = await sm.createOrUpdateSession('s-phone', 'vis-phone', { attributes: { last_page_path: '/bags' } });
    expect(written.userId).toBe(SH);                         // the person's id survived the browser's write
    expect(written.attributes.last_page_path).toBe('/bags');
    const person = await sm.readRaw(r.sessionId);
    expect(person?.attributes.last_page_path).toBe('/bags'); // it landed on the person
    expect((await sm.readRaw('s-phone'))?.attributes.last_page_path).toBeUndefined(); // not on the tombstone
  });
});

describe('absorbIntoShopper: the second device', () => {
  it('folds in: the person is the sum of both devices', async () => {
    await device('vis-phone', 's-phone', ['Tabby', 'Tabby'], T0);
    await device('vis-laptop', 's-laptop', ['Rogue', 'Rogue', 'Tabby'], T0 + 2000);
    const first = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 6000 });
    const second = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-laptop'), fromSessionId: 's-laptop', config: cfg, now: T0 + 7000 });
    expect(second.created).toBe(false);
    expect(second.sessionId).toBe(first.sessionId);
    const snap = snapshot(second.data.reflex!, T0 + 7000, cfg);
    // Three Tabby touches across two devices: over the threshold, where each device alone was not.
    expect(snap.dims.line.Tabby).toBeGreaterThanOrEqual(cfg.thetaIn);
    expect(snap.dims.line.Rogue).toBeGreaterThan(0);
    expect(second.data.attributes.product_views).toBe(5);      // counters add
    expect(second.data.metadata.visitCount).toBe(2);            // one visit per device, one person
    expect(second.data.metadata.firstSeen).toBeLessThanOrEqual(first.data.metadata.firstSeen);
    expect(await sm.resolveSessionIdByUserId('vis-laptop')).toBe(first.sessionId);
  });

  it('a browser already forwarding here folds nothing twice', async () => {
    await device('vis-phone', 's-phone', ['Tabby', 'Tabby'], T0);
    const a = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 6000 });
    const b = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 6001 });
    expect(b.data.attributes.product_views).toBe(a.data.attributes.product_views);
    expect(b.data.reflex!.dims.line.Tabby.s).toBeCloseTo(a.data.reflex!.dims.line.Tabby.s, 9);
  });
});

describe('a shared computer', () => {
  it('repoint: the second account inherits nothing of the first', async () => {
    await device('vis-shared', 's-shared', ['Tabby', 'Tabby', 'Tabby'], T0);
    await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-shared'), fromSessionId: 's-shared', config: cfg, now: T0 + 5000 });
    const second = await sm.absorbIntoShopper({ shopperId: SH2, from: await sm.readRaw('s-shared'), fromSessionId: 's-shared', config: cfg, now: T0 + 9000, mode: 'repoint' });
    expect(second.created).toBe(true);
    expect(second.data.reflex?.dims).toEqual({});
    expect(second.data.attributes).toEqual({});
    expect((await sm.readRaw('s-shared'))?.forwardTo).toBe(second.sessionId);
    expect(await sm.resolveSessionIdByUserId('vis-shared')).toBe(second.sessionId);
  });
});

describe('leaving', () => {
  it('deleting the browser session detaches the browser and leaves the person whole', async () => {
    await device('vis-phone', 's-phone', ['Tabby'], T0);
    const r = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 5000 });
    await sm.deleteSession('s-phone');
    expect(await sm.readRaw('s-phone')).toBeNull();
    expect(await sm.resolveSessionIdByUserId('vis-phone')).toBeNull();
    expect((await sm.readRaw(r.sessionId))?.userId).toBe(SH);
    expect(await sm.resolveSessionIdByUserId(SH)).toBe(r.sessionId);
  });

  it("deleting the person's own session erases the person", async () => {
    await device('vis-phone', 's-phone', ['Tabby'], T0);
    const r = await sm.absorbIntoShopper({ shopperId: SH, from: await sm.readRaw('s-phone'), fromSessionId: 's-phone', config: cfg, now: T0 + 5000 });
