describe('W34.01 deployment-off external scoring on the actual service', () => {
  const reason = 'external scoring disabled by deployment policy';
  const snapshot = { affinity: { dims: { line: { Drover: 0.9 } } } };
  const configurations: NonNullable<LearnConfig['external']>[] = [
    { kind: 'service', ref: 'https://synthetic.invalid/score', timeoutMs: 50, fallback: 'omit' },
    { kind: 'service', ref: 'MODEL', timeoutMs: 50, fallback: 'omit' },
    { kind: 'workers_ai', ref: 'synthetic-model', timeoutMs: 50, fallback: 'omit' },
    { kind: 'table', ref: 'synthetic-table', timeoutMs: 50, fallback: 'omit' },
  ];

  beforeEach(() => { invalidateCache(); invalidateLiftCache(); });
  afterEach(() => { vi.unstubAllGlobals(); });

  it.each(configurations)('withdraws $kind / $ref despite a valid positive-weight stored document', async (external) => {
    const { env, ring, shopper } = await envWith(snapshot, {
      holdout: { share: 0, salt: '', arms: ['default'] },
      external, slots: { hero: { external: { weight: 0.5 } } },
    });
    // All adapters would succeed and favour b if the live service invoked one.
    const answer = { version: 'synthetic-v1', scores: { b: 1 } };
    const fetchCall = vi.fn(async () => Response.json(answer));
    const bindingCall = vi.fn(async () => Response.json(answer));
    const aiCall = vi.fn(async () => answer);
    const bindingRead = vi.fn(() => ({ fetch: bindingCall }));
    const aiRead = vi.fn(() => ({ run: aiCall }));
    vi.stubGlobal('fetch', fetchCall);
    Object.defineProperties(env, { MODEL: { get: bindingRead }, AI: { get: aiRead } });
    const kv = env.CACHE as unknown as FakeKV;
    kv.store.set('ext:coach:coach', JSON.stringify(answer));

    const out = await serve(env);
    await out.afterResponse;
    const rec = out.records[0]!;
    expect(out.sources.learn.revision).toBe(1);
    expect(out.arm).toBe('personalized');
    expect(rec.item_id).toBe('a');
    expect(rec.explain.score_final).toBeCloseTo(0.45, 3);
    expect(out.sources.external).toEqual({ kind: external.kind, ref: external.ref, ok: false, ms: 0, version: null, reason });
    expect(rec.explain.external).toEqual({ kind: external.kind, ref: external.ref, status: 'unavailable', reason });
    expect(rec.inputs?.external).toBeUndefined();
    expect(rec.explain.drivers.some((driver) => driver.dim === 'external')).toBe(false);
    expect(kv.reads.filter((key) => key.startsWith('ext:'))).toEqual([]);
    for (const call of [fetchCall, bindingCall, aiCall, bindingRead, aiRead]) expect(call).not.toHaveBeenCalled();
    expect(shopper).toEqual(['v1 GET /snapshot']);
    expect(ring).toEqual(['coach:v1 POST /append']);

    if (external.kind === 'table') {
      const replay = await replayDecision(env, rec);
      expect(replay).toMatchObject({ ok: true, equal: true, diff: [] });
      expect(replay.replayed?.explain.external).toEqual(rec.explain.external);
      expect(kv.reads.filter((key) => key.startsWith('ext:'))).toEqual([]);
    }
  });

  it.each(['zero weight', 'default arm'])('keeps an inactive term absent: %s', async (mode) => {
    const { env } = await envWith(snapshot, {
      holdout: { share: mode === 'default arm' ? 1 : 0, salt: '', arms: ['default'] },
      external: configurations[0], slots: { hero: { external: { weight: mode === 'zero weight' ? 0 : 0.5 } } },
    });
    const fetchCall = vi.fn(async () => Response.json({ version: 'unused', scores: { b: 1 } }));
    vi.stubGlobal('fetch', fetchCall);
    const out = await serve(env);
    await out.afterResponse;
    expect(out.arm).toBe(mode === 'default arm' ? 'default' : 'personalized');
    expect(out.records[0]!.item_id).toBe('a');
    expect(out.sources.external).toBeNull();
    expect(out.records[0]!.explain.external).toBeUndefined();
    expect(out.records[0]!.inputs?.external).toBeUndefined();
    expect(fetchCall).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCore } from './core';
import { testHost } from './testHost';

describe('core', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('builds the envelope the storefront sends, field for field', () => {
    const { host } = testHost();
    const core = createCore({ tenant: 'coach', source: 'coach-storefront', surface: 'coach' }, host);
    const env = core.envelope('product_view', { productId: 'SKU-1' });
    expect(Object.keys(env)).toEqual(['type', 'userId', 'anonymousId', 'sessionId', 'data', 'source', 'surface', 'entry', 'timestamp']);
    expect(env.userId).toMatch(/^vis-/);
    expect(env.anonymousId).toMatch(/^v-[A-Z0-9]{9}$/);
    expect(env.sessionId).toMatch(/^s-[A-Z0-9]+$/);
    expect(env.data).toEqual({ productId: 'SKU-1' });
    expect(env.entry).toEqual({ utmMedium: 'paid_social', utmSource: 'tiktok', referrer: 'https://www.tiktok.com/', siteHost: 'shop.example' });
    expect(env.timestamp).toBe(1_725_000_000_000);
    expect(Object.keys(createCore({ tenant: 'coach' }, host).envelope('page_view'))).not.toContain('surface');
  });

  it('POSTs to /realtime/action with credentials, applies the update, and reports the receipt', async () => {
    const { host, calls } = testHost({ responses: () => ({ success: true, update: { data: { timestamp: 7, segments: ['evening_affinity'] } }, odp: { receiptId: 'r1' } }) });
    const core = createCore({ tenant: 'coach', sdkKey: 'k-1' }, host);
    const updates: unknown[] = [], receipts: unknown[] = [], sent: unknown[] = [];
    core.on('update', (u, m) => updates.push([u, m])); core.on('receipt', (r) => receipts.push(r)); core.on('sent', (_e, m) => sent.push(m));
    const out = await core.send('add_to_cart', { productId: 'SKU-1' });
    expect(calls[0]?.url).toBe('https://shop.example/realtime/action');
    expect(calls[0]?.init).toMatchObject({ method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'X-SDK-Key': 'k-1' } });
    expect(JSON.parse(calls[0]!.init!.body!)).toMatchObject({ type: 'add_to_cart', data: { productId: 'SKU-1' } });
    expect(out).toEqual({ timestamp: 7, segments: ['evening_affinity'] });
    expect(updates).toEqual([[{ timestamp: 7, segments: ['evening_affinity'] }, { fromPush: false, rttMs: 0 }]]);
    expect(receipts).toEqual([{ receiptId: 'r1' }]);
    expect(sent).toEqual([{ via: 'fetch' }]);
  });

  it('a failed POST resolves null and never throws', async () => {
    const { host } = testHost();
    host.fetch = async () => { throw new Error('offline'); };
    const core = createCore({ tenant: 'coach' }, host);
    await expect(core.send('page_view')).resolves.toBeNull();
  });

  it('uses the beacon when asked and available', async () => {
    const { host, calls, beacons } = testHost();
    const core = createCore({ tenant: 'coach' }, host);
    await core.send('purchase', { orderId: 'o1', value: 10 }, { beacon: true });
    expect(beacons).toHaveLength(1);
    expect(JSON.parse(beacons[0]!.body)).toMatchObject({ type: 'purchase', data: { orderId: 'o1' } });
    expect(calls).toHaveLength(0);
  });

  it('opens the socket on the visitor id, heartbeats, dedupes the echo, reconnects on close', async () => {
    const { host, sockets } = testHost({ responses: () => ({ update: { data: { timestamp: 42, segments: ['a'] } } }) });
    const core = createCore({ tenant: 'coach', heartbeatMs: 1000, reconnectMs: 500 }, host);
    const status: string[] = []; core.on('socket', (s) => status.push(s));
    const updates: unknown[] = []; core.on('update', (u) => updates.push(u));
    core.connect();
    expect(sockets[0]?.url).toBe(`wss://shop.example/realtime/ws?userId=${encodeURIComponent(core.visitorId)}`);
    sockets[0]!.open();
    sockets[0]!.receive({ type: 'connected', userId: core.visitorId });
    expect(core.socketStatus).toBe('connected');
    vi.advanceTimersByTime(1000);
    expect(sockets[0]!.sent).toEqual([JSON.stringify({ type: 'heartbeat' })]);
    // The action's response applies once; the socket echo with the same timestamp is dropped.
    await core.send('product_view', { productId: 'x' });
    sockets[0]!.receive({ type: 'personalization_update', data: { timestamp: 42, segments: ['a'] } });
    expect(updates).toHaveLength(1);
    sockets[0]!.receive({ type: 'personalization_update', data: { timestamp: 43, segments: ['b'], decisionMs: 12 } });
    expect(updates).toHaveLength(2);
    // Content decisions and receipts are their own events.
    const decisions: unknown[] = []; core.on('decisions', (d) => decisions.push(d));
    sockets[0]!.receive({ type: 'content_decisions', page: 'home', decisions: [] });
    expect(decisions).toHaveLength(1);
    sockets[0]!.close();
    expect(core.socketStatus).toBe('reconnecting');
    vi.advanceTimersByTime(500);
    expect(sockets).toHaveLength(2);
    core.disconnect();
    expect(core.socketStatus).toBe('closed');
    expect(status[0]).toBe('connecting');
  });

  it('reports the socket as unavailable when the host has none', () => {
    const { host } = testHost({ withSocket: false });
    const core = createCore({ tenant: 'coach' }, host);
    core.connect();
    expect(core.socketStatus).toBe('unavailable');
  });
});

// src/sdk/identify.test.ts
// CW25, the client half: identify() and logout() against the contract in
// docs/architecture/25-identity-stitching.md §4, with the server faked.

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCore } from './core';
import { createIdentity, type IdentifyOptions } from './identify';
import { testHost } from './testHost';
import type { ClientConfig, Host } from './types';

// The client's identify() and logout() are one-line delegations to this pair; index.ts pulls the
// browser host (DOM types) into the root typecheck, so the test builds the pair the way the client does.
function createClient(config: ClientConfig, host: Host) {
  const core = createCore(config, host);
  const identity = createIdentity(core);
  return { core, get visitorId() { return core.visitorId; }, connect: () => core.connect(), on: core.on, identify: identity.identify, logout: identity.logout };
}

const LINK = 'https://shop.example/v1/coach/identity/link';
const DETACH = 'https://shop.example/v1/coach/identity/detach';

describe('identify and logout', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('posts the contract, stores the shopper id in both stores, reconnects the socket under it, and says so', async () => {
    const { host, calls, sockets } = testHost({ responses: (url) => (url === LINK ? { ok: true, shopperId: 'shp-9', carry: 'shp-9', outcome: 'linked' } : { ok: true }) });
    const client = createClient({ tenant: 'coach', sdkKey: 'k-1' }, host);
    const before = client.visitorId;
    expect(before).toMatch(/^vis-/);
    client.connect();
    expect(sockets).toHaveLength(1);
    expect(sockets[0]!.url).toContain(`userId=${before}`);
    const changes: unknown[] = [];
    client.on('identity', (c) => changes.push(c));
    const r = await client.identify('acct-42', { source: 'login', exp: 1_800_000_000, assertion: 'sig' });
    expect(r).toEqual({ ok: true, shopperId: 'shp-9', visitorId: 'shp-9', outcome: 'linked', retried: false });
    const link = calls.find((c) => c.url === LINK)!;
    expect(link.init).toMatchObject({ method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'X-SDK-Key': 'k-1' } });
    expect(JSON.parse(link.init!.body!)).toEqual({ visitorId: before, accountId: 'acct-42', source: 'login', exp: 1_800_000_000, assertion: 'sig' });
    expect(client.visitorId).toBe('shp-9');
    expect(host.storage.get('opt_visitor_id')).toBe('shp-9');
    expect(host.cookie.get('opt_visitor_id')).toBe('shp-9');
    expect(sockets).toHaveLength(2);
    expect(sockets[1]!.url).toContain('userId=shp-9');
    expect(changes).toEqual([{ visitorId: 'shp-9', previous: before, reason: 'identified' }]);
    // every later event is the person's
    expect(client.core.envelope('page_view').userId).toBe('shp-9');
  });

  it('a refused link changes nothing', async () => {
    const { host, sockets } = testHost({ responses: () => ({ ok: false, error: 'assertion invalid' }) });
    host.fetch = async () => ({ ok: false, status: 401, json: async () => ({ ok: false, error: 'assertion invalid' }) });
    const client = createClient({ tenant: 'coach' }, host);
    const before = client.visitorId;
    const r = await client.identify('acct-42');
    expect(r).toEqual({ ok: false, status: 401, error: 'assertion invalid', retried: false });
    expect(client.visitorId).toBe(before);
    expect(sockets).toHaveLength(0);
    expect(await client.identify('')).toMatchObject({ ok: false, error: 'accountId required' });
  });

  it('logout detaches, mints a fresh anonymous id, and reconnects under it', async () => {
    const { host, calls, sockets } = testHost({ responses: (url) => (url === LINK ? { ok: true, carry: 'shp-9' } : { ok: true, detached: true }) });
    const client = createClient({ tenant: 'coach' }, host);
    client.connect();
    await client.identify('acct-42');
    expect(client.visitorId).toBe('shp-9');
    const out = await client.logout();
    expect(out.ok).toBe(true);
    expect(calls.find((c) => c.url === DETACH)).toBeTruthy();
    expect(client.visitorId).toMatch(/^vis-/);
    expect(client.visitorId).not.toBe('shp-9');
    expect(host.storage.get('opt_visitor_id')).toBe(client.visitorId);
    expect(sockets[sockets.length - 1]!.url).toContain(`userId=${client.visitorId}`);
  });

  it('on 409 the previous person is logged out and the link is retried once with the fresh id', async () => {
    const { host, calls } = testHost();
    let uuid = 0;
    host.uuid = () => `fresh-${++uuid}`;
    let links = 0;
    host.fetch = async (url, init) => {
      calls.push({ url, init });
      if (url === LINK) {
        links += 1;
        const body = JSON.parse(String(init?.body)) as { visitorId: string };
        if (links === 1) return { ok: false, status: 409, json: async () => ({ ok: false, error: 'this browser already carries a shopper id; detach first' }) };
        return { ok: true, status: 200, json: async () => ({ ok: true, carry: 'shp-2', linkedFrom: body.visitorId }) };
      }
      return { ok: true, status: 200, json: async () => ({ ok: true, detached: true }) };
    };
    host.storage.set('opt_visitor_id', 'shp-1');                              // the previous person never logged out
    const client = createClient({ tenant: 'coach' }, host);
    expect(client.visitorId).toBe('shp-1');
    const provider = vi.fn(({ visitorId }: { visitorId: string }) => ({ assertion: `proof-${visitorId}`, exp: 1_800_000_000 }));
    const r = await client.identify('acct-2', { getAssertion: provider });
    expect(r).toMatchObject({ ok: true, shopperId: 'shp-2', retried: true });
    const linkCalls = calls.filter((c) => c.url === LINK).map((c) => JSON.parse(String(c.init?.body)) as { visitorId: string });
    expect(linkCalls[0]!.visitorId).toBe('shp-1');
    expect(linkCalls[1]!.visitorId).toMatch(/^vis-/);                        // never the old shopper id again
    expect(calls.some((c) => c.url === DETACH)).toBe(true);
    expect(client.visitorId).toBe('shp-2');
    expect(provider).toHaveBeenCalledTimes(2);
  });
});

describe('W04.01 backend proof provider and captured visitor', () => {
  it('uses synchronous provider proof over static fields and never falls back on invalid/throwing providers', async () => {
    const { host, calls } = testHost({ responses: () => ({ ok: true, carry: 'shp-signed' }) });
    const client = createClient({ tenant: 'coach' }, host), visitorId = client.visitorId;
    const provider = vi.fn(() => ({ assertion: 'fresh-proof', exp: 1_800_000_000 }));
    expect(await client.identify('acct', { assertion: 'static', exp: 1, getAssertion: provider })).toMatchObject({ ok: true, retried: false });
    expect(provider).toHaveBeenCalledWith({ tenant: 'coach', visitorId, accountId: 'acct' });
    expect(JSON.parse(String(calls[0]!.init?.body))).toMatchObject({ visitorId, assertion: 'fresh-proof', exp: 1_800_000_000 });

    const invalid = [
      () => { throw new Error('W0401_PRIVATE_PROVIDER_ERROR'); },
      () => undefined, () => ({}), () => ({ assertion: ' ', exp: 1 }),
      () => ({ assertion: 'proof', exp: NaN }), () => ({ assertion: 'proof', exp: 1.5 }),
      'not-a-provider',
    ];
    for (const getAssertion of invalid) {
      const fixture = testHost();
      const c = createClient({ tenant: 'coach' }, fixture.host), before = c.visitorId;
      const result = await c.identify('acct', { assertion: 'static', exp: 1_800_000_000, getAssertion: getAssertion as unknown as IdentifyOptions['getAssertion'] });
      expect(result).toMatchObject({ ok: false, status: 0, retried: false });
      expect(JSON.stringify(result)).not.toContain('W0401_PRIVATE');
      expect(fixture.calls).toEqual([]); expect(c.visitorId).toBe(before);
    }
  });

  it('does not detach on static409, and failed detach or fresh proof prevents a retry', async () => {
    for (const detached of [null, { status: 500, json: { ok: true, detached: true } },
      { status: 200, json: { ok: false, detached: true } }, { status: 200, json: { ok: true, detached: false } },
      { status: 200, json: null }, { status: 200, json: { ok: true, detached: true } }]) {
      const { host, calls } = testHost();
      let uuid = 0; host.uuid = () => `fresh-${++uuid}`;
      host.fetch = async (url, init) => {
        calls.push({ url, init });
        if (url === LINK) return { ok: false, status: 409, json: async () => ({ ok: false, error: 'conflict' }) };
        return { ok: detached?.status === 200, status: detached?.status ?? 500, json: async () => detached?.json };
      };
      const client = createClient({ tenant: 'coach' }, host), before = client.visitorId;
      let proofs = 0;
      const provider = () => { if (++proofs > 1) throw new Error('W0401_PRIVATE_FRESH_PROOF'); return { assertion: 'proof', exp: 1_800_000_000 }; };
      const result = await client.identify('acct', { assertion: 'static', exp: 1_800_000_000, ...(detached ? { getAssertion: provider } : {}) });
      expect(result.ok).toBe(false); expect(result.retried).toBe(false);
      expect(calls.filter(c => c.url === LINK)).toHaveLength(1);
      expect(calls.filter(c => c.url === DETACH)).toHaveLength(detached ? 1 : 0);
      const successfulDetach = detached?.status === 200 && detached.json?.ok === true && detached.json.detached === true;
      expect(proofs).toBe(detached ? successfulDetach ? 2 : 1 : 0);
      if (successfulDetach) expect(client.visitorId).not.toBe(before);
      else expect(client.visitorId).toBe(before);
      expect(JSON.stringify(result)).not.toContain('W0401_PRIVATE');
    }
    // Even a second conflict is returned; it cannot start another detach cycle.
    const { host, calls } = testHost();
    let uuid = 0; host.uuid = () => `fresh-${++uuid}`;
    host.fetch = async (url, init) => { calls.push({ url, init }); return url === LINK
      ? { ok: false, status: 409, json: async () => ({ ok: false, error: 'conflict' }) }
      : { ok: true, status: 200, json: async () => ({ ok: true, detached: true }) }; };
    const client = createClient({ tenant: 'coach' }, host);
    expect(await client.identify('acct', { getAssertion: () => ({ assertion: 'proof', exp: 1_800_000_000 }) }))
      .toMatchObject({ ok: false, status: 409, retried: true });
    expect(calls.map(c => c.url)).toEqual([LINK, DETACH, LINK]);
  });

  it('rejects changed visitors while proof, link or detach is pending', async () => {
    for (const phase of ['proof', 'link', 'detach']) {
      let release!: () => void, entered!: () => void;
      const gate = new Promise<void>(resolve => { release = resolve; });
      const ready = new Promise<void>(resolve => { entered = resolve; });
      const { host, calls } = testHost();
      host.fetch = async (url, init) => {
        calls.push({ url, init });
        if ((phase === 'link' && url === LINK) || (phase === 'detach' && url === DETACH)) { entered(); await gate; }
        if (phase === 'detach' && url === LINK) return { ok: false, status: 409, json: async () => ({ ok: false, error: 'conflict' }) };
        return { ok: true, status: 200, json: async () => ({ ok: true, carry: 'stale-shopper', detached: true }) };
      };
      const client = createClient({ tenant: 'coach' }, host);
      const pending = client.identify('acct', { getAssertion: async () => {
        if (phase === 'proof') { entered(); await gate; }
        return { assertion: 'proof', exp: 1_800_000_000 };
      } });
      await ready;
      client.core.setVisitorId('vis-newer-identity', 'logout');
      release();
      expect(await pending).toMatchObject({ ok: false, status: 0, error: 'identity changed during identify', retried: false });
      expect(client.visitorId).toBe('vis-newer-identity');
      expect(calls.filter(c => c.url === LINK)).toHaveLength(phase === 'proof' ? 0 : 1);
    }
  });

  it('checks the caller continuation after attempt resolves, before detach or carry adoption', async () => {
    for (const status of [200, 409]) {
      const { host, calls } = testHost();
      host.fetch = async (url, init) => { calls.push({ url, init }); return {
        ok: status === 200, status, json: async () => ({ ok: status === 200, carry: 'stale-shopper', error: 'conflict' }),
      }; };
      const client = createClient({ tenant: 'coach' }, host);
      const post = client.core.postJson;
      client.core.postJson = async (path, body) => {
        const response = await post(path, body);
        // Change identity after attempt's await resumes but before identify's await resumes.
        queueMicrotask(() => queueMicrotask(() => client.core.setVisitorId('vis-newer-identity', 'logout')));
        return response;
      };
      expect(await client.identify('acct', { getAssertion: () => ({ assertion: 'proof', exp: 1_800_000_000 }) }))
        .toMatchObject({ ok: false, status: 0, error: 'identity changed during identify' });
      expect(client.visitorId).toBe('vis-newer-identity'); expect(calls.map(c => c.url)).toEqual([LINK]);
    }
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCore } from './core';
import { createListen } from './listen';
import { testHost } from './testHost';

const snapshot = {
  ok: true, page: 'home', arm: 'personalized', versions: { config: 41, lift: 0, prior: 0, policy: 0 }, config_label: 'reflex-demo-v1+r41',
  decisions: [
